// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Пресвятій Богородиці перед іконою «Знамення» Курська Корінна","e":"Akathist to the Theotokos before her icon “The Sign” of Kursk-Root","secs":[{"h":"Кондак 1","ps":["Ізбра́нной Воєво́ді і благо́й Одиги́трії, путеводя́щей нас к Небе́сному Гра́ду, прийді́те, припаде́м всі, гра́да зді пребива́ющаго не іму́щії, Тоя́ всеси́льнаго заступле́нія прося́ще, чудеса́ же, от літ дре́вніх да́же дони́ні от іко́ни Єя́ бива́ємия, помина́юще, велегла́сно возопії́м:","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Ікос 1","ps":["А́нгели удиви́шася, зря́ще Тя, Влади́чице, іко́ною Твоє́ю, я́ко столпо́м о́гненним, нам предходя́щую во вели́ком ісхо́ді на́шем із землі́, беззако́нники порабоще́нния. Не Мойсе́я бо, но Са́мую Тя і́мами Путеводи́тельницю в ско́рбнем стра́нствованії на́шем, ті́мже Ті благода́рні зове́м:","Ра́дуйся, благослове́нная Одиги́тріє;","ра́дуйся, і́стиннаго Путі́ Ма́ти.","Ра́дуйся, сквозі́ пусти́ню ми́ра сего́ нас провожда́ющая;","ра́дуйся, Амали́ка ми́сленнаго пресла́вно побіжда́ющая.","Ра́дуйся, істо́чники благода́ті от іко́ни Твоєя́ істоча́ющая;","ра́дуйся, зако́н Си́на Твоєго́, Христа́ Бо́га на́шего, на скрижа́ліх серде́ць на́ших напису́ющая.","Ра́дуйся, зно́єм страсте́й пали́мих благода́тноє окропле́ніє;","ра́дуйся, ізнемога́ющих всемо́щноє укріпле́ніє.","Ра́дуйся, серде́ць см'яте́нних тиша́йшая усла́до;","ра́дуйся, стра́нних і си́рих Боже́ственная отра́до.","Ра́дуйся, зе́млю обітова́нную нам приуготовля́ющая;","ра́дуйся, небе́снаго Ієрусали́ма врата́ нам отверза́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 2","ps":["Ви́діхом, ви́діхом ви́ну чудеса́ і зна́менія Твоя́, Влади́чице, іспові́дуєм ми́лость, не таї́м благодія́ній Твої́х, оба́че велегла́сно вопіє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Бо́жий кто пости́же і та́йну суде́б Єго́ кто пові́сть? Возво́дить бо і низво́дить, смиря́єть і возно́сить, поража́єть і ісціля́єть, і кто бисть сові́тник Єму́? Ті́мже і нас, гріх на́ших ра́ди, смири́ і ца́рство на́ше низложи́, си́ни на́ша по всему́ лицю́ землі́ разсе́яв. Ко кому́ у́бо прибі́гнем в ско́рбі на́шей, ко кому́ ру́ці простре́м, а́ще не к Тебі́, Всеблага́я. Оба́че се́рдцем сокруше́нним вопіє́м Ті такова́я:","Ра́дуйся, Си́на Твоєго́ за нас умоля́ющая;","ра́дуйся, пра́ведний гнів Бо́жий утоля́ющая.","Ра́дуйся, беззако́ній на́ших очище́ніє;","ра́дуйся, грі́шним Хода́тайце проще́нія.","Ра́дуйся, світи́льник упова́нія неме́ркнущий нам возже́гшая;","ра́дуйся, во ісхо́ді і стра́нствованії на́шем іко́ною Твоє́ю нам предте́кшая.","Ра́дуйся, вся разсі́янния воєди́но собира́ющая;","ра́дуйся, омофо́ром Твої́м светообра́зним вся покрива́ющая.","Ра́дуйся, раздо́ри і нестроє́нія умиря́ющая;","ра́дуйся, сові́ти нечести́вих разоря́ющая.","Ра́дуйся, пла́вающих в жите́йськом мо́ре окормля́ющая;","ра́дуйся, попече́нієм Твої́м ні єди́наго же оставля́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 3","ps":["Си́ли Тобо́ю ді́ються і благода́ть от честни́я іко́ни Твоєя́ неоску́дно ізлива́ється, Преблагослове́нная Ді́во, вся подвиза́я о Тебі́ вопи́ти: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи милосе́рдіє неізрече́нноє, та́мо благода́ть Твою́ возсіява́єши, Всеблага́я, іді́же тьма огустева́єть і ско́рби преумножа́ються, ті́мже не оста́вила єси́ нас си́рих, оба́че во іко́ні Твоє́й к нам убо́гим пришла́ єси́, сла́в'ящим Твоє́ снисхожде́ніє і вопію́щим си́це:","Ра́дуйся, чуде́с мо́ре;","ра́дуйся, ми́лости пучи́но.","Ра́дуйся, благода́ті приснотеку́щий істо́чниче;","ра́дуйся, ісціле́ній кла́дезю неісчерпа́ємий.","Ра́дуйся, єстества́ уста́ви побіди́вшая;","ра́дуйся, зако́ни єсте́ственния преміни́вшая.","Ра́дуйся, ско́рби на́ша на ра́дость прелага́ющая;","ра́дуйся, плач і стена́ніє во весе́ліє духо́вноє претворя́ющая.","Ра́дуйся, озлобле́нія і бі́ди на по́льзу нам обраща́ющая;","ра́дуйся, враги́ на́ша пресла́вно смиря́ющая.","Ра́дуйся, ча́янія враго́в посрамля́ющая;","ра́дуйся, пою́щия Тя возвеселя́ющая.","Ра́дуйся Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 4","ps":["Бу́ри іскуше́ній, на нас находя́щия, ско́рбем же і болі́знем, нас посеща́ющим, єгда́ терпі́нію в нас оскудіва́ти і ду́ху на́шему смуща́тися, притеце́м ко о́бразу Пречи́стая Ді́ви і сле́зи точа́ще Той, от се́рдця возопії́м: Богоно́снеї ру́ці Твої́ нам простира́ющи, із глубини́ зол возведи́ ни, я́ко да благода́рними усти́ зове́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаху дре́вле лю́діє украї́нськії слух явле́нія свята́го Твоєго́ о́браза в дубра́ві Ку́рстей і те́кше к нему́ со тща́нієм, уми́льно взива́ху: «Отку́ду нам сіє́, да при́йде к нам Ма́ти Го́спода на́шего», узрі́в же іко́ну Твою́, Влади́чице, при ко́рене древе́снем лежа́щую, і приє́мше ю, я́ко сокро́вище вели́коє, возопи́ша Тебі́, Первообра́зній:","Ра́дуйся, раю́ світлі́йшій, дре́во Жи́зні ізрасти́вший;","ра́дуйся, вертогра́ді Боже́ственний, дре́во Це́ркві прозя́бший.","Ра́дуйся, Цві́те благово́нний, мир весь облагоуха́яй;","ра́дуйся, кри́не непоро́чний, вселе́нную украша́яй.","Ра́дуйся, лозо́ благопло́дная, вино́м умиле́нія всіх напоі́вшая;","ра́дуйся, розго́ освяще́нная, плоди́ сла́достними род челові́чеський напита́вшая.","Ра́дуйся, ко́реню домострої́тельства Бо́жия;","ра́дуйся, спасе́нія на́шего верх і глави́зно.","Ра́дуйся, зли́я на́ші стра́сті із ко́рене посека́ющая;","ра́дуйся, доброді́телей сад насажда́ющая.","Ра́дуйся, до́бриє оби́чаї в нас вкореня́ющая;","ра́дуйся, прича́стники ра́йськия жи́зні би́ти нас сподобля́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́б'ящеся, іко́на Твоя́ честна́я, Госпоже́, зе́млю Ру́ськую і гра́ди єя́ обтека́ше, ца́ріє сей благогові́йно поклоня́хуся, цари́ці любо́вію ту благоукраша́ху, архієре́ї стра́хом сріта́ху, ві́рних же мно́жества, духо́вно торжеству́юще, вопія́ху: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще безбо́жников безу́мний сові́т іко́ну Твою́, Пречи́стая, разори́ти, от Тебе́, Ді́во, посра́мленний, і обрі́тше о́браз Твой святи́й, от вся́каго ді́йства сокруши́тельна невреди́м, мона́си і мирсті́ї стра́хом і любо́вію возопи́ша Ті сицева́я:","Ра́дуйся, крі́посте несокруши́мая;","ра́дуйся, стіно́ неруши́мая.","Ра́дуйся, лю́тих безбо́жников сові́т посрами́вшая;","ра́дуйся, ча́янія враго́в осуєти́вшая.","Ра́дуйся, хули́телей уста́ загради́вшая;","ра́дуйся, іко́ну Твою́ святу́ю невреди́мо сохра́ншая.","Ра́дуйся, от руки́ злоде́йськой сія́ соблю́дшая;","ра́дуйся, о́чі Твої́ от скве́рних діл челові́чеських обраща́ющая.","Ра́дуйся, лиця́ Твоєго́ Пречи́стаго от нас, убо́гих, не отвраща́ющая;","ра́дуйся, із руки́ дия́воли грі́шния ісхища́ющая.","Ра́дуйся, проще́ніє ка́ющимся возсіява́ющая;","ра́дуйся, две́рі милосе́рдія Бо́жия хода́тайством Твої́м отверза́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть мир весь ми́лости, от іко́ни Твоєя́ ізлива́ємия, Всецари́це! Отне́лиже бо ізшла́ єси́ то́ю із землі́ Ру́ськия, ність град, ніже́ весь, в ни́хже не бі явля́єма си́ла Твоя́. Ті́мже от всіх язи́к спасе́ннії і Тобо́ю вопію́ть благода́рно Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́й нам па́ки світ упова́нія, Богоро́дице Пречи́стая, зарю́ спасе́нія ми́ру возвісти́вшая во Твоє́м рождестві́. Не преда́ждь нас до конця́ в ру́ці враго́в на́ших і сові́ти нечести́вих і лю́тих отсту́пников ско́ро разори́. Да бу́деть і страна́ на́ша Украї́нськая, я́коже дре́вле дом Твой, да процвіте́ть в ней благоче́стіє, святи́я оби́телі і хра́ми да благоукра́сяться, лю́діє же, от лю́тих безбо́жников ізба́вльшеся, да торжеству́ють с весе́лієм, сла́в'яще Твоє́ заступле́ніє і зову́ще Ті такова́я:","Ра́дуйся, любо́вію Твоє́ю всему́ ми́ру возсія́вшая;","ра́дуйся, із уст Боже́ственних Си́на Твоєго́ всиновле́ніє ро́да челові́чеськаго прия́вшая.","Ра́дуйся, Ма́ти Бо́жия і Ма́ти христия́ном;","ра́дуйся, неду́гов от'я́тіє і Ціли́тельнице ра́нам.","Ра́дуйся, в темни́цях су́щих незаходи́мий Сві́те;","ра́дуйся, у́зников отра́до і простра́нство кле́тей.","Ра́дуйся, за пра́вду гони́мих дерзнове́ніє;","ра́дуйся, за ві́ру стра́ждущих терпі́ніє.","Ра́дуйся, му́чеников вінча́ніє;","ра́дуйся, мучи́телей гро́зноє воздая́ніє.","Ра́дуйся, свя́занним у́зи разріша́ющая;","ра́дуйся, ті́лом і душе́ю пліне́нних свобожда́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 7","ps":["Хотя́щу пра́ведному Судії́ і Бо́гу челові́ки, Того́ забива́ющия, вразуми́ти, попусти́ бра́нем ве́ліїм на землі́ воздви́гнутися. Язи́ци бо см'ято́шася і ца́рства поколеба́шася. Смерть і у́жас по лицю́ землі́ пройдо́ша, плач і стена́ніє возду́х огласи́. Тогда́ у́бо всі, і́же на Тя упова́ніє возложи́ша, Богоро́диці, ко о́бразу Твоєму́ усе́рдно притека́ху і, от Тебе́ єди́ния спасе́нія ча́юще, Бо́гу, да́вшему Тя лю́дем Засту́пницю, вопія́ху: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́виє зна́менія і чудеса́ ве́лія яви́ла єси́ от іко́ни Твоєя́ честни́я, Богома́ти, єгда́ усли́шахом глас бра́ні. Градо́м бо горя́щим і землі́ трясу́щися, черто́гом разруша́ємим і пруго́м, возду́х ісполня́ющим, соблюла́ єси́ це́рков, в не́йже о́браз Твой, Всецари́це, пребива́ше, невреди́му: всі же в ней моля́щіїся, чу́до ви́дяще, єди́ними усти́ возопи́ша Ті такова́я:","Ра́дуйся, Держа́вная Воєво́до;","ра́дуйся, на Ню́же упова́ють всі наро́ди.","Ра́дуйся, Це́ркве Столп і Утвержде́ніє;","ра́дуйся, вся́кия святи́ні защи́то і огражде́ніє.","Ра́дуйся, побі́до, мир побіжда́ющая;","ра́дуйся, і неіму́щия упова́нія спаса́ющая.","Ра́дуйся, блага́я Послу́шательнице моле́ній приле́жних;","ра́дуйся, безпомо́щних по́моще і наде́ждо ненаде́жних.","Ра́дуйся, сатану́ под но́зі на́ша сокруша́ющая;","ра́дуйся, огню́ і стихі́ям повеліва́ющая.","Ра́дуйся, іко́ною Твоє́ю нас остеня́ющая;","ра́дуйся, Покро́вом Твої́м нас осіня́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 8","ps":["Стра́нноє і стра́шноє зна́меніє яви́ла єси́, Всесвята́я, єгда́ домо́м разруша́ємим, хра́мину ма́лую, ю́же освяти́ла єси́ пре́жде іко́ни Твоєя́ пребива́нієм, сохрани́ла єси́ невреди́му, ста́рицю же і си́на єя́, в той кри́ющихся, ці́лих предста́вила єси́. Тім же всі, зря́щия і сли́шащия сія́, ужаса́хуся у́жасом, стра́хом вопію́ще: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир любо́вію Твоє́ю Богоподо́бною об'є́млеши, Присноді́во, бли́жняя і да́льняя посіща́ющи і всю поднебе́сную во іко́ні Твоє́й приснопоклоня́ємей обтека́ющи. Тім же от восто́к да́же до за́пад ше́ствіє Твоє́ бисть, да всі невозбра́нно к той припа́дають, Тебі́ же Первообра́зній припіва́ють сицева́я:","Ра́дуйся, всіх ра́достей Ра́досте;","ра́дуйся, Ча́ше неупива́ємая сла́дости.","Ра́дуйся, ни́нішняго ві́ка ско́рбнаго утіше́ніє;","ра́дуйся, бу́дущия жи́зні наслажде́ніє.","Ра́дуйся, веселя́щихся на небесі́ нас ра́ди оставля́ющая;","ра́дуйся, к землі́ многоско́рбней і многобе́дствующей приника́ющая.","Ра́дуйся, со іко́ною Твоє́ю благода́тними стопи́ неви́димо в до́ми на́ша входя́щая;","ра́дуйся, благослове́ніє і ра́дованіє тім принося́щая.","Ра́дуйся, ке́ллії мона́шеськия о́бразом Твої́м честни́м освяща́ющая;","ра́дуйся, клі́ти убо́гія па́че пала́ть ца́рських тім украша́ющая.","Ра́дуйся, хра́ми Бо́жії Ли́ком Твої́м Пресвяти́м облиста́ющая;","ра́дуйся, в жили́щах чту́щих Тя незри́мо пребива́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 9","ps":["Всяк во́зраст і всяк чин притека́єть к Тебі́, Богоневі́сто Влади́чице, всім бо просте́рти суть Богоно́снеї Твої́ ру́ці, всім вся подає́ши незави́стно, вся сві́тлиши і утіша́єши, Всецари́це. Ті́мже, о Тебі́ веселя́щеся, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния ув'ядо́ша і ри́тори благоглаго́ливії ізнемого́ша, по до́лгу Тя просла́вити хотя́щії, Марі́є Богоро́дице, недоумі́єть бо всяк ум благохвали́ти Тя по достоя́нію, оба́че а́ще ми умо́лкнем — ка́меніє возопію́ть. Ті́мже, а́ще і недосто́йнії су́ще, бре́нними усти́ дерза́єм взива́ти Ті такова́я:","Ра́дуйся, проро́ков огнедохнове́нний глаго́лі;","ра́дуйся, апо́столов про́поведе неумолка́ємая.","Ра́дуйся, преподо́бних серде́чноє пі́ніє;","ра́дуйся, іспові́дников крі́посте і дерзнове́ніє.","Ра́дуйся, молча́льников тайнолі́пная бесе́до;","ра́дуйся, ри́торов і Богопропові́дников злати́я уста́.","Ра́дуйся, на стра́сті подвиза́ющихся превознесе́нная награ́до;","ра́дуйся, всіх пра́ведников Боже́ственная отра́до.","Ра́дуйся, ма́терей сла́во і ді́вства похвало́;","ра́дуйся, ста́рцев поко́є і ю́них Води́тельнице.","Ра́дуйся, Ада́ма сме́ртнаго Дщи, Бо́гу же Роди́тельнице;","ра́дуйся, сла́вою неізрече́нною близ Бо́га сія́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ся ми́ру те́плі помоли́ся, Богоро́дице, по́мощі бо Твоєя́ тре́буєть, сітя́м лука́ваго, по всему́ лицю́ землі́ распросте́ртим, язи́ком же шата́ющимся і бу́рям напа́стей, на Це́рков Бо́жию воздвиза́ємим; ті́мже, я́коже в Ка́ні Галиле́йстій іногда́, рци сло́во к Си́ну Твоєму́ і Бо́гу, да во́ду іскуше́ній же і скорбе́й во вино́ умиле́нія і весе́лія Боже́ственнаго претвори́ть, да поє́м Єму́ ви́ну: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́ма нам бу́ди, Всенепоро́чная, сопроти́в ополче́ній ви́димих і неви́димих враг, держа́вно по нас побора́ющи, любо́вію вопію́щих Ті такова́я:","Ра́дуйся, Богоно́снеї ру́ці Твої́ о нас к Бо́гу при́сно воздвига́ющая;","ра́дуйся, духо́в зло́би под но́зі на́ша покоря́ющая.","Ра́дуйся, кня́зя тьми хитросплете́нния сові́ти посрамля́ющая;","ра́дуйся, ту́чі по́мислов Ду́хом Бо́жиїм развіва́ющая.","Ра́дуйся, уни́ніє от нас отгоня́ющая;","ра́дуйся, треволне́нія жите́йськія смиря́ющая.","Ра́дуйся, бу́рям напа́стей повеліва́ющая;","ра́дуйся, обурева́ємих благода́тно окормля́ющая.","Ра́дуйся, із глубини́ зол ізвлача́ющая;","ра́дуйся, погиба́ющим дла́ни ми́лостивно простира́ющая.","Ра́дуйся, но́зі на́ша на путі́ спасе́нія наставля́ющая;","ра́дуйся, ру́ці на́ша во бра́ніх укріпля́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 11","ps":["Пі́нія на́ша, я́коже Син Твой вдови́чу ле́пту, прийми́, Всесвята́я, і пода́ждь нам всегда́ Тебі́ сія́ приноси́ти, живо́т наш в ми́рі управля́ющи і гріхо́м проще́ніє да́рующи, я́ко да в небе́сния оби́телі вше́дше, воскли́кнем Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світообра́зний омофо́р Твой, Всеблага́я, над земле́ю на́шею неви́димо простри́, нече́стія безлу́нную нощ прогоня́ющи, зарю́ же пакибитія́ возсіява́ющи, да в ра́дості немо́лчно зове́м:","Ра́дуйся, воі́стину в Со́лнце облече́нная;","ра́дуйся, вінце́м от звізд ув'язе́нная.","Ра́дуйся, ря́сни злати́ми преіспещре́нная;","ра́дуйся, красото́ неізрече́нная.","Ра́дуйся, Сві́тлосте, денни́ці світлі́йшая;","ра́дуйся, теплото́, со́лнця любе́знійшая.","Ра́дуйся, зарни́це бу́дущаго ві́ка;","ра́дуйся, Сві́те невече́рній а́нгелов і челові́ков.","Ра́дуйся, те́мния де́монськия полки́ дале́че отгоня́ющая;","ра́дуйся, неві́рія тьму просвіща́ющая.","Ра́дуйся, во ору́жія сві́та нас облека́ющая;","ра́дуйся, Святи́не, цві́ти всіх доброді́телей благоуха́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть воз благода́ть от іко́ни Твоєя́ прия́хом, Богоро́дице Пречи́стая. Нікто́же бо, притека́яй к той с ві́рою, тощ отхо́дить, но ки́йждо по потре́бі своє́й дар Боже́ственний приє́млеть і ра́достію вінча́ється, вопія́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м Тя, велича́єм Тя, покланя́єм Ті ся, Госпоже́ Пречи́стая, си́тости похва́л Твої́х отню́дь не зна́юще, і припа́дающи пред честни́м Твої́м о́бразом, уми́льно взива́єм Ті си́це:","Ра́дуйся, душ на́ших сладча́йшая весно́;","ра́дуйся, серде́ць на́ших світлі́йшеє у́тро.","Ра́дуйся, висото́ недоми́слимая;","ра́дуйся, сла́во неув'яда́ємая.","Ра́дуйся, блаже́нство несконча́ємоє;","ра́дуйся, бла́госте неізсяка́ємая.","Ра́дуйся, весе́ліє неізрече́нноє;","ра́дуйся, воі́стину єди́на Преблагослове́нная.","Ра́дуйся, преви́ше всей тва́рі Превознесе́нная;","ра́дуйся, в житії́ сем нас заступа́ющая.","Ра́дуйся, в час сме́ртний ві́рния сріта́ющая;","ра́дуйся, я́ко і на Стра́шнім Суди́щі спаса́єши на Тя упова́ющия.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 13","ps":["О,Всепі́тая Ма́ти і Ма́ти всім христия́ном, Си́на Твоєго́ і Бо́га любо́вію подража́ющи, вопіє́ши к нам ми́лостивно: не бо́йся, ма́лоє ста́до, Аз єсьм с ва́ми і нікто́же на ви! Ті́мже Ті любо́вію припа́дающе і со слеза́ми благодаря́ще, велегла́сно зове́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели удиви́шася, зря́ще Тя, Влади́чице, іко́ною Твоє́ю, я́ко столпо́м о́гненним, нам предходя́щую во вели́ком ісхо́ді на́шем із землі́, беззако́нники порабоще́нния. Не Мойсе́я бо, но Са́мую Тя і́мами Путеводи́тельницю в ско́рбнем стра́нствованії на́шем, ті́мже Ті благода́рні зове́м:","Ра́дуйся, благослове́нная Одиги́тріє;","ра́дуйся, і́стиннаго Путі́ Ма́ти.","Ра́дуйся, сквозі́ пусти́ню ми́ра сего́ нас провожда́ющая;","ра́дуйся, Амали́ка ми́сленнаго пресла́вно побіжда́ющая.","Ра́дуйся, істо́чники благода́ті от іко́ни Твоєя́ істоча́ющая;","ра́дуйся, зако́н Си́на Твоєго́, Христа́ Бо́га на́шего, на скрижа́ліх серде́ць на́ших напису́ющая.","Ра́дуйся, зно́єм страсте́й пали́мих благода́тноє окропле́ніє;","ра́дуйся, ізнемога́ющих всемо́щноє укріпле́ніє.","Ра́дуйся, серде́ць см'яте́нних тиша́йшая усла́до;","ра́дуйся, стра́нних і си́рих Боже́ственная отра́до.","Ра́дуйся, зе́млю обітова́нную нам приуготовля́ющая;","ра́дуйся, небе́снаго Ієрусали́ма врата́ нам отверза́ющая.","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нной Воєво́ді і благо́й Одиги́трії, путеводя́щей нас к Небе́сному Гра́ду, прийді́те, припаде́м всі, гра́да зді пребива́ющаго не іму́щії, Тоя́ всеси́льнаго заступле́нія прося́ще, чудеса́ же, от літ дре́вніх да́же дони́ні от іко́ни Єя́ бива́ємия, помина́юще, велегла́сно возопії́м:","Ра́дуйся, Влади́чице, зна́менія ми́лости Твоєя́ ми́ру при́сно явля́ющая."]},{"h":"Молитва перша","ps":["О Цари́це Небе́сная! Кто ізочте́ть вели́коє мно́жество чуде́с Твої́х, кто ісчи́слить во́пли моли́твенних проше́ній, то́ки умиле́нних слез, благода́рних воздиха́ній, проли́тих пред іко́ною Твоє́ю. Ове́яна у́бо вся она́ ско́рбію наро́дною, пла́чем угнете́нних і ра́достною хвало́ю уте́шенних. Припа́даху к ней лю́діє, поне́сшия ага́рянськоє і́го, пла́каху Москва́ в сму́тноі вре́м'я, взива́ше Курск в наше́ствіє вра́жеськоє. Вопія́ше вся о́бласть во дні смертоно́сних болі́зней і бід, і вся ско́рбі на ра́дость прелага́ла єси́. Ті́мже і ни́ні благослови́ зе́млю Ру́ськую. Спаси́ от гріха́, поги́белі і собла́знов страну́ на́шу. Ізле́й благода́ть на труд земледе́льчеський і на вся́коє благо́є начина́ніє обще́ственноє. Пом'яни́, Пресвята́я Ді́во, по і́мені всіх предстоя́щих і моля́щихся і вся лю́ди, тре́бующия Твоєго́ утіше́нія, по́мощі і милосе́рдія. Ти у́бо ві́си та́йная серде́ць на́ших. Ті́мже всім по потре́бі їх проше́нія іспо́лни. Ізря́дніє же заблу́ждших обрати́ к покая́нію, нас же всіх умудри́ сві́том Єва́нгельськия любві́ і до́брих діл. Архипа́стири і па́стирі і вся ві́рния в Правосла́вії до сме́рти тве́рди покажи́, в Ца́рство Небе́сноє упра́ви і со Христо́м жи́ти сотвори́ во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Цари́ця на́ша преблага́я, наде́ждо на́ша Богоро́дице, прия́телище си́рих і стра́нних предста́тельнице, скорб'я́щих ра́досте, оби́димих покрови́тельнице! Зри́ши на́шу біду́, зри́ши на́шу скорб; помози́ нам я́ко немощни́м, окорми́ нас я́ко стра́нних. Оби́ду на́шу ві́си, разріши́ ту, я́ко во́лиши, ізба́ви оте́чество на́ше, стра́ждущую зе́млю Украї́нськую от лю́таго безбо́жников обстоя́нія, спаси́ і сохрани́ раби́ Твоя́ (і́м'ярік) і всіх нас, зді предстоя́щих і моля́щихся, і покри́й нас от вся́каго зла честни́м Твої́м омофо́ром, я́ко не і́мами іни́я по́мощі ра́зві Тебе́, ні іни́я предста́тельниці, ні благи́я уті́шительниці, то́кмо Тебі́, о Богома́ти, я́ко да сохрани́ши ни і покри́єши во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко необори́мую сті́ну і істо́чник чуде́с / стяжа́вше Тя раби́ Твої́, / Богоро́дице пречи́стая, / сопроти́вних ополче́нія низлага́єм. / Ті́мже мо́лим Тя: / мир гра́ду Твоєму́ да́руй // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Честна́го о́браза Твоєго́ зна́меніє / пра́зднующе лю́діє Твої́, Богороди́тельнице, / і́мже ди́вную побі́ду на сопроти́вния гра́ду Твоєму́ дарова́ла єси́. / Ті́мже Тебе́ ві́рою взива́єм: // ра́дуйся, Ді́во, христия́н похвало́."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой честни́й, і́мже показа́ла єси́ пресла́вноє зна́меніє."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Охтирська»","e":"Akathist to the Theotokos before her icon “Okhtyrka”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, преди́вно цільбоно́сную іко́ну Свою́ явившей, на не́йже у Креста́ Христо́ва стоя́щую Засту́пницю на́шу ви́дяще, похва́льноє Той возглаша́єм пі́ніє; Ти же, Госпоже́ Всеми́лостивая, я́ко іму́щая милосе́рдіє неізрече́нноє, те́плим Твої́м предста́тельством і заступле́нієм от вся́ких нас бід і неду́гов свобожда́й, во умиле́нії Тебі́ зову́щих:","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Пречи́стая Ді́во Богоро́дице, єгда́ у Креста́ возлю́бленнаго Си́на Твоєго́ предстоя́ла єси́, Того́ страда́нія, нас ра́ди претерпі́нная, зря́щи, тогда́ се́рдцем лю́ті уязвля́лася єси́: воі́стину ору́жіє ско́рбноє про́йде ду́шу Твою́. Ті́мже і ми, многоболі́зненноє Твоє́ у Креста́ предстоя́ніє, на іко́ні ізображе́нноє, ви́дяще, си́це вопи́ти Тебі́ дерза́єм:","Ра́дуйся, Отця́ Безнача́льнаго Неві́сто прекра́сная;","ра́дуйся, Си́на Предві́чнаго Роди́тельнице неіскусобра́чная.","Ра́дуйся, Ду́ха Свята́го пала́то непоро́чная;","ра́дуйся Тро́йці Живонача́льния Таї́ннице Боже́ственная.","Ра́дуйся, а́нгельських во́їнств удивле́ніє;","ра́дуйся, ро́да челові́чеськаго возвише́ніє.","Ра́дуйся, воспіва́ємая от Херуви́м;","ра́дуйся велегла́сно сла́вимая от Серафи́м.","Ра́дуйся ра́дость неізрече́нную в нетлі́ннім рождестві́ Си́на Твоєго́ прия́вшая;","ра́дуйся, скорб ве́лію Того́ во сме́рті крестній претерпі́вшая.","Ра́дуйся, благода́ть, во є́же ско́рбния утіша́ти, от Него́ прия́вшая;","ра́дуйся, ра́дость милосе́рдаго Твоєго́ заступле́нія всему́ ми́ру дарова́вшая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 2","ps":["Ви́дів Тя, Богороди́тельнице Чи́стая, на Кресті́ пригвожде́нний Син Твой і Бог у Креста́ Єго́ предстоя́щую і болі́зненно Тому́ состраждущую, возлю́бленному ученику́ Своєму́ Іоа́нну Тя в Ма́тер нарече́ і сим весь род христия́нський Тебі́ усинові, да бу́деши воі́стину Ма́ти всім скорб'я́щим, Си́на Твоєго́ Христа́ Бо́га призива́ющим і пою́щим Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума неразуменна во́льнаго Христо́ва страда́нія не разумі́ша богоуби́йці іуде́є і Тебі́, Богоневі́сто, го́рці обезчадиша, ми же Тя, у Креста́ Си́на Твоєго́ і Го́спода на іко́ні ізображе́нную, ви́дяще, те́плі ві́руєм, я́ко ско́рбния гла́си моли́твенник Твої́х приє́млеши і того́ ра́ди благода́рні глаго́лем:","Ра́дуйся, о Христі́ Спаси́телі на́шем і нам Блага́я Ма́ти;","ра́дуйся, всіх нас в ско́рбний час страсте́й Єго́ усинови́вшая.","Ра́дуйся, нас си́рих і безпомо́щних Твоє́ю Ма́тернею любо́вію не оставля́ющая;","ра́дуйся милосе́рдим ухом Твої́м к нам приникающая.","Ра́дуйся, крест ско́рбних іспита́ній Сама́ до́бльственно поне́сшая;","ра́дуйся, Твої́м сострастієм і нам несе́ніє єго́ облегча́ющая.","Ра́дуйся, в земні́й юдо́лі скорбе́й несумні́нная на́ша Наде́ждо і Утіше́ніє;","ра́дуйся, в бу́дущем ві́ці всіх ві́рних Ра́досте і Защище́ніє.","Ра́дуйся, стра́хом сме́рти і суда́ Бо́жия спя́щия со́вісти пробуждающая;","ра́дуйся, коснеющия во грісі́х к покая́нію спаси́тельному приводя́щая.","Ра́дуйся, із ро́ва поги́бельнаго отча́янния ісхища́ющая;","ра́дуйся, в сві́тлия оби́телі поко́я ві́чнаго тружда́ющихся возводя́щая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю, чрез святи́я іко́ни Твоя́ являємою, спаса́ти нас не престає́ши, Всеблага́я Влади́чице. Та́ко і зді, в украї́нськім гра́де на́шем, вели́кая чудеса́ світоно́сним явле́нієм многоціле́бнаго о́браза Твоєго́ показа́ла єси́, єму́же покланя́ющеся с любо́вію, вопіє́м Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи Ма́тернєє попече́ніє о лю́діх, Честно́ю Кро́вію Си́на Твоєго́ іску́пленних, Госпоже́ Пресвята́я, благода́тную іко́ну Твою́ в би́лії травнем смиренномудрому ієре́ю Данії́лу яви́ти благоволи́ла єси́ і сію́ світоно́сним сія́нієм і чудеси́ мно́гими просла́вила єси́, да всі ві́рнії похва́льними пі́сньми Тебі́ взива́ють:","Ра́дуйся, многотекущий істо́чник ми́лости Бо́жия нам дарова́вшая;","ра́дуйся, зало́г Твоєго́ Ма́терняго о нас попече́нія пречу́дно преподавшая.","Ра́дуйся, ієре́ю благогові́йному в травнем зла́ці іко́ну Твою́ святу́ю яви́вшая;","ра́дуйся, солнцеподобними луча́ми ту озари́вшая.","Ра́дуйся, наш ма́лий град чудеси́ вели́кими просла́вльшая;","ра́дуйся, незна́ємоє дото́лі і́м'я єго́ всім ві́рним ізві́стно сотворившая.","Ра́дуйся, всю Це́рков Украї́нськую явле́нієм іко́ни Твоєя́ духо́вно возвесели́вшая;","ра́дуйся, всю страну́ на́шу покро́вом Твої́м святи́м осіни́вшая.","Ра́дуйся, ві́рним ісціле́нія от іко́ни Твоєя́ подаю́щая;","ра́дуйся, неві́рния чудеси́ Твої́ми посрамля́ющая.","Ра́дуйся, скоропослушно моли́твам смире́нним внемлющая;","ра́дуйся, ско́рбная воздиха́нія стра́ждущих і печа́лію угнете́нних незри́мо утоля́ющая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смути́ Даниї́ла ієре́я, святу́ю іко́ну Твою́ обрі́тшаго, оба́че со стра́хом моле́бно к Тебі́ возопи́, да бу́деши єму́ в животі́ Помо́щниця, в час сме́ртний Засту́пниця; сему́ у́бо і ми подража́юще, та́яжде моле́нія Тебі́, Ма́ти Бо́жия, возноси́ти дерза́єм, Влади́ці же живота́ і сме́рті Христу́ Бо́гу зове́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав ієре́й Данії́л во сні повелі́ніє Твоє́, Пречи́стая Ді́во, да оми́єть водо́ю лик Твой Святи́й на іко́ні і да украси́ть сію́ благолі́пно, потща́ся во́лю Твою́ благогові́йно іспо́лнити, Тебі́ же, Свої́м милосе́рдієм неізрече́нним єго́ взискавшей, благода́рственно вопія́ше:","Ра́дуйся, Ма́ти Го́спода Ви́шняго;","ра́дуйся, я́ко Госпо́дь при́сно с Тобо́ю пребива́єть.","Ра́дуйся, небе́с похвало́ і землі́ заступле́ніє;","ра́дуйся ро́да христия́нськаго непреста́нноє пі́ніє.","Ра́дуйся, лю́б'ящая смире́нния се́рдцем;","ра́дуйся, богатя́щая нищія ду́хом.","Ра́дуйся, ізбра́нния раби́ Своя́ благода́тно посіща́ющая;","ра́дуйся в со́ніїх виді́ніїх во́лю Свою́ їм открива́ющая.","Ра́дуйся, сві́тлостію іко́ни Твоєя́ мрак гріхо́в прогоня́ющая;","ра́дуйся, зна́меньми і чудеси́ от нея́ істочаємими, в правосла́вній ві́рі всіх утвержда́ющая.","Ра́дуйся, ві́рним путеводи́тельнице ко спасе́нію;","ра́дуйся, кающимся уті́шительнице і упова́ніє.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ свята́я і чудотво́рная іко́на Твоя́, Влади́чице, яви́ся, ди́вним сія́нієм хра́мину смиренному́драго ієре́я Даниї́ла озари́вшая; вода́ же, іко́ну Твою́ омившая, ціле́бную си́лу прия́ти сподо́бися; ті́мже лю́ди, с ві́рою сію́ пію́ще і то́ю окропля́ємі, врачевство́ благода́тноє получи́ша і хвалу́ Бо́гу си́це воспі́ша: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів ієре́й Данії́л в со́ннім виді́нії Тя, Влади́чице, во о́бразі Неві́сти прекра́сния я́вльшуюся і от омитія іко́ни Твоєя́ во́ду сліянную неду́жним вкуша́ти повелевшую, позна́ Тя, Преблагослове́нная Ді́во, Ціли́тельницю благода́тную і, то́ю водо́ю боля́щую ісціли́в, во умиле́нії се́рдця вопія́ше Тебі́:","Ра́дуйся, в неду́зіх стра́ждущих врачевство́ благода́тноє;","ра́дуйся, болі́зней многолетніх ісціле́ніє ско́роє і соверше́нноє.","Ра́дуйся, єди́ним прикоснове́нієм к іко́ні Твоє́й святі́й здра́віє недугующим подаю́щая;","ра́дуйся, водо́ю і єле́єм, от нея́ освяще́нним, сме́ртні боля́щия возставля́ющая.","Ра́дуйся, пред Сино́м Твої́м і Бо́гом дерзнове́нная на́ша Предста́тельнице;","ра́дуйся, гнів Єго́ пра́ведно на ни дви́жимий, на ми́лость преклоня́ющая.","Ра́дуйся, ско́рбію сокруше́нних уті́шительнице;","ра́дуйся, печа́лію удруче́нних ободрительнице.","Ра́дуйся, Ра́досте на́ша пресвята́я;","ра́дуйся, Отра́до на́ша неізглаго́ланная.","Ра́дуйся, премилосе́рдая тре́бующим Помо́щнице;","ра́дуйся, ро́да христия́нськаго неусипа́ющая Попечи́тельнице.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 6","ps":["Пропові́дник чуде́с, от іко́ни Твоєя́ явле́нних, ієре́й Данії́л яви́ся, єгда́ ціле́бний Твой о́браз, Влади́чице, в храм Бо́жий принесе́ і благогові́йно поста́ви, да всі́ми ви́дим пребива́єть і, а́ки зало́г благода́тний Твоєго́ к людям благоволе́нія, почита́ється, о не́мже ра́дующеся, я́ко о сокро́вище, Бо́гом да́ннім, зове́м Даропода́телю Христу́: Аллилу́я."]},{"h":"Ікос 6","ps":["Сві́том многоразли́чних чуде́с святу́ю іко́ну Твою́, Богома́ти, просла́ви і обрі́тшаго ю, я́ко ізбра́нника Своєго́, знаменовавши, сего́ путе́м ско́рбних лише́ній і напа́стей к блаже́нству ра́йському возвела́ єси́, єго́же і нас сподо́би, Госпоже́ Всеми́лостивая, с ві́рою і любо́вію Тебі́ взива́ющих:","Ра́дуйся, побо́рников ві́ри і благоче́стія к черто́гом Отця́ Небе́снаго приводя́щая;","ра́дуйся, наде́ждою благ ві́чних ску́дость благ вре́менних восполня́ющая.","Ра́дуйся, слеза́ми го́рести і лише́ній нечистоту́ гріхо́вную омива́ющая;","ра́дуйся, попуще́нієм земни́х скорбе́й путь к радостям ра́йським открива́ющая.","Ра́дуйся, кро́ткия ду́хом во упова́нії на Тя утвержда́ющая;","ра́дуйся, гони́мим за пра́вду Ца́рствіє Небе́сноє уготовля́ющая.","Ра́дуйся, іко́ною Твоє́ю свято́ю пресла́вно чудодействующая;","ра́дуйся, ди́вная зна́менія то́ю соверша́ющая.","Ра́дуйся, служи́телей Це́ркве Христо́ви благода́тная по́моще;","ра́дуйся, ієре́єв благогові́йних богому́драя Наста́внице.","Ра́дуйся, ві́ри правосла́вния утвержде́ніє;","ра́дуйся, ро́да христия́нськаго возвише́ніє.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 7","ps":["Хотя́щи па́че просла́вити іко́ну Твою́ святу́ю, Богома́ти, і бога́тия ми́лости от нея́ лю́дем низпосла́ти, жени́ ні́кия предсмертную мольбу́ о дще́ріх єя́, пред іко́ною Твоє́ю вознесе́нную, ди́вно усли́шала єси́ і, благочести́війшей цари́це Єлисаве́ті во сні яви́вшися, осиротелия отрокови́ці воспита́ти той повелі́ла єси́, я́же, до конця́ живота́ своєго́ Твою́ ми́лость пам'яту́юще, Всеви́шнему Отцю́ сиро́т благода́рственно воспіва́ху: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє повелі́ніє Твоє́ ісполня́ющи, благочестивейшая цари́ця о́бі ю́ния отрокови́ці со тща́нієм воспита́ і сама́ на поклоне́ніє чудотво́рному Твоєму́ о́бразу прийти́ потща́ся, іді́же храм благолі́пен сооруди́ти повелі́, в не́мже ни́ні предстоя́ще, благогові́йно вопіє́м Ті:","Ра́дуйся, безма́терніх сиро́т незри́мая Воспита́тельнице;","ра́дуйся ю́них і безпомо́щних дів благосе́рдая Попечи́тельнице.","Ра́дуйся, Ма́тернею любо́вію Твоє́ю всяк во́зраст ві́рних об'ємлющая;","ра́дуйся, во благи́х усе́рдния моли́тви ісполня́ющая.","Ра́дуйся, ца́рства Украї́нськаго благода́тноє утвержде́ніє;","ра́дуйся, Це́ркве Святи́я благолі́пноє украше́ніє.","Ра́дуйся, Цари́це Небе́сная, от цари́ць земни́х благогові́йноє приє́мшая поклоне́ніє;","ра́дуйся, благолі́пний храм, а́ки же́ртву прия́тную, Тебі́ принесе́нную, благослови́вшая.","Ра́дуйся, в нем ми́лостиво моли́тви ві́рних приє́млющая;","ра́дуйся, чудеси́ мно́гими єго́ освяти́вшая.","Ра́дуйся во хра́мі земні́м неізрече́нную красоту́ хра́ма небе́снаго показу́ющая;","ра́дуйся, моле́бния гла́си земни́х с гла́сом сил небе́сних соєдиняющая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 8","ps":["Странници єсьми́ і прише́льці на землі́ сей, скорбе́й і болі́зней іспо́лненній, пре́лестьми ми́ра сего́ і наві́ти ду́ха зло́би іскуша́ємії; в Тебі́ же, Ма́ти Бо́жия, неісчерпа́ємий істо́чник благода́тних дарова́ній обріта́юще, і Небе́снаго оте́чества дости́гнути упова́єм, взива́юще Соверши́телю на́шего спасе́нія Христу́ Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир преблагослове́нноє і́м'я Твоє́, Богоро́дице, сла́вить, і Твоєго́ Боже́ственнаго ли́ка ізображе́ніє чтить благогові́йно, і́мже преди́вная чудеса́ во вселе́нній соверша́єши. Ті́мже і ми чудотво́рную іко́ну Твою́, Богома́ти, я́ко со́лнце, луча́ми чуде́с сія́ющую, ви́дяще, со умиле́нієм Тебі́ взива́єм:","Ра́дуйся, я́ко от восто́ка і до за́пада і́м'я Твоє́ ублажа́ється;","ра́дуйся я́ко всі роди́ благогові́йно Тя велича́ють.","Ра́дуйся, правосла́вную Украї́ну па́че іни́х стран возлюби́вшая;","ра́дуйся, чудотво́рними іко́нами Твої́ми сію́ обогати́вшая.","Ра́дуйся, сія́нієм чуде́с Твої́х мрак єресе́й і раско́лов прогоня́ющая;","ра́дуйся, бога́тими ми́лостьми Твої́ми неві́рния к ві́рі приводя́щая.","Ра́дуйся, ревни́телей ві́ри Христо́вой многопопечительная наста́внице;","ра́дуйся, отпадающих от нея́ гро́зная обличи́тельнице.","Ра́дуйся, і́щущих Христо́ва просвіще́нія сві́том богові́дінія озаря́ющая;","ра́дуйся, хули́телей ві́ри правосла́вния в пучи́ну томле́нія душе́внаго вверга́ющая.","Ра́дуйся, наде́жду іму́щих на Тя ніколи́же оставля́ющая;","ра́дуйся, моле́нія ві́рних при́сно ісполня́ющая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 9","ps":["Вся а́нгельськая во́їнства слу́жать Тебе́, Влади́чице ми́ра, превознесенну в Сіо́ні Небе́снім Тя созерца́юще, і неземними похвала́ми честву́ють Тя с любо́вію, єди́ному же просла́вльшему Тя Бо́гу немо́лчно взива́ють: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не мо́жеть досто́йно просла́вити Тя, Ма́ти Го́спода ви́шніх сил; ізумевають бо і у́ми а́нгельстії пі́ти Тя, Богоро́дице, оба́че ми, грі́шнії, благода́рні Тя чту́ще, сицеви́я пі́сні, а́ки діте́й лепетаніє, Тебі́ приноси́ти дерза́єм:","Ра́дуйся, лі́ствице, не́бо і зе́млю соєдини́вшая;","ра́дуйся, ста́мно, благода́ті Бо́жия преісполненная.","Ра́дуйся, Бо́га Сло́ва в плоть земноро́дних облекшая;","ра́дуйся, до́льнему ми́ру Христа́ Спаси́теля породи́вшая.","Ра́дуйся, і́менем Ма́тере Бо́жия возвели́ченная;","ра́дуйся, преви́ше небе́с вознесе́нная.","Ра́дуйся, пред Не́юже си́ли а́да і тьми трепе́щуть;","ра́дуйся, Ю́же сві́тлії лиці́ небе́сних сил славосло́в'ять непреста́нно.","Ра́дуйся, святи́х хра́мов благода́тноє освяще́ніє;","ра́дуйся, і́ночеських оби́телей покро́ве і снабді́ніє.","Ра́дуйся, христия́нських жили́щ благода́тноє охране́ніє;","ра́дуйся, всего́ ми́ра освяще́ніє.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 10","ps":["Спасти́ся всім ві́рним жела́ющи, оби́льно на вся притека́ющия к Тебі́, Богоро́дице Ді́во, да́ри Твоєя́ благода́тния по́мощі ізлива́єши і Твої́м Ма́терним покро́вом от ко́зней і ловле́нія дия́вольськаго всяк во́зраст огражда́єши ві́рно вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Преблагослове́нная Ді́во, і всім ві́рним от враг ви́димих і неви́димих Покро́в і Защище́ніє. Ті́мже по́мощ Твою́ благу́ю от свята́го о́браза Твоєго́ явля́ти нам і додне́сь не престає́ши, к нему́же припа́дающе, уми́льно взива́єм Ті:","Ра́дуйся, до́ми на́ша іко́ною Твоє́ю благословляющая;","ра́дуйся, ни́ви і па́жити на́ша осіне́нієм єя́ освяща́ющая.","Ра́дуйся, возвеянієм до́брих ві́тров і росо́ю благовре́менних дожде́й землі́ плодоро́діє да́рующая;","ра́дуйся, всю твар от щедро́т Си́на Твоєго́ оби́льно пита́ющая.","Ра́дуйся, гра́ди і ве́сі на́ша от смертоно́сния я́зви спаса́ющая;","ра́дуйся, в годи́ну бі́дствій на по́мощ к нам ускоря́ющая.","Ра́дуйся, я́ко Твоя́ Ма́терняя моли́тва мно́го мо́жеть ко благосе́рдію Влади́ки;","ра́дуйся, я́ко Твої́м предста́тельством от преще́нія, за гріхи́ на́ша бива́ємаго, освобождаємся.","Ра́дуйся, от житія́ вре́меннаго отходящих держа́вная Засту́пнице;","ра́дуйся, в гро́зний час сме́ртний ві́рним ізря́дная Пособнице.","Ра́дуйся, ключу́ Ца́рствія Христо́ва;","ра́дуйся, две́ре ра́йськая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє прино́сим Ті, Влади́чице Пречи́стая, я́ко многоціле́бний Твой о́браз нам дарова́ла єси́, на не́мже плачущую Тя зрим со умиле́нієм; у́бо і на́ше окаменелоє в беззако́ніїх се́рдце слеза́ми умиле́нія напої́ оби́льно, о Всеблага́я, да, і́ми от скве́рни гріхо́вния очи́стившеся, сподо́бимся пі́ти со святи́ми Царю́ Сла́ви Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сная лампада, єле́єм ми́лости преісполненная, яви́лася єси́ в Це́ркві Христо́вой, Влади́чице, вся конці́ землі́ сві́том і́стиннаго богові́дінія просвіща́ющая і к блаже́нству ві́чному приводя́щая зову́щих Ті такова́я:","Ра́дуйся, суєму́дріє проти́вников ві́ри Христо́ви посрамля́ющая;","ра́дуйся, чистоту́ догма́тов Правосла́вія чудеси́ Твої́ми охраня́ющая.","Ра́дуйся, заблуждшим от путі́ пра́ваго путеводи́тельнице ко спасе́нію;","ра́дуйся, во прегріше́нія тя́жкая впадшим пособнице к покая́нію і ісправле́нію.","Ра́дуйся, в се́рдця закоснелих грі́шников сві́тлий луч наде́жди на проще́ніє Бо́жиє вселя́ющая;","ра́дуйся, тім от отча́янія і ві́чния ги́белі душі́ їх спаса́ющая.","Ра́дуйся, благові́стником уче́нія Христо́ва всегда́шняя помо́щнице;","ра́дуйся, пропові́дником Ца́рства Бо́жия богоглаго́ливая споспі́шнице.","Ра́дуйся, моли́тви ві́рних к престо́лу Небе́снаго Царя́ вознося́щая;","ра́дуйся, і Сама́ пред Сино́м Твої́м і Бо́гом всегда́ о нас моля́щаяся.","Ра́дуйся, ми́ра засту́пнице;","ра́дуйся, ми́лості і щедро́т неоскудевающий істо́чниче.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 12","ps":["Благода́ті зало́г, многоціле́бний о́браз Твой дарова́ла єси́ нам, Влади́чице, к нему́же притекающиє, прилі́жно мо́лимся Тебі́: прийми́, Госпоже́ Всеблага́я, пред сим чудоді́йственним о́бразом приноси́моє Тебі́ поклоне́ніє і в напа́стіх на́ших по́мощ і защи́ту нам пода́ждь, да ви́ну вопіє́м дарова́вшему Тебі́ толи́кую си́лу благода́ті Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, Богома́ти Пречи́стая, пропові́дуєм Твою́ ко христия́нському ро́ду ми́лость: се бо і мно́гажди ди́вная зна́менія милосе́рдія Твоєго́, от многоціле́бнаго о́браза Твоєго́ явля́ємая, зді ви́діхом, я́же ра́зум наш бре́нний превосхо́дять і то́кмо ві́рою постигаються, ві́рних же вопи́ти Тебі́ подвиза́ють:","Ра́дуйся, о́браз Твой честни́й во утіше́ніє і освяще́ніє нам дарова́вшая;","ра́дуйся, сим ми́лость мно́гу лю́дем Твої́м я́вльшая і при́сно явля́ющая.","Ра́дуйся неоску́дний істо́чник по́мощі і ісціле́ній в нем открива́ющая;","ра́дуйся, моли́тви усе́рдно пред ним возноси́мия, благоутро́бне приє́млющая.","Ра́дуйся, о том освяще́нному собо́ру Це́ркве Украї́нськия усти́ раб Твої́х поведавшая;","ра́дуйся, гра́ду на́шему милосе́рдіє Твоє́ іко́ни явле́нієм запечатлевшая.","Ра́дуйся, кре́стному поклоне́нію є́ю нас науча́ющая;","ра́дуйся, си́лу спаси́тельную расп'я́тія Христо́ва на ней показу́ющая.","Ра́дуйся, ру́ці Твої́ в по́мощ нам простирающая;","ра́дуйся, всім ві́рним две́рі милосе́рдія Бо́жия отверза́ющая.","Ра́дуйся, Судію́ Пра́веднаго о нас умоляющая;","ра́дуйся, Ца́рствія Небе́снаго ві́рния сподобля́ющая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, сладча́йшаго Го́спода на́шего Ісу́са Христа́ нетлі́нно ро́ждшая і спаси́тельним страда́нієм Єго́ многоболі́зненно спострада́вшая, прийми́ ми́лостиво сіє́ ма́лоє моле́ніє на́ше, пред многоціле́бним Твої́м о́бразом с любо́вію Тебі́ приноси́моє, і всемо́щним Твої́м предста́тельством і заступле́нієм ізба́ви нас от вре́менния напа́сти і муки́ ві́чния, да сподо́бимся, по кончи́ні житія́ на́шего, со всі́ми святи́ми взива́ти Спаси́телю Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Пречи́стая Ді́во Богоро́дице, єгда́ у Креста́ возлю́бленнаго Си́на Твоєго́ предстоя́ла єси́, Того́ страда́нія, нас ра́ди претерпі́нная, зря́щи, тогда́ се́рдцем лю́ті уязвля́лася єси́: воі́стину ору́жіє ско́рбноє про́йде ду́шу Твою́. Ті́мже і ми, многоболі́зненноє Твоє́ у Креста́ предстоя́ніє, на іко́ні ізображе́нноє, ви́дяще, си́це вопи́ти Тебі́ дерза́єм:","Ра́дуйся, Отця́ Безнача́льнаго Неві́сто прекра́сная;","ра́дуйся, Си́на Предві́чнаго Роди́тельнице неіскусобра́чная.","Ра́дуйся, Ду́ха Свята́го пала́то непоро́чная;","ра́дуйся Тро́йці Живонача́льния Таї́ннице Боже́ственная.","Ра́дуйся, а́нгельських во́їнств удивле́ніє;","ра́дуйся, ро́да челові́чеськаго возвише́ніє.","Ра́дуйся, воспіва́ємая от Херуви́м;","ра́дуйся велегла́сно сла́вимая от Серафи́м.","Ра́дуйся ра́дость неізрече́нную в нетлі́ннім рождестві́ Си́на Твоєго́ прия́вшая;","ра́дуйся, скорб ве́лію Того́ во сме́рті крестній претерпі́вшая.","Ра́дуйся, благода́ть, во є́же ско́рбния утіша́ти, от Него́ прия́вшая;","ра́дуйся, ра́дость милосе́рдаго Твоєго́ заступле́нія всему́ ми́ру дарова́вшая.","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, преди́вно цільбоно́сную іко́ну Свою́ явившей, на не́йже у Креста́ Христо́ва стоя́щую Засту́пницю на́шу ви́дяще, похва́льноє Той возглаша́єм пі́ніє; Ти же, Госпоже́ Всеми́лостивая, я́ко іму́щая милосе́рдіє неізрече́нноє, те́плим Твої́м предста́тельством і заступле́нієм от вся́ких нас бід і неду́гов свобожда́й, во умиле́нії Тебі́ зову́щих:","Ра́дуйся, Благода́тная, непреста́нно за нас Христу́ моля́щаяся."]},{"h":"Молитва","ps":["О преблагослове́нная і многоми́лостивая Влади́чице ми́ра! Се ми грі́шнії, на святи́й о́браз Твой взира́юще і на нем Тя в ско́рбі і сострада́нії расп'я́тому за нас Христу́ Спаси́телю предстоя́щу ви́дяще, усе́рдно мо́лим Тя, ізві́стную о нас к Си́ну Твоєму́ моли́твенницю: не оста́ви нас в день іспита́нія і ско́рби, но во іскуше́ніїх і напа́стіх, нам бива́ємих, огради́ нас всечестни́м покро́вом Твої́м от враг ви́димих і неви́димих і даждь нам си́лу, во є́же всесоверше́нную і благу́ю во́лю Творця́ і ми́ра Влади́ки твори́ти. Зри́ши бо, ми́лостивая Засту́пнице на́ша, коли́ко гріхо́м вся́чеським подвержені єсьми́: не то́кмо бо во́лею согріша́єм, но і нево́лею в многоразли́чная прегріше́нія впада́єм. Сего́ ра́ди к Тебі́, держа́вній устроїтельнице спасе́нія христия́нськаго прибіга́єм і умиле́нно вопіє́м: ум наш позна́нієм Боже́ственния і́стини просвіти́, се́рдце на́ше теплото́ю христия́нськия любві́ і спаси́тельних жела́ній согрі́й, во́лю же на́шу в нелицемі́рнім за́повідей Госпо́дніх ісполне́нії утверди́. Єй, Госпоже́ преми́лостивая, прини́кни с висоти́ небе́сния к воздиха́нієм і моли́тві нас грі́шних, ісціли́ болі́зні неду́жних, умири́ се́рдця озло́бленних, даждь терпі́ніє стра́ждущим, внуши́ страх Бо́жий обидящим, укріпи́ гони́мия за пра́вду, сироти́ і вдови́ защити́, пода́ждь утіше́ніє пла́чущим, іспроси́ проще́ніє кающимся, де́монськую же бу́рю страсте́й во грі́шних душа́х утиши́ і в сердця́х, чту́щих Тя, Христо́ву кро́тость і любо́во вкорени́ і ду́хом милосе́рдія і сострада́нія сія́ утверди́, отпадшия же от ві́ри єретики́ і отсту́пники к позна́нію і́стини напра́ви і уста́ нечести́вих, ху́лящих Святу́ю Це́рков і ві́ру правосла́вную понося́щих, загради́. Отшедшим от житія́ сего́ отце́м і бра́тіям і сестра́м на́шим, о Ма́ти Бо́жия, проще́ніє гріхо́в і предначатіє блаже́нства ві́чнаго іспроси́. Єгда́ же і на́шея кончи́ни час прибли́житься, тогда́ у́бо, о Влади́чице, прийми́ ду́шу на́шу і в со́нмі пра́ведних сію́ упоко́й, іді́же ли́ци А́нгел і святи́х уго́дник немо́лчно славосло́в'ять держа́ву і ми́лость Отця́ і Си́на і Свята́го Ду́ха і Твоє́ Ма́тернеє о нас предста́тельство і заступле́ніє, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Преблагослове́нная Ді́во, Богороди́тельнице Чи́стая, / у Креста́ Си́на Твоєго́ і Бо́га на́шего предстоя́щи, / скорб ве́лію претерпі́ла єси́ / і благода́ть от Него́ прия́ла єси́ су́щия в ско́рбіх утіша́ти. / Ті́мже на пречи́стий о́браз Твой благогові́йно взира́юще / і ізображе́нную Тя на нем пред Кресто́м Спа́са на́шего ви́дяще, / умиле́нно к Тебі́ вопіє́м: / Засту́пнице усе́рдная, блага́я і ми́лостивая! / Ускори́ ізба́вити ни от вся́кия ско́рби, ну́жди і болі́зні / і спаси́ ду́ші на́ша, // да Тя со благодаре́нієм сла́вим во ві́ки."]},{"h":"Кондак, глас 8","ps":["Притеце́м, ві́рнії, к благода́тному ми́лостей і щедро́т істо́чнику - / чудотво́рному Пречи́стия Ді́ви о́бразу: / сей бо нам сви́ше дарова́ся, / душа́м і тілесе́м во спасе́ніє, / єму́же покланя́ющеся с любо́вію, возопіє́м к Богоро́диці: / о Всепі́тая Ма́ти, о Цари́ці Всеми́лостивая, / покри́й і соблюди́ нас от вся́каго зла // Твої́м к Бо́гу Ма́тернім предста́тельством."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Примножувальниця хлібів»","e":"Akathist to the Theotokos before her icon “Multiplier of Bread”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Влади́чице Небесе́ і землі́, ізбавля́ющей нас от вся́кия ну́жди, благода́рственноє прино́сим пі́ніє. Ти же, Всеми́лостивая Госпоже́ Богоро́дице, прийми́ на́ше усе́рдноє моле́ніє, сохрани́ нас от гла́да і па́губи, да́руй землі́ на́шей плодоно́сіє, Пита́тельнице і Спори́тельнице нив і хлібо́в на́ших, да ра́дующеся всегда́ зове́м Ті:","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ Тя, Влади́чице, к благода́тному челові́ков спасе́нію і дарова́ Тя Помо́щницю лю́дем, ізбавля́ющую нас от гла́да і вся́ких напа́стей, житіє́ на́ше до́брі устроя́ющую в ми́рі і вся́ком дово́льстві. Ті́мже со умиле́нієм взива́єм Ті:","Ра́дуйся, благода́тноє челові́ков от вся́кия ну́жди ізбавле́ніє;","ра́дуйся, достоя́нію Твоєму́ по́мощ і заступле́ніє.","Ра́дуйся, христолюби́вия лю́ди от вся́ких бід спаса́ющая;","ра́дуйся, а́лчущих пита́ющая.","Ра́дуйся, си́рих заступле́ніє;","ра́дуйся, наги́х одія́ніє.","Ра́дуйся, ізрасти́вшая нам Плод Живота́;","ра́дуйся, ро́ждшая Спа́са душ на́ших.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 2","ps":["Ви́дів Син Твой, Богома́ти, вели́коє Твоє́ к лю́дем милосе́рдіє, глаго́леть Тебі́: проси́, Ма́ти Моя́, зане́ не отвращу́ся Тебі́, но іспо́лню вся проше́нія Твоя́. Ми же, прославля́юще сіє́ ди́вноє промишле́ніє о ро́ді челові́честім, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Небе́сний дарова́ся преподо́бному ста́рцю Амвро́сію, є́же водрузи́ти во оби́телі, їм созда́нній, іко́ну Пресвяти́я Богоро́диці і нарещи́ ю Спори́тельниця хлібо́в, я́ко Ти, Пресвята́я Ді́во, спаса́єши лю́ди Твоя́ от гла́да, защища́єши я от смертоно́снаго вре́да і па́губи, да́руєши землі́ плодоно́сіє, посила́єши дождь ра́нній і по́здній на ни́ви і поля́ на́ша. Ті́мже вопіє́м Тебі́ такова́я:","Ра́дуйся, Ді́во, христия́н похвало́;","ра́дуйся, я́ко блажа́ть Тя всі ро́ди.","Ра́дуйся, я́ко Ти хлі́би на́ша благословля́єши і споря́єши;","ра́дуйся, я́ко Ти нас от гла́да ізбавля́єши.","Ра́дуйся, пита́ющая нас Хлі́бом Жи́зні;","ра́дуйся, млеко́м пита́вшая Пита́теля вселе́нния.","Ра́дуйся, Плода́ безсме́ртнаго стяжа́ніє;","ра́дуйся, Сади́теля жи́зні на́шея ро́ждшая.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 3","ps":["Си́лою сви́ше укріпи́ нас, благода́тная Влади́чице, во дні гла́да і па́губи, да не поги́бнем лю́ті без покая́нія во уни́нії і отча́янії, но утверди́ і наста́ви нас в терпі́нії і благоугожде́нії Бо́гові, да разумі́єм в напа́стіх і ско́рбіх во́лю Єго́ святу́ю, благу́ю і соверше́нную, непреста́нно взива́юще к Нему́ хвале́бним гла́сом: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи любо́во ве́лію к лю́дем, іскупле́нним Честно́ю Кро́вію Си́на Твоєго́ і Бо́га, Богома́ти Пречи́стая, прия́ла єси́ от Него́ власть устроя́ти і покрива́ти род христия́нський. Ти бо бе́дствующим Помо́щниця єси́ ско́рая, градо́м і ве́сем, се́лам і ни́вам і всему́ ми́ру покро́в. Тебі́, Милосе́рдной і Боголюби́вой Ма́тері на́шей, устроя́ющей і направля́ющей ко спасе́нію земну́ю жизнь на́шу, со смире́нієм глаго́лем:","Ра́дуйся, Блага́го Си́на Блага́я Ма́ти;","ра́дуйся, непреста́нно моля́щаяся о спасе́нії нас грі́шних.","Ра́дуйся, о всем ми́рі христия́нстім к Бо́гу Хода́тайце;","ра́дуйся, благ вся́чеських Всеблага́я Пода́тельнице.","Ра́дуйся, пліне́нних і в темни́цях заключе́нних Пита́тельнице;","ра́дуйся, тілесе́м на́шим здра́віє і душа́м спасе́ніє.","Ра́дуйся, я́ко рай пи́щний процвіта́єши;","ра́дуйся, я́ко приста́нище душа́м гото́виши.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 4","ps":["Бу́ря проти́вних ві́тров, єгда́ на́йдеть на ни внеза́пно, гро́ми і мо́лнії, град і вода́ мно́гая устрем'я́ться на зе́млю, тогда́, Госпоже́ Всеми́лостивая, ускори́ на по́мощ нам безпомо́щним, защити́ і ізба́ви нас от дожде́внаго лія́нія, єго́же сотвори́хомся досто́йнії гріх ра́ди на́ших, і да бу́дуть поля́ і ни́ви невреди́ми от сих, і да не потопи́ть нас бу́ря водна́я. Тебі́ бо грі́шнії і́мами Засту́пницю непости́дную, на Тя упова́ніє на́ше возлага́єм і, прославля́юще си́лу моли́тв Твої́х, ро́ждшемуся от Тебе́ Спа́су ми́ра зове́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і ви́дяще Твоє́ сострада́ніє, Влади́чице, к бе́дствующим і ги́бнущим лю́дем, ми грі́шнії прибіга́єм к Тебі́ і мо́лимся: о Пресвята́я Ді́во, усли́ши нас, і во дні, єгда́ со́лнце ізсуши́ть зе́млю і от су́хости зной бу́деть, і прозябе́нія земна́я начну́ть ув'яда́ти, тогда́, Влади́чице, ро́су благода́ті Твоєя́ низпосли́ на тре́бующия і прося́щия ми́лости, возвесели́ лице́ землі́ люде́й ра́ди Твої́х, і младе́нець їх, і ското́в, і іни́х всіх, і́же ча́ють к Бо́гу да́ти пи́щу їм во бла́го вре́м'я, і от святи́я іко́ни Твоєя́ Спори́тельници яви́ милосе́рдіє Твоє́ вопію́щим Тебі́ такова́я:","Ра́дуйся, Моли́твеннице неусипа́ющая ко Христу́ Бо́гу, на ми́лость к нам Єго́ преклоня́ющая;","ра́дуйся, гнів Бо́жий, на ни пра́ведно дви́жимий, от глав на́ших отводя́щая.","Ра́дуйся, Ма́терним покро́вом Твої́м от вся́ких несча́стій нас охраня́ющая;","ра́дуйся, поля́ і ни́ви на́ша от запале́нія со́лнечнаго і зно́я спаса́ющая.","Ра́дуйся, Всеми́лостивая Усли́шательнице гласо́в на́ших моле́бних в ско́рбі і обстоя́ніїх;","ра́дуйся, жили́ща на́ша от огня́ спаса́ющая.","Ра́дуйся, держа́вная Скоропомо́щнице на́ша во дні тя́жких іспита́ній;","ра́дуйся, от всіх бід ско́роє ізбавле́ніє.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ іко́на Твоя́, Богома́ти, лю́дем, прося́щим хлі́ба насу́щнаго, немерца́ємо сія́єть. Покро́вом бо Твоєя́ ми́лости соблюда́єши поля́ і ни́ви на́ша і плодоноси́ти їх устроя́єши, подвиза́ющи ві́рния вопи́ти Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя Тя Син Твой при Кресті́ стоя́щую с возлю́бленним ученико́м, глаго́леть Тебі́: Же́но, се син Твой. І ученику́: се Ма́ти твоя́, – всиновля́я Тебі́ вся ве́рующия в Него́. Ми же, ча́да Твоя́ су́ще, на Твой покро́в наді́ющеся, Тебі́, я́ко Ма́тері на́шей, глаго́лати дерза́єм:","Ра́дуйся, Судії́ Пра́веднаго умоле́ніє;","ра́дуйся, гріхо́в на́ших проще́ніє.","Ра́дуйся, наде́ждо на́ша ізві́стная;","ра́дуйся, упова́ніє на́ше непости́дноє.","Ра́дуйся, скорбе́й на́ших разріше́ніє;","ра́дуйся, печа́лей на́ших утоле́ніє.","Ра́дуйся, пла́мене страсте́й ізміня́ющая;","ра́дуйся, всіх родо́во весе́ліє.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 6","ps":["Пропові́дуєть Це́рков Христо́ва чудеса́ Твоя́, Богороди́тельнице, от восто́к бо до за́пад хва́льно і́м'я Твоє́, і ність гра́да іли́ страни́, іді́же не яви́шася Тобо́ю ді́йства си́ли Бо́жия, во ізбавле́ніє і спасе́ніє, просвіще́ніє і ісціле́ніє люде́й христоімени́тих, найпа́че же чрез іко́ни Твоя́ святи́я оби́кла єси́ чудотвори́ти, ізлива́ющи от них струї́ ми́лостей і щедро́т бі́дствующему і тре́бующему по́мощі челові́честву. Сего́ ра́ди славосло́в'яще Тя, Си́ну Твоєму́ і Бо́гу на́шему вопіє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ от І́стиннаго Со́лнця заря́, Ді́во Богоотрокови́це, просвіща́ющи ду́ші всіх томи́мих гла́дом душе́вним, рече́ бо Госпо́дь: не о хлі́бі єди́нім жив бу́деть челові́к, но о вся́ком глаго́лі, ісходя́щем із уст Бо́жиїх. Оба́че помрачи́шася о́чі на́ші і окамені́ша сердця́ на́ша, і не ви́дим очи́ма свої́ма і не разумі́єм се́рдцем суде́б Бо́жиїх. Томи́мії же душе́вним гла́дом к Тебі́ прибіга́єм, Пречи́стая Ді́во, і про́сим Сло́вом Жи́зні утоли́ти глад душе́вний нас, вопію́щих Тебі́ такова́я:","Ра́дуйся, от убо́жества душе́внаго нас воздвиза́ющая;","ра́дуйся, пита́ющая нас Сло́вом Жи́зні.","Ра́дуйся, трапе́зо пресві́тлая, Хліб Жи́зні носи́вшая;","ра́дуйся, пи́ще, ма́нни Приє́мнице.","Ра́дуйся, земле́ блага́я, Клас Боже́ственний ізрасти́вшая;","ра́дуйся, ни́во, растя́щая многопло́діє щедро́т.","Ра́дуйся, ка́меню, напої́вший жа́ждущия жи́зні;","ра́дуйся, ми́лость сугу́бо нам подаю́щая.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 7","ps":["Хотя́щи жа́ти спасе́ніє, я́ко село́ сла́дкоє показа́лася єси́, Влади́чице, от него́же пита́ющеся, і́мами пи́щу ві́чную і нетлі́нную. Ми же, земні́ї су́ще, мо́лим Тя, Пречи́стая Ді́во: покажи́ си́лу Твою́ в дні жа́тви нив і поле́й на́ших, да всяк злак ізоби́луєть на утіше́ніє нас, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно просла́вилася єси́, Богома́ти, в защище́нії люде́й правосла́вних. Возстаю́щії на Бо́га не познаю́ть, коль сильна́ єсть моли́тва Бо́жия Ма́тере. Ми же, о Твоє́м всемо́щнім заступле́нії, по́мощі і благослове́нії до́брі ві́дуще, си́це к Тебі́ со умиле́нієм зове́м:","Ра́дуйся, чи́стих рука́ма і се́рдцем земледі́льцев благослове́нними плода́ми вінча́ющая;","ра́дуйся, бе́дствующим среди́ напа́стей і трудо́во внеза́пноє вспоможе́ніє.","Ра́дуйся, безма́терніх сиро́т незри́мая Воспита́тельнице;","ра́дуйся, Помо́щнице всіх безпомо́щних.","Ра́дуйся, Корми́тельнице вдов і сиро́т;","ра́дуйся, подаю́щая си́лу, пи́щу і отра́ду боля́щим і разсла́бленним.","Ра́дуйся, оде́ждо наги́х дерзнове́нія;","ра́дуйся, мно́гих согріше́ній проще́ніє.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 8","ps":["Я́коже дре́вле соді́йствовала єси́ схожде́нію на зе́млю Спаси́теля ми́ра, си́це і ни́ні, я́ко со́лнце світоза́рноє, восхо́диши над созрева́ющею ни́вою, предше́ствующи прихо́ду Господи́на с жа́тельми. Тому́ і ми со стра́хом вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Все упова́ніє на́ше на Тя возлага́єм, Ма́ти Бо́жия, і в ско́рбіх на́ших ко святі́й іко́ні Твоє́й усе́рдно притека́єм, ча́юще получи́ти от Тебе́ утіше́ніє благода́тноє і вспоможе́ніє во оскуді́нії і нищеті́ на́шей, сего́ ра́ди взива́єм Ті:","Ра́дуйся, ми́лости превели́кия сокро́вище;","ра́дуйся, пи́ще і утіше́ніє к Тебі́ прибіга́ющих.","Ра́дуйся, хлі́бе несніда́ємий а́лчущих;","ра́дуйся, ско́роє ни́щих усли́шаніє.","Ра́дуйся, от гла́да і ну́жди скорб'я́щих прия́тноє попече́ніє;","ра́дуйся, к Сві́ту Непристу́пному нас ізводя́щая.","Ра́дуйся, ключу́ Ца́рствія Христо́ва;","ра́дуйся, наде́ждо благ ві́чних.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 9","ps":["Всі лю́діє див'я́ться вели́чію чуде́с Твої́х, Пресвята́я Ді́во, ізлива́ємих Тобо́ю от святи́х Твої́х іко́н, я́ко всім да́руєши по коєго́ждо проше́нію, устроя́єши до́ми на́ша, посила́єши благослове́ніє землі́ ді́лателем і дає́ши лю́дем вся́коє дово́льство. Ті́мже вопіє́м Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не мо́гуть воспі́ти чуде́с Твої́х, Богома́ти Влади́чице, я́ко всім конце́м землі́ простира́єши ру́ку по́мощі і низпосила́єши ві́рним землі́ плодоно́сіє, благорастворе́ніє возду́хов і вся́коє ізоби́ліє плодо́в і благ земни́х. Ми же, во смире́нії своє́м іспові́дающе Твоє́ вели́коє заступле́ніє нас грі́шних і непреста́нную по́мощ в ну́ждах на́ших, вопіє́м Ті:","Ра́дуйся, досто́йно восхваля́ємая от Арха́нгел і А́нгел;","ра́дуйся, велича́ємая от всіх Небе́сних Сил.","Ра́дуйся, честні́йшая Херуви́м;","ра́дуйся, сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, Влади́чице Не́ба і землі́;","ра́дуйся, Роди́тельнице Ві́чнаго Царя́.","Ра́дуйся, ві́рная Рабо́ Госпо́дня;","ра́дуйся, ублажа́ємая на Небесі́ і на землі́.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 10","ps":["Спаси́тельноє прибі́жище в ско́рбіх і напа́стіх Ти єси́, Богоро́дице, ті́мже іспроси́ у Си́на Твоєго́ і Бо́га на́шего ми́лости нам грі́шним, пою́щим: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ похваля́ющим чудеса́ Твоя́, Богоро́дице Ді́во, і всім с ві́рою притека́ющим і покланя́ющимся Тебі́ і іко́ні Твоє́й, Спори́тельниця хлібо́в імену́ємой, і глаго́лющим:","Ра́дуйся, неістощи́мий істо́чниче ми́лостей і щедро́т;","ра́дуйся, любве́ Боже́ственния проявле́ніє.","Ра́дуйся, чуде́с пресла́вних соверше́ніє;","ра́дуйся, тружда́ющихся і обремене́нних сла́дкий поко́ю.","Ра́дуйся, терпіли́вих страда́льцев да́ри благода́тними ущедря́ющая;","ра́дуйся, о хра́міх Бо́жиїх попече́ніє іму́щих духо́вною ра́достію утіша́ющая.","Ра́дуйся, несумні́нная на́ша наде́ждо;","ра́дуйся, ти́хоє і до́броє приста́нище.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше не пре́зри, Пресвята́я Ді́во, і сокро́вище любве́ Твоєя́ не затвори́ от нас; ще́друю ру́ку Твоєя́ по́мощі простри́ нам, да, прославля́юще ми́лості і чудеса́ Твоя́, поє́м Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с Твої́х просвіща́єши весь мир христия́нський і заступа́єши лю́ди правосла́вния, іскупле́нния Кро́вію Си́на Твоєго́. Ті́мже, припа́дающе ко свято́му о́бразу Твоєму́, на не́мже зрим Тя, Богома́ти, на возду́сі над поля́ми і ни́вами на́шими, благословля́ющую со́бранния снопи́ хлі́ба, мо́лим Тя, Всеми́лостивая Влади́чице: род челові́чеський, осужде́нний в по́ті лиця́ своєго́ сні́сти хліб, в болі́зніх роди́ти і в печа́ліх пита́ти ча́да своя́, ми́лостивно пощади́ і заступи́. Да́руй нам здра́віє і благомо́щіє, да, пита́ємії Тобо́ю, от си́ли в си́лу возраста́ти бу́дем і всі іспо́лнимся ра́дости і утіше́нія от щедрода́тельния десни́ці любве́ Твоєя́, зову́ще Тебі́:","Ра́дуйся, младе́нцев Млекопита́тельниці;","ра́дуйся, усти́ діте́й хвалу́ Бо́гові соверша́ющая.","Ра́дуйся, росо́ небото́чная в зно́ї трудо́в су́щим;","ра́дуйся, подаю́щая тре́бующим благостроє́ніє.","Ра́дуйся, прося́щим ізоби́ліє уготовля́ющая;","ра́дуйся, мно́гажди проше́нія предваря́ющая.","Ра́дуйся, печа́льних утіше́ніє;","ра́дуйся, скорб'я́щих весе́ліє.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 12","ps":["Благода́тную по́мощ низпосли́ нам, Ма́ти Бо́жия, і, єгда́ ізи́деть сі́яй сі́яти, да не паду́ть сі́мена при путі́, іли́ посреді́ те́рнія, іли́ на ка́мені, но на землі́ до́брій. Сотвори́ восхо́д їх, да проізрасти́ть земля́ плод стори́цею, і ми всі в ра́дості се́рдця благода́рними усти́ вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́ і ми́лости, Влади́чице Богоро́дице, хва́лим Тя всі, я́ко воі́стину єси́ на́ша Помо́щниця, Засту́пниця, Пита́тельниця і Домострої́тельниця, житіє́ на́ше ко спасе́нію устроя́ющая. Ті́мже вопіє́м Ті:","Ра́дуйся, бога́тство нетлі́нноє нам подава́ющая;","ра́дуйся, бра́шно неги́блющеє а́лчущим пра́вди.","Ра́дуйся, питіє́ неісчерпа́ємоє жа́ждущим жи́зні;","ра́дуйся, земле́ обітова́нія, із нея́же тече́ть мед і млеко́.","Ра́дуйся, ві́рних спаси́тельноє прибі́жище;","ра́дуйся, покро́ве ми́ру, ши́рший о́блака.","Ра́дуйся, ненаде́жних наді́яніє;","ра́дуйся, отча́янних спасе́ніє.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 13","ps":["О всепі́тая Ма́ти, ро́ждшая всіх святи́х Святі́йшеє Сло́во! Ни́нішнєє на́ше приє́мши приноше́ніє, ізба́ви лю́ди, к Тебі́ прибега́ющия, от вся́кия ну́жди, гла́да душе́внаго і тіле́снаго, смертоно́сних болі́зней і вся́каго зла і ві́чния ізми́ му́ки, да с ли́ки А́нгельськими непреста́нно поє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ Тя, Влади́чице, к благода́тному челові́ков спасе́нію і дарова́ Тя Помо́щницю лю́дем, ізбавля́ющую нас от гла́да і вся́ких напа́стей, житіє́ на́ше до́брі устроя́ющую в ми́рі і вся́ком дово́льстві. Ті́мже со умиле́нієм взива́єм Ті:","Ра́дуйся, благода́тноє челові́ков от вся́кия ну́жди ізбавле́ніє;","ра́дуйся, достоя́нію Твоєму́ по́мощ і заступле́ніє.","Ра́дуйся, христолюби́вия лю́ди от вся́ких бід спаса́ющая;","ра́дуйся, а́лчущих пита́ющая.","Ра́дуйся, си́рих заступле́ніє;","ра́дуйся, наги́х одія́ніє.","Ра́дуйся, ізрасти́вшая нам Плод Живота́;","ра́дуйся, ро́ждшая Спа́са душ на́ших.","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Влади́чице Небесе́ і землі́, ізбавля́ющей нас от вся́кия ну́жди, благода́рственноє прино́сим пі́ніє. Ти же, Всеми́лостивая Госпоже́ Богоро́дице, прийми́ на́ше усе́рдноє моле́ніє, сохрани́ нас от гла́да і па́губи, да́руй землі́ на́шей плодоно́сіє, Пита́тельнице і Спори́тельнице нив і хлібо́в на́ших, да ра́дующеся всегда́ зове́м Ті:","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, пода́ждь і нам недосто́йним ро́су благода́ті Твоєя́ і яви́ милосе́рдіє Твоє́."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во Богоро́дице, Преми́лостивая Влади́чице, Цари́це Небесе́ і землі́, вся́каго до́ма і семе́йства христия́нськаго Благоустрої́тельнице, тружда́ющихся благослове́ніє, нужда́ющихся неістощи́моє бога́тство, си́рих і вдови́ць і всіх люде́й Корми́тельнице! Пита́тельнице на́ша, ро́ждшая Пита́теля вселе́нния, і Спори́тельнице хлібо́в на́ших, Ти, Влади́чице, низпосила́єши Твоє́ Ма́тернеє благослове́ніє градо́м на́шим, се́лам і ни́вам і коєму́ждо до́му, на Тя упова́ніє іму́щему. Ті́мже с благогові́йним тре́петом і сокруше́нним се́рдцем смире́нно мо́лим Тя: бу́ди і нам, грі́шним і недосто́йним рабо́м Твої́м, му́драя Домострої́тельниця, житіє́ на́ше до́брі устроя́ющая. Всіх же прибіга́ющих к покро́ву Твоєму́, вся́кий дом і семе́йство во благоче́стії і Правосла́вії, єдиноми́слії, послуша́нії і дово́льстві соблюди́. Ни́щія і неіму́щия пропита́й, ста́рость поддержи́, младе́нці воспита́й, всіх вразуми́ преі́скренні взива́ти ко Го́споду: хліб наш насу́щний даждь нам днесь. Сохрани́, Пречи́стая Ма́ти, лю́ди Твоя́ от вся́кия ну́жди, болі́зні, гла́да, огня́, от вся́каго зла́го обстоя́нія і вся́каго нестроє́нія. Оби́телі [іли́: ві́си] на́шей [іли́: гра́ду на́шему], домо́м і семе́йством, і вся́кой душі́ христия́нськой, і всей страні́ на́шей ісхода́тайствуй мир і ве́лію ми́лость, да сла́вим Тя, Преми́лостивую Пита́тельницю і Спори́тельницю на́шу, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Пречи́стая Ді́во Марі́є, Ма́ти Царя́ Небесі́ і землі́, / благоутро́бно призира́єши на лю́б'ящих Си́на Твоєго́, Христа́ Бо́га на́шего, / і тружда́ющихся во і́м'я Єго́ ві́чнаго ра́ди спасе́нія, / і подає́ши їм вся оби́льно к наслажде́нію. / Спори́тельнице су́щи хлібо́в їм, / ізбавля́я їх вся́кия ну́жди і утісне́нія // і устроя́я їм, рабо́м Твої́м су́щим, ізбавле́ніє ві́чния му́ки і жизнь ві́чную."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті; / ускори́ на моли́тву і потщи́ся на умоле́ніє, // предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Поручителька грішних»","e":"Akathist to the Theotokos before her icon “Surety of Sinners”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от Всеви́шняго, грі́шних Спору́чнице, преклоня́ющей на милосе́рдіє Си́на Своєго́, да спасе́ть я́же созда́ руко́ю Своє́ю, благода́рственноє пі́ніє прино́сим Ті, Ма́ти Ді́во і Влади́чице, о явле́нії ди́вния Твоєя́ і чудотво́рния іко́ни, Ти же я́ко предста́тельство ко Го́споду іму́щи, потщи́ся от обстоя́ній многообра́зних ізба́вити ни і ві́чноє спасе́ніє нам соді́лати, да, воспіва́юще, вопіє́м Ті:","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Ікос 1","ps":["А́нгелов ли́ки благогові́йно Тебі́ слу́жать і святі́ї всі немо́лчними гла́си Тя ублажа́ють, Богоро́дице Ді́во, я́ко ро́ждшую А́нгелов Царя́, Христа́ Бо́га на́шего, ми же, грі́шнії, подража́ти їм дерза́юще і благохвали́ти Тя недоумі́юще, смиренному́дренно арха́нгельський глас вопіє́м Ті, Чи́стая:","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю;","ра́дуйся, Преблагослове́нная в жена́х, Ді́во Всенепоро́чная.","Ра́дуйся; Дщи Отця́ Небе́снаго;","ра́дуйся, Ма́ти Си́на Преві́чнаго.","Ра́дуйся, Ду́ха Свята́го селе́ніє;","ра́дуйся, А́нгелов і челові́к непреста́нноє удивле́ніє.","Ра́дуйся, Честні́йшая Херуви́м;","ра́дуйся, Сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 2","ps":["Ви́дящи Премилосе́рдная Ма́тер Бо́жия земно́є ско́рбноє житіє́ на́ше, не́мощі і болі́зні, благоізво́ли да́ти нам в благослове́ніє і утіше́ніє, в ра́дость і спасе́ніє і от вся́ких бід і напа́стей огражде́ніє іко́ну Свою́ святу́ю, Спору́чницею грі́шним в ней наре́кшися, да, ра́достная пред се́ю іко́ною Єй принося́ще, ра́достно всегда́ пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний открива́ющи, Богоро́дице Ді́во, благоізво́лила єси́ мно́гими чудеси́ просла́вити іко́ну Твою́ святу́ю, Спору́чниця грі́шних імену́ємую, да всі, ві́дуще таково́є Твоє́ о ней благоволе́ніє, пі́сненно Тебі́ зову́ть:","Ра́дуйся, Милосе́рдая, всіх нас о Христі́ Ма́ти;","ра́дуйся, неістощи́мая сокро́вищнице Боже́ственния благода́ті.","Ра́дуйся, Тобо́ю бо нисхо́дить к нам Бо́жиє благоволе́ніє;","ра́дуйся, Тобо́ю бо і́мами вя́щшеє к Бо́гу дерзнове́ніє.","Ра́дуйся, моли́тви всіх христия́н приє́млющая;","ра́дуйся, і са́мих отча́янних грі́шников моле́нія не отверга́ющая.","Ра́дуйся, я́ко предста́тельством Твої́м спасти́ся упова́єм;","ра́дуйся, я́ко моли́твами Твої́ми Ца́рство Небе́сноє получи́ти ча́єм.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 3","ps":["Си́ла благода́тная осіня́єть всіх, Преблагослове́нная Ма́тер Бо́жия, с ві́рою к Тебі́, я́ко Спору́чнице грі́шних, притека́ющих і святі́й іко́ні Твоє́й покланя́ющихся: Єди́ній бо то́кмо Тебе́ даде́ся дар вся́коє благо́є проше́ніє ско́ро ісполня́ти і грі́шних ми́ловати і спаса́ти, і Єди́на то́кмо Ти мо́жеши воі́стину всім помощі́ єли́ка хо́щеши, Бо́гу пою́щим: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я Ма́тернєє о всіх всеблаго́є промишле́ніє, Ти, Всеблага́я Ма́ти Бо́жия, і са́мих отча́янних грі́шников ко спасе́нію призива́єши, глаго́лющи: Аз єсьм Спору́чниця грі́шних к Си́ну Моєму́ і Бо́гу, І́же і обіща́ Мні сли́шати М'я всегда́, да ра́достная Мні принося́щії ві́чно ра́доватися бу́дуть чрез Мене́. Сего́ ра́ди ми, грі́шнії, Тебі́, я́ко Спору́чнице на́шей, ра́достно зове́м:","Ра́дуйся, Засту́пнице усе́рдная, от Бо́га нам дарова́нная;","ра́дуйся, к Небе́сному оте́честву Путеводи́тельнице на́ша Благода́тная.","Ра́дуйся, от ро́ва поги́белі ісхища́ющая;","ра́дуйся, безпомо́щних на Свої́ всемо́щния ру́ці приє́млющая.","Ра́дуйся, непреста́нноє уни́ніє отгоня́ющая;","ра́дуйся, па́дших ко благода́ті возставля́ющая.","Ра́дуйся, сло́во прему́дрости прося́щим да́рующая;","ра́дуйся, і неразу́мних разу́мними соде́ливающая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 4","ps":["Бу́рею сомні́ній іскуша́ємая ні́кая жена́ не хотя́ше ві́ровати чудесе́м, от іко́ни Твоєя́, Спору́чници, бива́ємим, но внеза́пну я́звою смертоно́сною пораже́нная, позна́ си́лу Твою́ всемо́щную, Влади́чице, і чудотво́рния іко́ни Твоєя́ благода́ть, і, раска́явшися, сле́зно моля́ше Тя о проще́нії неві́рствія єя́, милосе́рдієм же Твої́м ісцеле́нная, благода́рственно Бо́гу о Тебі́ всегда́ вопія́ше: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шить Госпо́дь Твоя́ о нас на Небесі́ хода́тайства, Цари́це Небе́сная, і ісполня́єть Твоя́ проше́нія, ми же, грі́шнії, я́ко всеблагу́ю Скоропослу́шницю і Спору́чницю на́шу, про́сим і мо́лим Тя: Влади́чице, ско́ро усли́ши моле́нія на́ша і вся на́ша печа́лі на ра́дость преложи́, і проше́нія всіх зді моля́щихся ско́ро іспо́лни, да ра́достно всегда́ поє́м Ті:","Ра́дуйся, принося́щая к Си́ну Твоєму́ і Бо́гу моле́нія ві́рних;","ра́дуйся і Сама́ у престо́ла Си́на Твоєго́ всегда́ о нас моля́щаяся.","Ра́дуйся, Спору́чнице грі́шних;","ра́дуйся, Взиска́ніє поги́бших.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая;","ра́дуйся, і на́ша проше́нія ско́ро ісполня́ющая.","Ра́дуйся, Ми́лостивая, всегда́ нас ми́лующая;","ра́дуйся, житіє́ на́ше до́броє устроя́ющая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 5","ps":["Я́ко лучеза́рную звізду́, весь мир озаря́ющую, подава́ла єси́ нам, Влади́чице Ми́ра, честну́ю Твою́ іко́ну, Спору́чницею грі́шних імену́ємую, на ню́же взира́юще, Само́й Тебі́, і́стинній Бо́жієй Ма́тері і Ді́ві, покланя́ємся, глаго́люще: Влади́чице, прийми́ моли́тви раб Твої́х і ізба́ви ни от вся́кия ну́жди і печа́лі, восхваля́ющих Тя і Бо́гу воспіва́ющих: Аллилу́я."]},{"h":"Ікос 5","ps":["Ні́кий благогові́йний муж стра́хом ве́ліїм преіспо́лнися, єгда́ в нощ Сві́тлаго Христо́ва Воскресе́нія ви́ді іко́ну Твою́, Спору́чнице Всеблага́я, сві́том Небе́сним блиста́ющуюся і, я́ко дожде́вния ка́плі, ми́ро істоча́ющую і молнієви́дния і́скри іспуща́ющую, позна́во в сем зна́менії ми́лости Твоєя́ к лю́дем, со слеза́ми умиле́нія і благодаре́нія ра́достно воспі́ Тебі́, Преблагослове́нній Ма́тері Бо́жієй:","Ра́дуйся, Огнь Боже́ственний неопа́льно держа́вшая, І́мже гріхи́ на́ша попаля́ються;","ра́дуйся, Світ неприкоснове́нний носи́вшая, І́мже ду́ші на́ша просвіща́ються.","Ра́дуйся, ру́ці Свої́ в поруче́ніє о нас Бо́гу принося́щая;","ра́дуйся, вход в Ца́рство Небе́сноє і нам, грі́шним, отверза́ющая.","Ра́дуйся, я́ко мо́лнія тьму гріхо́в на́ших разсека́ющая;","ра́дуйся, я́ко ми́ро благово́нноє, сердця́ на́ша ум'ягча́ющая.","Ра́дуйся, істо́чники чуде́с всю́ду істоча́ющая;","ра́дуйся, іко́ною Твоє́ю вся лю́ди возвеселя́ющая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 6","ps":["Весь мир христия́нський пропові́дуєть ми́лості і чудеса́ Твоя́, Препросла́вленная Ма́ти Го́спода, і сві́тло красу́ється мно́гими чудотво́рними Твої́ми іко́нами, среди́ ко́їх іко́на Твоя́, Спору́чниця грі́шних імену́ємая, я́ко луна́ по́лная, луча́ми ми́лости Твоєя́ і чуде́с немерца́ємо сія́єть, просвіща́ющи і освіща́ющи ду́ші на́ша сві́том Бо́жия благода́ті, подвиза́ющи нас хвале́бно Бо́гу взива́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в одну́ із ноще́й світ небе́сний в хра́мі Нико́ло-Хамо́вничеськом, єгда́ прия́т о́браз Твой чудотво́рний, Спору́чнице грі́шним, світи́льники тогда́ і лампа́ди неви́димою си́лою в хра́мі сем возжига́хуся, свіща́ горя́щая, а́ки в служе́нії, незри́мо кім о́крест престо́ла ноша́шеся. Лю́діє же, вні хра́ма стоя́вшії і сія́ вся ви́дівше, дивля́хуся, сла́в'яще Тя, Ма́ти Бо́жия, і Си́на Твоєго́, ми же, воспомина́юще ди́вноє сіє́ виді́ніє, с умиле́нієм Тебі́ глаго́лем:","Ра́дуйся, ско́рби на́ша в ра́дость претворя́ющая;","ра́дуйся, ненаді́ющихся несомні́нною наде́ждою возвеселя́ющая.","Ра́дуйся, Свіще́, у престо́ла Бо́жия присногоря́щая;","ра́дуйся, Лампа́до, єле́єм Боже́ственним світя́щая.","Ра́дуйся, Сві́те лучеза́рний, путь жи́зні нам показу́ющий;","ра́дуйся, Хра́мі одушевле́нний, всіх нас освяща́ющий.","Ра́дуйся, упова́ющим на Тя непости́дную жизнь да́рующая;","ра́дуйся, і по сме́рті неотсту́пно о них пред Бо́гом хода́тайствующая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 7","ps":["Хотя́ Долготерпіли́вий Госпо́дь яви́ти Бе́здну Своєго́ человіколю́бія і щедро́т, ізбра́ Тебі́, Пресвята́я Ді́во, в Ма́тер Себе́ і яви́ Тя неісчерпа́ємий істо́чник ми́лостей Свої́х, да а́ще кто пра́ведним судо́м Бо́жиїм осужде́нія досто́їн, Твої́м хода́тайством, я́ко грі́шним Спору́чници, сохране́н бу́деть, велегла́сно зови́й: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вная діла́ Твоя́ показа́л єси́ нам, Го́споди, в Пречи́стій Твоє́й Ма́тері і ди́вну дарова́л єси́ нам Єя́ іко́ну, па́че луче́й со́лнечних просвіща́ющую лю́ди, я́ко Са́мую зря́щих Богоро́дицю і ві́рою серде́чною от душі́ любо́вію, я́ко Бо́жієй Ма́тері і Ді́ві, Єй вопію́щих:","Ра́дуйся, Купе́ле, в Не́йже вся ско́рбі на́ша погружа́ються;","ра́дуйся, Ча́ше, Є́юже ра́дость і спасе́ніє всі восприє́млем.","Ра́дуйся, Живоно́сний Істо́чниче, всіх нас оживотворя́ющий;","ра́дуйся, Цві́те неув'яда́ємий, всіх нас облагоуха́ющий.","Ра́дуйся, скорбе́й на́ших услажде́ніє;","ра́дуйся, печа́лей на́ших утоле́ніє.","Ра́дуйся, болі́зней на́ших врачева́ніє;","ра́дуйся, от бід ско́роє на́ше ізбавле́ніє.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 8","ps":["Стра́нники і прише́льці єсьми́ на землі́ і, по глаго́лу Апо́стола, не і́мами зді пребива́ющаго гра́да. Но ко кому́ прибі́гнем, Влади́чице, в ско́рбіх житія́ на́шего, а́ще не к Тебі́, Всеблага́я Спору́чнице о нас грі́шних! Не отве́ржи нас, Ма́ти Бо́жия, і не рци нам: Не вім вас гріхо́в ра́ди ва́ших, но поми́луй нас, си́рих і безпомо́щних, і прийми́ нас во ві́чния кро́ви, Покрови́тельнице на́ша, да ра́достно вопіє́м во сла́ві Небе́сній Царю́ сла́ви Христу́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім ві́рним уті́шительно єсть взира́ти на святу́ю іко́ну Твою́, Влади́чице, Спору́чнице грі́шним, на не́йже зрим Тя, на руку́ Твоє́ю держа́щую Преві́чнаго Младе́нця, Го́спода на́шего Ісу́са Христа́, Єму́ же покланя́ющеся боголі́пно, я́ко Творцю́ і Бо́гу на́шему, Тебі́, і́стинній Богоро́дице, уми́льно глаго́лем: Влади́чице, помози́, на ни милосе́рдовавши, потщи́ся, погиба́єм от мно́жества прегріше́ній, не отврати́ Твоя́ раби́ тщи, Тебі́ вопію́щия:","Ра́дуйся, Ціли́тельнице на́ша в болі́зніх тіле́сних;","ра́дуйся, Уті́шительнице в печа́ліх на́ших душе́вних.","Ра́дуйся, а́лчущих Пита́тельнице;","ра́дуйся, наги́х одія́ніє.","Ра́дуйся, вдов Защи́тительнице;","ра́дуйся, сиро́т Покрови́тельнице.","Ра́дуйся, гони́мих і оби́димих Засту́пнице;","ра́дуйся, стра́ждущих і пліне́нних ско́рая Освободи́тельнице.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє похва́льния піснопі́нія прино́сить Тебі́, Бо́жієй Ма́тері і Спору́чнице всіх припа́дающих Тебі́ і прося́щих Твоєя́ по́мощі і Твоєго́ утіше́нія, я́ко тве́рдим і крі́пким Твої́м предста́тельством пра́ведних весели́ши, грі́шних заступа́єши і от бід ізбавля́єши і печа́лі утоля́єши, і мо́лишися о всіх, ві́рою зову́щих о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йствующий всяк язи́к недоумі́єть благохвали́ти Тя по достоя́нію, ізуміва́єть же ум і преми́рний пі́ти Тя, Богоро́дице; оба́че, Блага́я су́щи, ві́ру прийми́, і́бо любо́во ві́си боже́ственную на́шу; Ти бо христия́н єси́ Предста́тельниця, Тебі́ зову́щих:","Ра́дуйся, сія́нієм Пречи́стия душі́ Твоєя́ всю зе́млю просвіти́вшая;","ра́дуйся, чистото́ю тілесе́ Твоєго́ вся небеса́ возвесели́вшая.","Ра́дуйся, всіх нас при Кресті́ Си́на Твоєго́ усинови́вшая;","ра́дуйся, всегда́ Ма́тернюю любо́в Твою́ к нам явля́ющая.","Ра́дуйся, всіх даро́в духо́вних і тіле́сних всемо́щная Пода́тельнице;","ра́дуйся, благ вре́менних і ві́чних усе́рдная нам Хода́тайце.","Ра́дуйся, две́рі Ца́рствія Христо́ва ві́рним отверза́ющая;","ра́дуйся, і на землі́ ра́достію і весе́лієм сердця́ на́ша ісполня́ющая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́чеський от ві́чния му́ки і непрестаю́щия ско́рби, Человіколю́бець Госпо́дь Тебе́, Ма́тер Свою́, дарова́ земни́м на по́мощ, глаго́ля: си́нове челові́честії, се Ма́ти Моя́ покро́в і прибі́жище вам да бу́деть, печа́льним — утіше́ніє, скорб'я́щим — ра́дованіє, оби́димим — Засту́пниця, бе́дствующим — по́мощ, больни́м — Ціли́тельниця, грі́шним — Спору́чниця, да всіх із глубини́ гріхо́вния воздви́гнеть, вопію́щих: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Небе́сний, Си́не і Бо́же Мой, — та́ко мо́лить за нас всегда́ Небе́сная Цари́ця, — прийми́ вся́каго челові́ка, сла́в'ящаго Тя і призива́ющаго І́м'я Твоє́ Свято́є, і прославля́ющих М'я І́мені Твоєго́ ра́ди, і не отри́ни їх от лиця́ Твоєго́, но благоволи́ в них і прийми́ от них вся́коє благо́є моле́ніє і всіх от бід ізба́ви. Ми же, грі́шнії, наді́ющіїся на Твоя́ Ма́тернія моли́тви, зове́м Ті:","Ра́дуйся, я́ко Ти єси́ Моли́твенниця на́ша к Бо́гу те́плая;","ра́дуйся, я́ко Твоя́ моли́тва всегда́ пред Бо́гом многомо́щна.","Ра́дуйся, Твої́ми моли́твами і на́ша убо́гія моле́нія богоприя́тними соде́ловающая;","ра́дуйся, і на́ше недосто́їнство Твої́м предста́тельством восполня́ющая.","Ра́дуйся, ка́ющихся грі́шников непости́дная Спору́чнице;","ра́дуйся, всіх христия́н правосла́вних Засту́пнице.","Ра́дуйся, вся на́ша болі́зні ісціля́ющая;","ра́дуйся, о́блак страсте́й і іскуше́ній разгоня́ющая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прийми́ от нас, Небе́сная Спору́чнице на́ша, і моли́тву, приноси́мую Тебі́, Ді́во Богоро́дице, ско́ро усли́ши; к Тебі́ бо в напа́стіх, ско́рбіх і печа́ліх прибіга́єм і пред Тобо́ю в біда́х на́ших сле́зи пролива́єм і мо́лим: Влади́чице, утоли́ печа́лі і прийми́ моли́тви раб Твої́х, о Тебі́ пою́щих: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми зна́меній і чуде́с немерца́ємо сія́єть свята́я іко́на Твоя́, Богоро́дице Ді́во, і всіх благода́тно озаря́єть, с ві́рою пред не́ю Тебі́ моля́щихся, прогоня́ющи вся́коє вра́жиє ді́йство си́лою Бо́жиєю, от нея́ ісходя́щею. Ті́мже ра́дуємся ми, грі́шнії, іму́ще такову́ю чу́дную іко́ну Твою́ в хра́мі своє́м, я́ко зало́г Твоєго́ к нам і хра́му на́шему благоволе́нія, і Тебі́, Спору́чнице на́шей і Скоропослу́шнице моле́ній на́ших, благода́рственно взива́єм:","Ра́дуйся, ра́дость благода́тную нам ізлива́ющая;","ра́дуйся, утіше́ніє духо́вноє ско́ро нам подаю́щая.","Ра́дуйся, жела́нія богоуго́дния ісполня́ющая;","ра́дуйся, во вся́ких ско́рбних обстоя́ніїх на по́мощ нам поспеша́ющая.","Ра́дуйся, во ві́рі і благоче́стії живу́щих зіло́ лю́б'ящая;","ра́дуйся, сердця́ їх любо́вію к Бо́гу і лю́дем воспламеня́ющая.","Ра́дуйся, в час недоумі́нія мисль бла́гу на се́рдці полага́ющая;","ра́дуйся, во всем упова́ніє на Бо́га імі́ти нас науча́ющая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия, прису́щая святі́й Твоє́й іко́ні, Спору́чницею грі́шних імену́ємой, Богома́ти Влади́чице, влече́ть к ней всіх скорб'я́щих і гріхми́ мно́гими і напа́стьми обремене́нних, і не тщи отхо́дять они́ от сего́ істо́чника многообра́зних Твої́х ми́лостей і щедро́т, но в ско́рбіх — отра́ду, в напа́стіх — защи́ту, в боле́знях — цільбу́ і вся для душі́ і тіле́с благопотре́бная неоску́дно получа́ють от чудотво́рнаго о́браза Твоєго́, Всеблага́я, а́ще по Бо́зі все упова́ніє на Тя возлага́ють, пою́ще: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще неізрече́нноє Твоє́ Ма́тернеє к нам грі́шним милосе́рдіє, хва́лим Тя, я́ко Всемо́щную Спору́чницю на́шу, благослови́м Тя, я́ко Всеблагу́ю Скоропослу́шницю моле́ній на́ших, і со умиле́нієм покланя́ємся Тебі́ в честні́й Твоє́й іко́ні, ві́руєм бо і упова́єм, я́ко і ни́ні іспро́сиши нам у Си́на Твоєго́ і Бо́га, да в жи́зні сей і по сме́рті на́шей милосе́рдіє Єго́ неотсту́пно бу́деть о всіх, с любо́вію пою́щих Ті:","Ра́дуйся, Твої́ми моли́твами весь мир спаса́ющая;","ра́дуйся, Твої́ми хода́тайстви всю Вселе́нную заступа́ющая.","Ра́дуйся, я́ко всім с ві́рою притека́ющим ско́ро помога́ющая;","ра́дуйся, і Небе́снаго Ца́рствія їм іспроша́ющая.","Ра́дуйся, я́ко на іко́ну Твою́ взира́юще, Само́й Тебі́, і́стинній Богоро́дице, покланя́ємся;","ра́дуйся, Твої́м предста́тельством вся блага́я жела́нія на́ша ско́ро ісполня́ющая.","Ра́дуйся, і в час сме́ртний ві́рних Свої́х не оставля́ющая;","ра́дуйся, і по сме́рті о ві́чно блаже́ннім їх упокоє́нії хода́тайствующая.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, Всеблага́я Спору́чнице спасе́нія грі́шних, Богоро́дице Ді́во! Прийми́ ми́лостиво і ни́нішнєє на́ше моле́ніє, є́же от усе́рдія на́шего во благодаре́ніє Ті принесо́хом, і іспроси́ нам у Всеще́драго Бо́га во ві́рі правосла́вній непоколеби́мость, в любві́ христия́нськой преуспі́яніє і гріхо́в на́ших проще́ніє, да предста́тельством Твої́м унасле́дим Ца́рствіє Небе́сноє і сподо́бимся со всі́ми святи́ми пі́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ли́ки благогові́йно Тебі́ слу́жать і святі́ї всі немо́лчними гла́си Тя ублажа́ють, Богоро́дице Ді́во, я́ко ро́ждшую А́нгелов Царя́, Христа́ Бо́га на́шего, ми же, грі́шнії, подража́ти їм дерза́юще і благохвали́ти Тя недоумі́юще, смиренному́дренно арха́нгельський глас вопіє́м Ті, Чи́стая:","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю;","ра́дуйся, Преблагослове́нная в жена́х, Ді́во Всенепоро́чная.","Ра́дуйся; Дщи Отця́ Небе́снаго;","ра́дуйся, Ма́ти Си́на Преві́чнаго.","Ра́дуйся, Ду́ха Свята́го селе́ніє;","ра́дуйся, А́нгелов і челові́к непреста́нноє удивле́ніє.","Ра́дуйся, Честні́йшая Херуви́м;","ра́дуйся, Сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Кондак 1","ps":["Ізбра́нній от Всеви́шняго, грі́шних Спору́чнице, преклоня́ющей на милосе́рдіє Си́на Своєго́, да спасе́ть я́же созда́ руко́ю Своє́ю, благода́рственноє пі́ніє прино́сим Ті, Ма́ти Ді́во і Влади́чице, о явле́нії ди́вния Твоєя́ і чудотво́рния іко́ни, Ти же я́ко предста́тельство ко Го́споду іму́щи, потщи́ся от обстоя́ній многообра́зних ізба́вити ни і ві́чноє спасе́ніє нам соді́лати, да, воспіва́юще, вопіє́м Ті:","Ра́дуйся, грі́шним Спору́чнице, всегда́ о нас ру́ці Свої́ в поруче́ніє Бо́гу принося́щая."]},{"h":"Молитва","ps":["О Влади́чице Преблагослове́нная, Защи́тнице ро́да христия́нськаго, прибі́жище і спасе́ніє притека́ющих к Тебі́! Вім, воі́стину вім, я́ко зіло́ согріши́х і прогні́вах, Преми́лостивая Госпоже́, рожде́ннаго пло́тію от Тебе́ Си́на Бо́жия, но і́мам мно́гії о́брази пре́жде мене́ прогні́вавших Єго́ благоутро́біє: митарі́, блудни́ці і про́чія грі́шники, і́мже даде́ся проще́ніє гріхо́в їх, покая́нія ра́ди і іспові́данія. Ти́я у́бо о́брази поми́лованних очесе́м грі́шния душі́ моєя́ представля́я і на толи́коє Бо́жиє милосе́рдіє, о́ніх приє́мшеє, взира́я, дерзну́х і аз, грі́шний, прибі́гнути с покая́нієм ко Твоєму́ благоутро́бію. О Всеми́лостивая Влади́чице, да пода́си мі ру́ку по́мощі і іспро́сиши у Си́на Твоєго́ і Бо́га Ма́терніми і святі́йшими Твої́ми моли́твами тя́жким мої́м гріхо́м проще́ніє. Ві́рую і іспові́дую, я́ко Той, Єго́же родила́ єси́, Син Твой, єсть воі́стину Христо́с, Син Бо́га Жива́го, Судія́ живи́х і ме́ртвих, воздая́й кому́ждо по діло́м єго́. Ві́рую же па́ки і іспові́дую Тебі́ би́ти і́стинную Богоро́дицю, милосе́рдія істо́чник, утіше́ніє пла́чущих, взиска́ніє поги́бших, си́льную і непрестаю́щую к Бо́гу Хода́таїцю, зіло́ лю́б'ящую род христия́нський, і Спору́чницю покая́нія. Воі́стину бо ність челові́ком іни́я по́мощі і покро́ва, ра́зві Тебе́, Госпоже́ Преми́лостивая, і нікто́же, упова́я на Тя, постиді́ся когда́ і, Тобо́ю умоля́я Бо́га, нікто́же оста́влен бисть. Того́ ра́ди молю́ Твою́ неісче́тную бла́гость: отве́рзи две́рі милосе́рдія Твоєго́ мні, заблу́ждшему і па́дшему в тимі́ніє глубини́, не возгнуша́йся мене́, скве́рнаго, не пре́зри грі́шнаго моле́нія моєго́, не оста́ви мене́, окая́ннаго, я́ко в поги́бель зло́бний враг похи́тити м'я і́щеть, но умоли́ о мні рожде́ннаго от Тебе́ милосе́рдаго Си́на Твоєго́ і Бо́га, да прости́ть вели́кия моя́ гріхи́ і ізба́вить м'я от па́губи моєя́; я́ко да і аз со всі́ми, получи́вшими проще́ніє, воспою́ і просла́влю безмі́рноє милосе́рдіє Бо́жиє і Твоє́ непости́дноє о мні заступле́ніє в жи́зні сей і в несконча́ємом ві́ці. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Умолка́єть ни́ні вся́коє уни́ніє / і страх отча́янія ісчеза́єть, / грі́шници в ско́рбі се́рдця обріта́ють утіше́ніє / і Небе́сною любо́вію озаря́ються сві́тло: / днесь бо Ма́тер Бо́жия простира́єть нам спаса́ющую ру́ку / і от Пречи́стаго о́браза Своєго́ віща́єть, глаго́лющи: / Аз Спору́чниця грі́шних к Моєму́ Си́ну, / Сей дал Мні за них ру́ці сли́шати М'я ви́ну. / Ті́мже, лю́діє, обремене́ннії гріхи́ мно́гими, / припаді́те к подно́жію іко́ни Єя́, со слеза́ми вопію́ще: / Засту́пнице ми́ра, грі́шним Спору́чнице, / умоли́ Ма́терніми Твої́ми моли́твами Ізба́вителя всіх, / да Боже́ственним всепроще́нієм покри́єть гріхи́ на́ша / і сві́тлия две́рі ра́йськія отве́рзеть нам, // Ти бо єси́ предста́тельство і спасе́ніє ро́да христия́нськаго."]},{"h":"Інший тропар, глас 3","ps":["Тебі́, милосе́рдія істо́чнику при́сно теку́щему / і Спору́чнице грі́шних, недосто́йнії раби́ Твої́, Богоро́дице, / припа́дающе, скорб'я́ще, вопіє́м Ті: / спаса́й нас от бід, Влади́чице, // і ма́терним Твої́м хода́тайством іспроси́ всім нам ві́чноє спасе́ніє."]},{"h":"Кондак, глас 1","ps":["Честно́є жили́ще би́вшеє / неізрече́ннаго єстества́ Боже́ственнаго / ви́ше сло́ва і па́че ума́ / і грі́шним єси́ Спору́чниця, / подава́єши благода́ть і ісціле́ніє, / я́ко Ма́ти всіх Ца́рствующаго: / моли́ Си́на Твоєго́ // получи́ти нам ми́лость в День су́дний."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Трьох радостей»","e":"Akathist to the Theotokos before her icon “Three Joys”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді не умолчи́м нікогда́ глаго́лати ми недосто́йнії, Всесвята́я Ді́во, ро́ждшая на спасе́ніє на́ше Ра́дость ві́чную, вся́коє уни́ніє і печа́ль отжени́ от нас, да зове́м Ті:","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Ікос 1","ps":["Та́йну от ві́ка открива́я Тебі́, Пренепоро́чная Ді́во, Гавриї́л, безпло́тних архістрати́г, со стра́хом вопія́ше: Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю! Ми же грі́шнії нечи́стими устна́ми дерза́єм вопи́ти Тебі́ си́це:","Ра́дуйся, благослове́нная в жена́х;","ра́дуйся, Богоневі́сто.","Ра́дуйся, виногра́дная лозо́;","ра́дуйся, в рождестві́ і по рождестві́ Ді́ва.","Ра́дуйся, цві́те неув'яда́ємий;","ра́дуйся, чистоти́ сокро́вище.","Ра́дуйся, кади́ло благово́нноє;","ра́дуйся, ми́ро многоце́нноє.","Ра́дуйся, одушевле́нная трапе́зо;","ра́дуйся, Сві́та невече́рняго жили́ще.","Ра́дуйся, всего́ ми́ра очище́ніє;","ра́дуйся душ на́ших освяще́ніє.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 2","ps":["Іспо́лни весе́лія се́рдце моє́, утоли́ печа́ль мою́, Пресвята́я Ді́во! Просвіти́ сві́том нетления ра́дости мою́ ско́рбную ду́шу, да взива́ю Созда́телю моєму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський не мо́жеть уразумі́ти, ка́ко Ти, неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га і родила́ єси́ нетлі́ннаго Си́на, ті́мже со стра́хом взива́єм Тебі́:","Ра́дуйся, земле́ ненасі́янная;","ра́дуйся, купино́ неопали́мая.","Ра́дуйся, глубино́ неудобозри́мая;","ра́дуйся, мо́сте, к небесе́м приводя́й.","Ра́дуйся, лі́ствице висо́кая, ю́же Іа́ков ви́ді;","ра́дуйся, Боже́ственная ста́мно Ма́нни.","Ра́дуйся, разріше́ніє кля́тви;","ра́дуйся, Ада́мово воззва́ніє.","Ра́дуйся, врата́ а́дови сокруши́вшая;","ра́дуйся, тьму гріхо́вную разруши́вшая.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 3","ps":["Ти предста́тельство і покро́в моєя́ жи́зні, наде́жда і утвержде́ніє моє́, Всепі́тая, ісціли́ мою́ ду́шу, зараженную прока́зою гріхо́вною, да воспою́ Небе́сному Жениху́ во ві́ки: Аллилу́я."]},{"h":"Ікос 3","ps":["Всеви́шняго освяще́нноє Боже́ственноє селе́ніє, ра́дуйся, Тобо́ю бо даде́ся ра́дость Богоро́дице зовущим:","Ра́дуйся, чисті́йшая сві́тлостей со́лнечних;","ра́дуйся, пребива́ніє Творця́ не́ба і землі́.","Ра́дуйся, а́нгелов ра́досте;","ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє.","Ра́дуйся, Честні́йшая Херуви́м;","ра́дуйся, Сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, ра́дуйся, стіно́ і защище́ніє на́ше от враго́в;","ра́дуйся де́монов пораже́ніє і осліпле́ніє.","Ра́дуйся, ра́дуйся, две́рі ра́йськія нам отверза́ющая;","ра́дуйся, Марі́є, Госпоже́ всіх нас.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 4","ps":["Уни́нієм і мно́гими скорбми́ іспо́лнено моє́ се́рдце, ко кому́ же возопію́, Влади́чице, ко кому́ прибі́гну в го́ресті моє́й, кому́ возвіщу́ печа́ль мою́, кто плач і воздиха́ніє моє́ усли́шить, а́ще не Ти, Богоро́дице, ро́ждшая на ра́дость Не́бу і землі́ Царя́ Христа́ Бо́га на́шего, Єму́же пою́ть с на́ми Херуви́ми і Серафи́ми: Аллилу́я."]},{"h":"Ікос 4","ps":["Нікогда́ не умолчи́м і не отсту́пим от Тебе́, Влади́чице, Твоя́ бо раби́ спаса́єши при́сно от вся́ких лю́тих бід і скорбе́й, ті́мже припа́даєм к Тебі́ і с умиле́нієм поє́м:","Ра́дуйся, всіх скорб'я́щих Ра́досте;","ра́дуйся, взиска́ніє поги́бших.","Ра́дуйся, оби́димих Засту́пнице;","ра́дуйся, а́лчущих пита́тельнице.","Ра́дуйся, стра́нних Утіше́ніє;","ра́дуйся обурева́ємих Приста́нище.","Ра́дуйся, больни́х посіще́ніє;","ра́дуйся, немощни́х Покро́ве і Помо́щнице.","Ра́дуйся, же́зле ста́рости;","ра́дуйся, Ма́ти Бо́га на́шего.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 5","ps":["Засту́пнице ми́ра, возвесели́ всіх прибіга́ющих к Тебі́, Ма́тері висшей Ра́дости, покри́й нас честни́м Твої́м омофо́ром от вся́ких бід, напа́стей, скорбе́й і болі́зней, да поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Моле́ніє крі́пкоє, стіно́ необори́мая, ми́лости істо́чниче, всіх правосла́вних прибі́жище, Богоро́дице Ді́во! Прийми́ от нас а́нгельськоє пі́ніє:","Ра́дуйся, ра́досте і сла́во ві́рующих;","ра́дуйся, всіх святи́х непрело́жноє упова́ніє.","Ра́дуйся, ско́роє в біда́х ізбавле́ніє;","ра́дуйся, гото́воє в ну́ждах утіше́ніє.","Ра́дуйся, Боговмісти́моє жили́ще;","ра́дуйся, бе́здно щедро́т і благости́ні.","Ра́дуйся, одушевле́нний хра́мі;","ра́дуйся, сиро́т і вдови́ць сла́достноє весе́ліє.","Ра́дуйся, неістощи́моє бога́тство;","ра́дуйся, Неві́сто неневі́стная.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 6","ps":["Во вре́м'я живота́ моєго́ не оста́ви мене́, Ма́ти Бо́жия, і коне́ць благи́й получи́ти м'я сподо́би, да взива́ю Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Іскуше́нія вся́каго і страсте́й ізба́ви м'я, Всенепоро́чная! Уще́дри, спаси́, возвесели́ м'я і от лю́тих враго́в ізба́ви і защити́, да ви́ну взива́ю Тебі́:","Ра́дуйся, крі́пкоє і непоколеби́моє упова́ніє на́ше;","ра́дуйся, всіх Цари́це і Влади́чице.","Ра́дуйся, всея́ вселе́нния вели́коє сокро́вище;","ра́дуйся, всіх ві́рних утвержде́ніє.","Ра́дуйся, засту́пнице усе́рдная ро́да христия́нськаго;","ра́дуйся, ро́ждшая всіх святи́х святі́йшеє Сло́во.","Ра́дуйся, небе́сний престо́ле;","ра́дуйся, істо́чниче неізсяка́ємий Води́ живи́я.","Ра́дуйся, огражде́ніє і свяще́нноє прибі́жище на Тя наді́ющихся;","ра́дуйся, предста́тельство христия́н непости́дноє.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 7","ps":["В час кончи́ни моєя́, Всеблага́я, предста́ни мні і убо́гую мою́ ду́шу во ісхо́ді от окая́ннаго ті́ла моєго́ обра́дуй, да воспою́ Побіди́телю сме́рти і а́да: Аллилу́я."]},{"h":"Ікос 7","ps":["Лиця́ Твоєго́ ра́достнаго не отврати́ от мене́, Богороди́тельнице! Усли́ши мольбу́ мою́, і вопль мой к Тебі́ да при́йдеть, Ді́во Пресвята́я! Во́ньже а́ще день призову́ Тя, ско́ро усли́ши м'я, да взива́ю Тебі́ си́це:","Ра́дуйся, торже́ственноє пі́ніє А́нгелов;","ра́дуйся, Апо́столов похвало́.","Ра́дуйся, пресви́теров красото́;","ра́дуйся страда́льцев вінча́ніє.","Ра́дуйся, сто́лпе ді́вства;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, по́стников воздержа́ніє;","ра́дуйся, живота́ нетлі́ннаго весе́ліє.","Ра́дуйся, мона́хов умиле́ніє;","ра́дуйся, святи́телей удобре́ніє.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 8","ps":["Со сві́тлой свіще́ю благоволи́ла, Пречи́стая, ізи́ти во срі́теніє Жениха́ душ на́ших, да́руй і мні бо́дренним се́рдцем і тре́звенною ми́слію настоя́щаго житія́ нощ прейти́ і в ра́достний черто́г сла́ви Єго́ вни́ти і пі́ти Судії́ всіх Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Єди́на непоро́чная і чи́стая Ді́во, небе́снаго весе́лія улучи́ти со всі́ми святи́ми сподо́би всіх нас і сро́дников на́ших, дру́ги і зна́ємия, да упоко́їть їх Госпо́дь всеси́льними Твої́ми моли́твами, Пречи́стая, в мі́сті сві́тлі, іді́же ність болі́зні, ні печа́лі, ні воздиха́нія, но жизнь безконе́чная. Да прости́ть їм Госпо́дь вся́коє согріше́ніє, соді́янноє ї́ми от ю́ности до сме́ртнаго часа́ їх, да взива́ють і они́ с на́ми:","Ра́дуйся, во успе́нії Своє́м нас не оставившая;","ра́дуйся, Ма́ти Жи́зні.","Ра́дуйся, ізбавля́ющая от сме́рти душі́ на́ша;","ра́дуйся, в моли́твах неусипа́ющая Богоро́дице.","Ра́дуйся, ра́йськія ра́дости нас приобщающая;","ра́дуйся, Бо́га пло́тію ро́ждшая.","Ра́дуйся, от ро́ва поги́белі нас спаса́ющая;","ра́дуйся, ра́достноє упокоє́ніє всіх во ві́рі і наде́жде сконча́вшихся.","Ра́дуйся, Наде́ждо ненаде́жних;","ра́дуйся, милосе́рдія две́рі нам отверза́ющая.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 9","ps":["Ізба́ви, Богороди́тельнице, нас, грі́шних рабо́в Твої́х, геє́нни о́гненния, тьми несвіти́мия, муки́ а́дськия і сподо́би жи́зні нестарі́ющіяся, да поє́м всегда́ Сладча́йшему Ісу́су: Аллилу́я."]},{"h":"Ікос 9","ps":["Пречи́стая Ді́во, Твої́м хода́тайством пред престо́лом Всеви́шняго освяти́ мою́ ду́шу і ті́ло, ум і се́рдце, всего́ м'я обнови́, украси́, уцілому́дри, просла́ви, спаси́, просвіти́, і благослови́ Свої́м небе́сним і земни́м благослове́нієм, да взива́ю Ті:","Ра́дуйся, неневі́стная Ма́ти і неіскусобра́чная; ра́дуйся, я́ко Тобо́ю Си́на Бо́жия позна́хом.","Ра́дуйся, неруши́мая стіно́; ра́дуйся, всесоверше́нноє спасе́ніє душ на́ших.","Ра́дуйся, Влади́чице і Ма́ти Ізба́вителя от ві́чния сме́рти; ра́дуйся, святи́х святі́йшая а́нгелов.","Ра́дуйся, я́ко воі́стину із Тебе́ Госпо́дь воцари́ся і в лі́поту облече́ся; ра́дуйся, гріхо́вную от'ємлющая скве́рну.","Ра́дуйся, у́тра весенняго світлі́йшая; ра́дуйся, свирі́пую бу́рю душі́ моєя́ укроща́ющая.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 10","ps":["Утверди́, Богоро́дице Ді́во, в Правосла́вії всіх благові́рних украї́нських люде́й, покри́й їх Твої́м честни́м омофо́ром от вся́каго зла, да пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Боголюби́вая Ді́во Марі́є, Госпоже́ Богоро́дице безневі́стная, ві́рних спасе́ніє і наде́ждо! Ти бо і́маши мно́гоє дерзнове́ніє к Небе́сному Царю́, воплоти́вшемуся із Тебе́, ізба́ви нас от скорбе́й лю́тих і печа́лі го́ркия. Утіше́нія і ра́дости про́сим у Тебе́, Ра́досте на́ша, найпа́че же спасе́нія ві́чнаго тре́буєм от Тебе́, умиле́нно взива́юще:","Ра́дуйся, Хліб жи́зні, Боже́ственнаго А́гнця, ро́ждшая;","ра́дуйся, лозо́ виногра́дная, возрасти́вшая нам Плод живота́.","Ра́дуйся, вино́м небе́сния ра́дости нас напояющая;","ра́дуйся, святи́х, небе́сних, стра́шних, Боже́ственних і безсме́ртних, і животворя́щих Христо́вих Та́їн ві́рних сподобля́ющая.","Ра́дуйся, Сві́та невече́рняго Таї́ннице неізрече́нная;","ра́дуйся, сві́те помраче́нния моєя́ душі́.","Ра́дуйся, покро́ве і Наде́ждо моя́;","ра́дуйся, прибі́жище моє́.","Ра́дуйся, утіше́ніє моє́;","ра́дуйся, ра́дованіє моє́.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 11","ps":["Двер небе́сную ві́рним отверза́ющая, покая́нія две́рі отве́рзи мі, Богоро́дице, да поми́луєть м'я Пра́веднійший Судія́, да не яви́ть мої́х та́йних прегріше́ній і не посрами́ть мене́ пред А́нгели Свої́ми, да пою́ Єму́ во ві́ки: Аллилу́я."]},{"h":"Ікос 11","ps":["Очи́сти м'я, Пречи́стая, от вся́ких скверн пло́ті і ду́ха, отжени́ от мене́ уни́ніє, просвіти́ моя́ ми́слі серде́чния, пода́ждь мі па́м'ять сме́ртную, сохрани́ се́рдце моє́ от по́хотей лука́вих і усли́ши м'я вопію́щаго:","Ра́дуйся, Цари́це моя́ Преблага́я;","ра́дуйся, Засту́пнице моя́ Преблагослове́нная.","Ра́дуйся, тружда́ющихся помо́щнице;","ра́дуйся, оби́димих Засту́пнице.","Ра́дуйся, отра́до і утіше́ніє пла́чущих;","ра́дуйся, утіше́ніє в сме́рті моє́й.","Ра́дуйся, весе́ліє душі́ моєя́;","ра́дуйся, красото́ Це́ркві.","Ра́дуйся, просвіще́ніє ума́ моєго́;","ра́дуйся, всіх христия́н утіше́ніє.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 12","ps":["Во сві́тлостіх святи́х Твої́х ка́ко вни́ду недосто́йний аз, Бо́же, Бо́же мой! А́ще бо дерзну́ совни́ти в черто́г, оде́жда м'я облича́єть, я́ко ність бра́чна. Просвіти́ одія́ніє душі́ моєя́, Жизнода́вче, моли́твами Богоро́диці, да пою́ Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["О небе́сний, о любе́зний, о сладча́йший Твой глас, веселя́щий се́рдця на́ша! С на́ми бо нело́жно обіща́лася єси́ би́ти до сконча́нія ві́ка, Ді́во Богоро́дице! Твої́ми бо моли́твами сліпі́ї ви́дять, глухи́я сли́шать, хромі́ї хо́дять, прокаже́ннії очища́ються, а́лчущії пита́ються, назі́ї одіва́ються, вдови́ці утіша́ються, сироти́ ра́дуються, ни́щії веселя́ться, грі́шници спаса́ються, убо́зії лику́ють, воспіва́юще:","Ра́дуйся, одушевле́нний Бо́жий Киво́те;","ра́дуйся, Боголюби́вая Цари́це і Влади́чице.","Ра́дуйся, от гла́да і губи́тельства, тру́са і пото́па нас спаса́ющая;","ра́дуйся, от огня́, меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні нас защища́ющая.","Ра́дуйся, бурния во́лни жите́йськаго мо́ря укроща́ющая;","ра́дуйся, вся́кую сле́зу с оче́й на́ших отирающая.","Ра́дуйся, я́ко воі́стину любо́вію матери́нською нас возлюби́вшая;","ра́дуйся, пода́тельнице Боже́ственния бла́гости.","Ра́дуйся, во чре́ві Своє́м Ра́дость ві́чную носи́вшая;","ра́дуйся, я́ко ти́хоє приста́нище душа́м на́шим гото́виши.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, Пречи́стая Госпоже́ Ді́во Богоро́дице! Прийми́ сіє́ ма́лоє моле́ніє на́ше, Засту́пнице крі́пкая су́щих в ско́рбіх і печа́ліх; умоля́єм Тя честни́м і животворя́щим кресто́м Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́: пода́ждь нам дух сокруше́нний, се́рдце смире́нноє, сле́зи умиле́нія, мно́гих согріше́ній на́ших проще́ніє і ра́дость неув'яда́ємую, да поє́м в го́рнем Ієрусали́ме Спаси́телю Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Та́йну от ві́ка открива́я Тебі́, Пренепоро́чная Ді́во, Гавриї́л, безпло́тних архістрати́г, со стра́хом вопія́ше: Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю! Ми же грі́шнії нечи́стими устна́ми дерза́єм вопи́ти Тебі́ си́це:","Ра́дуйся, благослове́нная в жена́х;","ра́дуйся, Богоневі́сто.","Ра́дуйся, виногра́дная лозо́;","ра́дуйся, в рождестві́ і по рождестві́ Ді́ва.","Ра́дуйся, цві́те неув'яда́ємий;","ра́дуйся, чистоти́ сокро́вище.","Ра́дуйся, кади́ло благово́нноє;","ра́дуйся, ми́ро многоце́нноє.","Ра́дуйся, одушевле́нная трапе́зо;","ра́дуйся, Сві́та невече́рняго жили́ще.","Ра́дуйся, всего́ ми́ра очище́ніє;","ра́дуйся душ на́ших освяще́ніє.","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді не умолчи́м нікогда́ глаго́лати ми недосто́йнії, Всесвята́я Ді́во, ро́ждшая на спасе́ніє на́ше Ра́дость ві́чную, вся́коє уни́ніє і печа́ль отжени́ от нас, да зове́м Ті:","Ра́дуйся, Ра́досте на́ша, во об'ятіїх Свої́х Ра́дость всего́ ми́ра носи́вшая."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во, всеблага́го Си́на Ма́ти всеблага́я, ца́рствующаго гра́да і свята́го хра́ма сего́ покрови́тельнице, всім су́щим во грісі́х, ско́рбіх, біда́х і болі́зніх ві́рная предста́тельнице і засту́пнице! Не пре́зри моле́нія нас, недосто́йних рабо́в Твої́х, і умоли́ Си́на Твоєго́ і Бо́га на́шего, да всім нам, с ві́рою і умиле́нієм поклоняющимся пред чудотво́рним о́бразом Твої́м, да́руєть по коєго́ждо потре́бі ра́дость: су́щим в ско́рбіх і печа́ліх утіше́ніє, бедствующим милосе́рдіє, су́щим в многонедужії неча́ємоє ісціле́ніє і укріпле́ніє. О Госпожі́ Пресвята́я, умилосе́рдися ко всім чту́щим всечестно́є і́м'я Твоє́ і всім яви́ всемо́щний покро́в Твой і заступле́ніє: вся́кому ді́лу, Си́ну Твоєму́ уго́дному споспі́шествуй; вся́коє ді́ло зло́є разруши́; в недоумі́нії і тру́дних і опа́сних обстоя́ніїх обріта́ющимся незри́мую по́мощ і вразумле́ніє с небесе́ ниспосли́. Младе́нці воспита́й, ю́ния уцілому́дри, отве́рзи їм ум к прия́тію вся́каго поле́знаго уче́нія. От дома́шнія бра́ні і от враго́во ви́димих і неви́димих защити́ і сохрани́. Супру́жества в любві́ і єдиноми́слії сохрани́ і от вражди́ єдинокро́вних ми́ром і любо́вію огради́. І всім нам даждь друг ко дру́гу любо́в, мир і благоче́стіє, і здра́віє с долгоде́нствієм. Преставившіяся во ві́рі і покая́нії от житія́ сего́ со а́нгели і всі́ми святи́ми жи́ти сотвори́, да всі на Небесі́ і на землі́ ві́дять Тя я́ко тве́рдую і непости́дную Предста́тельницю на́шу, ро́да христия́нськаго, і, ві́дуще, сла́в'ять Тя і Тобо́ю Си́на Твоєго́, со Безнача́льним Єго́ Отце́м і Єдиносу́щним Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От святи́я іко́ни Твоєя́ / ра́дости неізрече́нния преіспо́лнила єси́ се́рдце благочести́вия жени́. / О Пречи́стая Влади́чице ми́ра, / Всемо́щная Цари́ця ра́досте, Присноді́во тва́рі, / єгда́ возврати́ла о́ной і му́жа, і си́на, і достоя́ніє єя́, / та́кожде і всім нам милосе́рдствуєши, / да́руй ісполне́ніє благи́х жела́ній, / істоча́я приснотеку́щий істо́чник ра́дости моля́щимся Тебі́ / і вседу́шно вопію́щим: / Ра́дость всему́ ми́ру роди́вшая, // ра́дости іспо́лни неоскудева́ющия чту́щих Тя."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, хода́тайство ко Творцю́ непрело́жноє, не пре́зри грі́шних моле́ній гла́си, но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті; ускори́ на моли́тву і потщи́ся на умоле́ніє, предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «У скорботах і печалях Утіха»","e":"Akathist to the Theotokos before her icon “Consolation in Sorrows and Afflictions”","secs":[{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді Влади́чиці на́шей Богоро́диці, дарова́вшей нам пречу́дную іко́ну Свою́ «В ско́рбіх і печа́ліх Утіше́ніє», благода́рственноє прино́сим пі́ніє. Ти же, Пренепоро́чная, прийми́ моли́тви на́ша і от вся́ких бід заступи́ раби́ Твоя́, с ві́рою і любо́вію вопію́щия Ті:","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Ікос 1","ps":["А́нгел мно́жество і вся Небе́сная Во́їнства сла́в'ять Тя непреста́нно на небесі́, Влади́чице, і ми, земноро́днії, іспо́лненнії ра́дости духо́вния, притека́юще к цільбоно́сній іко́ні Твоє́й, із глубини́ се́рдця прино́сим Ті глаго́ли сія́:","Ра́дуйся, Бо́жиє ко грі́шним благоволе́ніє;","ра́дуйся, ка́ющихся пред Го́сподом Бо́гом крі́пкоє заступле́ніє.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, гріхо́вную от'є́млющая скве́рну;","ра́дуйся, ба́не, омива́ющая со́вість.","Ра́дуйся, ро́ждшая Ізба́вителя, беззако́нія на́ша ту́не очища́ющаго;","ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє.","Ра́дуйся, мо́сте, воі́стину преводя́й нас от сме́рти к животу́;","ра́дуйся, мир от пото́па гріхо́внаго спа́сшая.","Ра́дуйся, лі́ствице небе́сная, Є́юже Госпо́дь к нам сни́де;","ра́дуйся, вина́ всіх обоже́нія.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 2","ps":["Ви́дяще Тя на іко́ні Твоє́й святі́й, Богома́ти Пречи́стая, Богомладе́нця Христа́ на рука́х Твої́х держа́щую і ли́ками святи́х окружа́ємую, умиля́ємся душа́ми на́шими і благогові́йно с любо́вію покланя́ємся пречи́стаго ли́ка Твоєго́ ізображе́нію, зову́ще Си́ну Твоєму́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний открива́я, Богоро́дице Ді́во, благоволи́ла єси́ мно́гими чудеси́ просла́вити іко́ну Твою́, в земно́м жре́бії Твоє́м, Святі́й Горі́ Афо́нстій, да всі ві́дуще таково́є Твоє́ о ней благоволе́ніє, пі́сненно Тебі́ зову́ть:","Ра́дуйся, обурева́ємих ти́хоє приста́нище;","ра́дуйся, сумня́щихся ізві́стноє утвержде́ніє.","Ра́дуйся, єди́на Ма́ти милосе́рдія;","ра́дуйся, ско́рая Помо́щнице су́щим в біда́х і напа́стіх.","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая;","ра́дуйся, печа́лію на́ша не́мощі душе́вния врачу́ющая.","Ра́дуйся, су́єтния ра́дости ми́ра сего́ презира́ти нас науча́ющая;","ра́дуйся, от ми́ра к преми́рним ум наш возводя́щая.","Ра́дуйся, от любве́ земни́я к небе́сній Бо́жієй любві́ нас привлека́ющая;","ра́дуйся, в са́мих страда́ніях на́ших утіше́ніє і благода́тную жизнь нам подаю́щая.","Ра́дуйся, обітова́ніє благ ві́чних;","ра́дуйся, Хода́тайце ві́чния ра́дости.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 3","ps":["Си́лу Боже́ственния благода́ті да́руєши, о Богома́ти, всім с ві́рою і любо́вію прибега́ющим ко всечестно́му покро́ву Твоєму́; і нас, неду́гующих ті́лом і душе́ю, Блага́я Влади́чице, сви́ше укріпи́ і посіще́нія Твоєго́ сподо́би, да спаса́ємії Тобо́ю, непреста́нно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я любо́во ве́лію к лю́дем, іскупле́нним Кро́вію Си́на Твоєго́ і Бо́га, всім с ві́рою і упова́нієм прибега́ющим к Тебі́ ми́лостивно подає́ши ру́ку по́мощі, Влади́чице, да всі єди́ним се́рдцем і єди́ними усти́ прино́сять Ті пі́ніє сицево́є:","Ра́дуйся, ми́лости сокро́вище многоці́нноє;","ра́дуйся, отча́янних єди́на Наде́ждо.","Ра́дуйся, ті́ла моєго́ врачева́ніє;","ра́дуйся, душі́ моєя́ спасе́ніє.","Ра́дуйся, тве́рдая крі́посте немощни́х;","ра́дуйся, ізнемога́ющих Засту́пнице і укріпле́ніє.","Ра́дуйся, гнів Бо́жий Твої́м моле́нієм ско́ро утоля́ющая;","ра́дуйся, стра́сті на́ша си́лою моли́тв Твої́х укроща́ющая.","Ра́дуйся, сліпи́х зрі́ніє, глухи́х сли́шаніє;","ра́дуйся, хроми́х хожде́ніє, німи́х глаго́ланіє.","Ра́дуйся, боля́щих благонаде́жноє посіще́ніє;","ра́дуйся, я́ко Тобо́ю по мі́рі ві́ри подаю́ться благода́тная ісціле́нія всім немощству́ющим.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 4","ps":["Бу́рею мно́гих бід одержи́мим нам помога́єши, Небе́сная Цари́це, с ві́рою прибега́ющим к Тебі́ і покланя́ющимся цільбоно́сному о́бразу Твоєму́, єго́же ми́лостиво яви́ла єси́ нам во утіше́ніє, да прославля́я ми́лость Твою́, нам низпосла́нную, рожде́нному от Тебе́ Спаси́телю ми́ра зове́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше бра́тія скита́ Андре́євськаго словеса́ отця́ своєго́ духо́внаго: «Да бу́деть сія́ іко́на вам отра́дою і утіше́нієм в ско́рбіх і печа́ліх», возра́довашеся зіло́ о Твоє́м заступле́нії, Пресвята́я Ді́во, і всю наде́жду на Тя возложи́вше, воспі́ша Ті та́ко:","Ра́дуйся, ра́дость ми́ру Христа́ Спаси́теля ро́ждшая;","ра́дуйся, мир от скорбе́й ізбавля́ющая.","Ра́дуйся, хуле́нія і клевети́ на Си́на Твоєго́ терпе́вшая;","ра́дуйся, страда́нієм Єго́ спострада́вшая.","Ра́дуйся, ско́рбних ма́терей утіше́ніє;","ра́дуйся, чад їх благода́тноє охране́ніє.","Ра́дуйся, в біда́х ско́роє нам заступле́ніє;","ра́дуйся, заблу́ждших ісправле́ніє.","Ра́дуйся, младе́нцев пита́ніє;","ра́дуйся, ю́них наставле́ніє.","Ра́дуйся, Ма́ти сиро́тствующих;","ра́дуйся, вдов заступле́ніє.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся іко́на Твоя́, Ді́во Богоро́дице, сія́нієм мно́гих чуде́с духо́вно просвіща́я і неоску́дно істоча́я благода́тная ісціле́нія всім ві́рним, усе́рдно к ней притека́ющим і смире́нно вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще то́ки чуде́с, от святи́я іко́ни Твоєя́ істоча́ємия, Всеблага́я, всі лю́діє землі́ В'я́тськия стека́хуся к ней на поклоне́ніє і на Тя все упова́ніє своє́ в ско́рбіх і печа́ліх возлага́юще, воспі́ша Ті си́це:","Ра́дуйся, Ма́ти ро́да христия́нськаго;","ра́дуйся, усинови́вшая нас при Кресті́ Си́на Твоєго́.","Ра́дуйся, Бо́га с челові́ки соєдини́вшая;","ра́дуйся, ві́рних Го́сподеві сочета́вшая.","Ра́дуйся, А́гнице, ро́ждшая А́гнця, взе́мшаго гріхи́ ми́ра;","ра́дуйся, ча́ше, че́рплющая нам ра́дость от Істо́чника безсме́ртія.","Ра́дуйся, Спору́чнице спасе́нія грі́шних;","ра́дуйся, Взиска́ніє поги́бших.","Ра́дуйся, неча́янная грі́шних Ра́досте;","ра́дуйся, па́дших воста́ніє.","Ра́дуйся, Ціли́тельнице всіх не́мощей;","ра́дуйся, утоле́ніє вся́кия печа́лі.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 6","ps":["Пропові́дують ми́лості Твоя́, Богоро́дице, всі конці́ вселе́нния, от святи́я іко́ни Твоєя́ «В ско́рбіх і печа́ліх Утіше́ніє» бива́ємия: боля́щим бо здра́віє, сліпи́м прозрі́ніє, скорб'я́щим утіше́ніє подає́ши і всім на вся́ком мі́сті і на вся́кий час благода́тную по́мощ явля́єши, вопію́щим о Тебі́ Всеми́лостивому Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ мно́гими луча́ми чуде́с іко́на Твоя́, о Богома́ти, і си́ми не то́кмо Го́ру Афо́нськую, но і мно́жайшая міста́ озари́ла єси́, да научі́мся зва́ти Тебі́:","Ра́дуйся, принося́щая к Си́ну Твоєму́ і Бо́гу моле́нія ві́рних;","ра́дуйся, і Сама́ у Престо́ла Си́на Твоєго́ непреста́нно моля́щаяся о нас.","Ра́дуйся, Предста́тельнице к Бо́гу, мир от бід спаса́ющая;","ра́дуйся, Засту́пнице ро́да христия́нськаго, от Бо́га нам дарова́нная.","Ра́дуйся, дре́во благосінноли́ственноє, і́мже покрива́ються мно́зі;","ра́дуйся, дре́во світлоплодови́тоє, і́мже пита́ються ві́рнії.","Ра́дуйся, покро́ве ми́ру, ши́рший о́блака;","ра́дуйся, земле́ обітова́нія, із нея́же тече́ть мед і млеко́.","Ра́дуйся, сві́тлий о́блаче, ві́рния непреста́нно освеща́ющий;","ра́дуйся, сто́лпе о́гненний, наставля́яй ізбра́нния к небе́сному наслі́дію.","Ра́дуйся, ни́во, растя́щая оби́ліє щедро́т;","ра́дуйся, Пода́тельнице вся́кия бла́гости.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 7","ps":["Хотя́щи яви́ти то́ки чуде́с от іко́ни Своєя́ «В ско́рбіх і печа́ліх Утіше́ніє», усли́шала єси́, Влади́чице, моли́тву боля́щаго раба́ Твоєго́ Влади́мира і от немоти́ ісціле́ніє єму́ дарова́ла єси́, да здрав сий душе́ю і ті́лом, пропові́дуєть всім ми́лості Твоя́, ра́ди тоя́ іко́ни явле́нния. Ті́мже і ми прославля́юще Бо́га, благоді́ющаго чрез святи́й о́браз Твой, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє ми́лости Твоєя́ яви́ла єси́, Цари́це Небе́сная, в чуде́снім прославле́нії святи́я іко́ни Твоєя́, к не́йже с ві́рою і любо́вію прибега́ющим і по́мощі от Тебе́ прося́щим вся́кий неду́г і вся́кую я́зву душе́вную і тіле́сную врачу́єши. Сего́ ра́ди вопіє́м Ті:","Ра́дуйся, купі́ль, в не́йже вся ско́рбі на́ша погружа́ються;","ра́дуйся, ча́ше, Є́юже ра́дость і спасе́ніє восприє́млем.","Ра́дуйся, ка́меню, напої́вший жа́ждущия жи́зні;","ра́дуйся, дре́во, услажда́ющеє сла́ния во́ди жите́йськаго мо́ря.","Ра́дуйся, животво́рния води́ неістощи́мий істо́чниче;","ра́дуйся, ба́не, омива́ющая гріхо́вную скве́рну.","Ра́дуйся, скорбе́й на́ших услажде́ніє;","ра́дуйся, печа́лей на́ших утоле́ніє.","Ра́дуйся, болі́зней на́ших врачева́ніє;","ра́дуйся, бід ізбавле́ніє.","Ра́дуйся, де́монов попра́ніє;","ра́дуйся, враго́в посрамле́ніє.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є многоско́рбноє і многом'яте́жноє услажда́єши нам ма́терним твої́м о нас попече́нієм, Богоро́дице: Ти бо, я́ко блага́я Одиги́трія, наставля́єши нас к ти́хому і благооти́шному приста́нищу і мо́лиши Си́на Твоєго́ о проще́нії прегріше́ній на́ших, да непреста́нно вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім ві́рним умили́тельно єсть взира́ти на святу́ю іко́ну Твою́, Всеми́лостивая Влади́чице, Ти бо єси́ всіх скорб'я́щих Уті́шительниця і бі́дствующих Помо́щниця. К Тебі́ у́бо прибіга́єм, Богома́ти, пред пречестно́ю іко́ною Твоє́ю припа́дающе: іспо́лни ра́дости і весе́лія ско́рбная сердця́ на́ша, да, получи́вше отра́ду і утіше́ніє, вопіє́м Ті:","Ра́дуйся, Путеводи́тельнице, к Небе́сному оте́честву нас руководя́щая;","ра́дуйся, Цари́це Не́ба і землі́, врата́ ра́йськая нам отверза́ющая.","Ра́дуйся, Ми́лостивая, нас ми́лующая;","ра́дуйся, Домострої́тельнице, житіє́ на́ше до́брі устроя́ющая.","Ра́дуйся, руно́ ороше́нноє, є́же Гедео́н предви́ді;","ра́дуйся, блаже́нноє чре́во, невмісти́маго всі́ми Бо́га вмісти́вшеє.","Ра́дуйся, Неопали́мая Купино́;","ра́дуйся, Неруши́мая Стіно́.","Ра́дуйся, Живоно́сний Істо́чниче;","ра́дуйся, Цві́те Неув'яда́ємий.","Ра́дуйся, ум'ягче́ніє серде́ць злих;","ра́дуйся, умиле́ніє благи́х.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 9","ps":["Вся́кия утоля́єши болі́зні і ско́рби, во обстоя́нії су́щим ру́ку по́мощі простира́ющи, о Всеблага́я: призрі́ла бо єси́ на раба́ Твоєго́ Тимофе́я і ісціле́ніє єму́ дарова́ла єси́. Услади́ у́бо і на́ша ско́рби і печа́лі, ско́рая Помо́щнице, і ісціле́ніє пода́ждь неду́гующим душа́м і тілесе́м на́шим, да вопіє́м немо́лчно: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоуміва́ють, ки́їми словеси́ досто́йно восхвали́ти вся чудеса́ Твоя́, Богоро́дице, от святи́я іко́ни Твоєя́ бива́ємия. Ми же, Твоя́ неісче́тная благодія́нія ви́дяще, при́сно Тя ублажа́єм і хвале́бно Тебі́ вопіє́м:","Ра́дуйся, обра́довавшая наді́янієм на Тя всіх христия́н;","ра́дуйся, Ра́досте і умире́ніє ми́ру.","Ра́дуйся, Пода́тельнице Боже́ственния бла́гости;","ра́дуйся, Наде́ждо благ ві́чних.","Ра́дуйся, кораблю́ хотя́щих спасти́ся;","ра́дуйся, приста́нище жите́йських пла́ваній.","Ра́дуйся, ві́рная Храни́тельнице упова́ющих на Тя по Бо́зі;","ра́дуйся, оде́ждо наги́х дерзнове́нія.","Ра́дуйся, Засту́пнице всіх і утвержде́ніє;","ра́дуйся, всіх ві́рних огражде́ніє і свяще́нноє прибі́жище.","Ра́дуйся, по́моще ві́рно моля́щихся Тебі́;","ра́дуйся, сві́тлоє благода́ті позна́ніє.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 10","ps":["Спаси́тельноє прибі́жище в ско́рбіх і біда́х явля́єшися всему́ ро́ду челові́чеському, Ма́ти Бо́жия: Тя бо дарова́ Человіколю́бець Госпо́дь погиба́ющим в по́мощ, покро́в і утіше́ніє. Ми же, ві́чния му́ки Твої́м хода́тайством ізба́витися упова́юще, ві́рно вопіє́м Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая і істо́чник чуде́с яви́ся свята́я іко́на Твоя́, Влади́чице, всім к Твоєму́ покро́ву прибега́ющим. Ті́мже і ми, припа́дающе пред о́бразом Твої́м, мо́лим Тя: защити́ і сохрани́ нас невреди́ми от всіх напа́стей і нестроє́ній, с любо́вію взива́ющих Ті із глубини́ душі́:","Ра́дуйся, сто́лпе ді́вства;","ра́дуйся, чистоти́ і цілому́дрія сосу́де ізбра́нний.","Ра́дуйся, во́їнствующим на плоть цілому́дрієм ізря́дноє вінча́ніє;","ра́дуйся, во і́ночестві благоскорб'я́щим Пода́тельнице ві́чнаго ра́дованія.","Ра́дуйся, пла́мень страсте́й ізміня́ющая;","ра́дуйся, мрак іскуше́ній прогоня́ющая.","Ра́дуйся, Наста́внице цілому́дрія;","ра́дуйся, чистоти́ огражде́ніє.","Ра́дуйся, ісправле́ніє челові́ков;","ра́дуйся, Є́юже от паде́нія на́шего воста́хом.","Ра́дуйся, тве́рдоє ві́ри утвержде́ніє;","ра́дуйся, прия́тноє моли́тви кади́ло.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє сіє́ на́ше не пре́зри, Пресвята́я Ді́во, єго́же всеумиле́нно прино́сим Ті, раби́ Твої́, я́ко всеси́льній Засту́пнице ро́да на́шего, но помози́ нам, Всеблага́я, покая́нієм очи́ститися от скве́рни гріхо́вния і преуспі́ти в чи́стім і богоуго́днім житії́, да воспомина́я неісче́тная чудотворе́нія Твоя́, вопіє́м Пода́телю всіх благ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с пречестна́я іко́на Твоя́, Влади́чице, немерца́ємо сія́єть і весь мир благода́тно озаря́єть, мрак гріхо́вний і уни́ніє разгоня́я. Не лиши́, о Всеблага́я, Твоєго́ заступле́нія і нас, в жите́йськом мо́ре треволне́ніями обурева́ємих, оба́че от се́рдця принося́щих Ті благохвале́нія сія́:","Ра́дуйся, си́льним Твої́м заступле́нієм от всіх бід нас ізбавля́ющая;","ра́дуйся, от тру́са і пото́па нас защища́ющая.","Ра́дуйся, от гла́да душе́внаго і тіле́снаго нас снабдіва́ющая;","ра́дуйся, огнь росо́ю моли́тв Твої́х угаша́ющая.","Ра́дуйся, от сме́ртнаго губи́тельства нас спаса́ющая;","ра́дуйся, в брані́х крі́пкая Помо́щнице.","Ра́дуйся, от наше́ствія іноплеме́нних нас огражда́ющая;","ра́дуйся, от междоусо́бния бра́ні охраня́ющая.","Ра́дуйся, пла́вающих ле́гкоє по вода́м прехожде́ніє;","ра́дуйся, путеше́ствующих до́брая Води́тельнице.","Ра́дуйся, плі́нних свобожде́ніє;","ра́дуйся, от належа́щаго пра́веднаго преще́нія Бо́жия ско́роє ізбавле́ніє.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную і ми́лость іспроси́ нам, Всеми́лостивая Влади́чице, у Си́на Твоєго́ і Бо́га, да, то́ю укріпля́ємі і направля́ємі, по путі́ сем многоско́рбнім неукло́нно ше́ствовати возмо́жем. Ти же, о Богома́ти, от вся́каго зла сохрани́ нас, под осіне́ніє іко́ни Твоєя́ святи́я прибіга́ющих і со умиле́нієм о Тебі́ вопію́щих: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ ми́лості і чудеса́, Богороди́тельнице, би́вшая в дре́внія і настоя́щая времена́, хва́лим, сла́вим і велича́єм Тя, честні́йшую воі́стину Херуви́м і сла́внійшую без сравне́нія Серафи́м, і, припа́дая к пречестно́му о́бразу Твоєму́, уми́льно сей лобиза́єм, с тре́петом і любо́вію воспіва́я Ті си́це:","Ра́дуйся, непости́дноє на́ше упова́ніє в животі́ і по преставле́нії на́шем;","ра́дуйся, упова́ющим на Тя ми́рен коне́ць житія́ сего́ подаю́щая.","Ра́дуйся, в день су́дний на́ша Наде́ждо і Защище́ніє;","ра́дуйся, Судії́ Пра́веднаго умоле́ніє.","Ра́дуйся, геє́нни ві́чния ізбавле́ніє;","ра́дуйся, Наде́ждо ві́чнаго спасе́нія.","Ра́дуйся, ключу́ Ца́рствія Христо́ва;","ра́дуйся, две́ре ра́йськая.","Ра́дуйся, мо́сте, к небесе́м преводя́й;","ра́дуйся, всіх ка́ющихся грі́шников прибі́жище і блага́я Засту́пнице.","Ра́дуйся, А́нгелов ра́досте;","ра́дуйся, всіх пра́ведних сла́во і утіше́ніє.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Сладча́йшаго Го́спода на́шего Ісу́са Христа́! Усли́ши глас скорб'я́щих раб Твої́х і прийми́ сіє́ ма́лоє моле́ніє на́ше, от лю́б'ящих серде́ць Тебі́ приноси́моє: ізба́ви нас от вся́ких бід, скорбе́й і напа́стей, неду́ги на́ша ісціли́, вся́ку зло́бу і вражду́ отжени́ от нас і прича́стниками жи́зні ві́чния соді́лай о Тебі́ благода́рно зову́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел мно́жество і вся Небе́сная Во́їнства сла́в'ять Тя непреста́нно на небесі́, Влади́чице, і ми, земноро́днії, іспо́лненнії ра́дости духо́вния, притека́юще к цільбоно́сній іко́ні Твоє́й, із глубини́ се́рдця прино́сим Ті глаго́ли сія́:","Ра́дуйся, Бо́жиє ко грі́шним благоволе́ніє;","ра́дуйся, ка́ющихся пред Го́сподом Бо́гом крі́пкоє заступле́ніє.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, гріхо́вную от'є́млющая скве́рну;","ра́дуйся, ба́не, омива́ющая со́вість.","Ра́дуйся, ро́ждшая Ізба́вителя, беззако́нія на́ша ту́не очища́ющаго;","ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє.","Ра́дуйся, мо́сте, воі́стину преводя́й нас от сме́рти к животу́;","ра́дуйся, мир от пото́па гріхо́внаго спа́сшая.","Ра́дуйся, лі́ствице небе́сная, Є́юже Госпо́дь к нам сни́де;","ра́дуйся, вина́ всіх обоже́нія.","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді Влади́чиці на́шей Богоро́диці, дарова́вшей нам пречу́дную іко́ну Свою́ «В ско́рбіх і печа́ліх Утіше́ніє», благода́рственноє прино́сим пі́ніє. Ти же, Пренепоро́чная, прийми́ моли́тви на́ша і от вся́ких бід заступи́ раби́ Твоя́, с ві́рою і любо́вію вопію́щия Ті:","Ра́дуйся, Влади́чице, в ско́рбіх і печа́ліх нас при́сно утіша́ющая."]},{"h":"Молитва","ps":["Ко кому́ возопію́, Влади́чице? Ко кому́ прибі́гну в го́ресті моє́й, а́ще не к Тебі́, Цари́це Небе́сная? Кто плач мой і воздиха́ніє моє́ при́йметь, а́ще не Ти, Пренепоро́чная, Наде́ждо христия́н і Прибі́жище нам, грі́шним? Кто па́че Тебі́ в напа́стіх защити́ть? Усли́ши у́бо стена́ніє моє́ і приклони́ у́хо Твоє́ ко мні, Влади́чице Ма́ти Бо́га моєго́, і не пре́зри мене́, тре́бующаго Твоєя́ по́мощі, і не отри́ни мене́, грі́шнаго. Вразуми́ і научи́ м'я, Цари́це Небе́сная; не отступи́ от мене́, раба́ Твоєго́, Влади́чице, за ропта́ніє моє́, но бу́ди мні Ма́ти і Засту́пниця. Вруча́ю себе́ ми́лостивому покро́ву Твоєму́: приведи́ м'я, грі́шнаго, к ти́хой і безм'яте́жній жи́зні, да пла́чуся о грісі́х мої́х. Ко кому́ бо прибі́гну пови́нний аз, а́ще не к Тебі́, упова́нію і прибі́жищу грі́шних, наде́ждою на неізрече́нную ми́лость Твою́ і щедро́ти Твоя́ окриля́єм? О Влади́чице, Цари́це Небе́сная! Ти мні упова́ніє і прибі́жище, покро́в і заступле́ніє і по́мощ. Цари́це моя́ Преблага́я і ско́рая Засту́пнице, покри́й Твої́м хода́тайством моя́ прегріше́нія, защити́ мене́ от враг ви́димих і неви́димих; ум'ягчи́ сердця́ злих челові́к, возстаю́щих на м'я. О Ма́ти Го́спода моєго́ Творця́! Ти єси́ ко́рень ді́вства і неув'яда́ємий цвіт чистоти́. О Богороди́тельнице! Ти пода́ждь мі по́мощ немощству́ющему плотськи́ми страстьми́ і болі́знующему се́рдцем, єди́но бо Твоє́ і с Тобо́ю Твоєго́ Си́на і Бо́га на́шего і́мам заступле́ніє; і Твої́м пречу́дним заступле́нієм да ізба́влюся от вся́кия біди́ і напа́сти, о Пренепоро́чная і Пресла́вная Бо́жия Ма́ти Марі́є. Ті́мже со упова́нієм глаго́лю і вопію́: ра́дуйся, Благода́тная, ра́дуйся, Обра́дованная, ра́дуйся, Преблагослове́нная, Госпо́дь с Тобо́ю! Амі́нь."]},{"h":"Тропар, глас 5","ps":["Утоли́ болі́зні многовоздиха́ющия душі́ моєя́, Утоли́вшая вся́ку сле́зу от лиця́ землі́: Ти бо челові́ком болі́зні отго́ниши і грі́шних ско́рби разруша́єши, Тебі́ бо всі стяжа́хом наде́жду і утвержде́ніє, Пресвята́я Ма́ти Ді́во."]},{"h":"Кондак, глас 6","ps":["Не вві́ри м'я челові́чеському предста́тельству, Пресвята́я Влади́чице, но прийми́ моле́ніє раба́ Твоєго́: скорб бо обдержи́ть м'я, терпі́ти не могу́ де́монськаго стріля́нія, покро́ва не і́мам, ніже́ гді прибі́гну окая́нний, всегда́ побіжда́єм, і утіше́нія не і́мам, ра́зві Тебе́, Влади́чице ми́ра, упова́ніє і предста́тельство ві́рних, не пре́зри моле́ніє моє́, поле́зно сотвори́."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Млекопитательниця»","e":"Akathist to the Theotokos before her icon “The Milk-Giver”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, похва́льная пі́нія прино́сим Ті раби́ Твої́ о явле́нії чудотво́рния іко́ни Твоєя́. Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, соблюди́ і спаси́ от вся́ких бід раби́ Твоя́, с ві́рою і любо́вію вопію́щия Ті:","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л с небесе́ приї́де к Тебі́, Богоро́дице, благовісти́ти непостижи́моє рожде́ніє от Тебе́ Бо́га Сло́ва, і рече́: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю. Ті́мже і ми, смире́ннії, дерза́єм вопи́ти к Тебі́ си́це:","Ра́дуйся, А́нгелов ра́досте;","ра́дуйся, челові́ков спасе́ніє.","Ра́дуйся, па́дшаго ми́ра обновле́ніє;","ра́дуйся, средості́нія вражди́ разруше́ніє.","Ра́дуйся, проро́чеських глаго́л ісполне́ніє;","ра́дуйся, зако́на дре́вняго преміне́ніє.","Ра́дуйся, А́гнця і Па́стиря во чре́ві Твоє́м упа́сшая;","ра́дуйся, Творця́ небесе́ і землі́ пло́тію ро́ждшая.","Ра́дуйся, Пита́теля вселе́нния млекопита́вшая;","ра́дуйся, млеко́м богопозна́нія ві́рних Пита́тельнице.","Ра́дуйся, пови́вшая Повива́ющаго не́бо о́блаки;","ра́дуйся, дла́ньма нося́щая на Херуви́міх Носи́маго.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 2","ps":["Ви́дя Іо́сиф цілому́дренний Чи́стую Ді́ву непра́здну су́щу, восхоті́ тай пусти́ти Ю: уві́дів же во чре́ві іму́щу от Ду́ха Свя́та, удиви́ся непостижи́мій та́йні воплоще́нія, і до конця́ ві́рен храни́тель чистоти́ Єя́ преби́сть; ми же, грі́шнії, сла́в'яще є́же о нас Госпо́днє смотре́ніє, во умиле́нії серде́ць на́ших благогові́йно покланя́ємся Ті, Ді́во Чи́стая, вопію́ще Ро́ждшемуся от Тебе́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський недоразумева́єть пости́гнути ве́ліє та́їнство воплоще́нія от Тебе́, Пречи́стая, Христа́ Бо́га на́шего, і А́нгели небе́снії недоумі́нно див'я́ться, ка́ко нас ра́ди, челові́к, Влади́ки Христа́ с небесе́ на зе́млю низхожде́ніє і от Ді́ви воплоще́ніє бисть, ми же, земноро́днії, Тебі́ благодаре́ніє принося́ще, ра́достно глаго́лем:","Ра́дуйся, пра́ведних Іоаки́ма і А́нни свято́є прозябе́ніє;","ра́дуйся, непло́дния утро́би плод благослове́нний.","Ра́дуйся, в зача́тії Твоє́м чуде́снім просла́вленная;","ра́дуйся, в рожде́нії Твоє́м благода́тію Бо́жиєю осіне́нная.","Ра́дуйся, благові́щеніє Арха́нгелово во смире́нії ра́достно приє́мшая;","ра́дуйся, ді́вство і діторожде́ніє пречу́дно в Себі́ сочета́вшая.","Ра́дуйся, Спаси́теля ми́ра нетлі́нно ро́ждшая;","ра́дуйся, Ді́во Пренепоро́чная і Богоро́дице Пречи́стая.","Ра́дуйся, Бо́га я́ко Отроча́ мла́до па́стирем яви́вшая;","ра́дуйся, Влади́ку, я́ко Пе́рвенця, пра́ведному Симео́ну прине́сшая.","Ра́дуйся, Киво́те Божества́ освяще́нний;","ра́дуйся, Вмісти́лище Боже́ственних открове́ній.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ Тя, Марі́є Богоневі́стная, і Дух Святи́й на́йде на Тя по благові́стію Арха́нгелову. Ті́мже благода́тію Свята́го Ду́ха осіня́єма, зачала́ єси́ во утро́бі Твоє́й і явила́ся єси́ одушевле́нний Киво́т Сло́ва воплоще́ннаго, Єму́же прера́достно вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи любо́в к челові́ком, іскупле́нним Кро́вію Си́на Твоєго́, Преблага́я Влади́чице, прия́ла єси́ от Бо́га благода́ть покрива́ти род христия́нський, єму́же в утіше́ніє іко́ну Твою́ сію́ святу́ю, чуде́с благода́тію просла́вленную, ми́лостивно дарова́ла єси́. Ті́мже благода́рственно вопіє́м Ті:","Ра́дуйся, пресві́тлая звіздо́, явля́ющая ми́рові Со́лнце пра́вди;","ра́дуйся, пресла́вная пала́то, в ню́же всели́ся Христо́с.","Ра́дуйся, от всіх родо́в ублажа́ємая;","ра́дуйся, ве́ліє дерзнове́ніє к Си́ну Твоєму́ і Бо́гу стяжа́вшая.","Ра́дуйся, ви́ну хода́тайствующая пред Ним за род христия́нський;","ра́дуйся, при́сно умоля́ющая Єго́ за лю́ди согреши́вшия.","Ра́дуйся, ско́рая на́ша Помо́щнице;","ра́дуйся, ми́лостивая на́ша Засту́пнице.","Ра́дуйся, грі́шников ка́ющихся Спору́чнице;","ра́дуйся, су́щих в ско́рбіх і напа́стіх Ізба́вительнице.","Ра́дуйся, тве́рдоє на́ше огражде́ніє от находя́щих на ни озлобле́ній;","ра́дуйся, непости́дная на́ша наде́ждо.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 4","ps":["Бу́рноє мо́ре препли́в, Са́вва святи́й, Се́рбськия Це́ркве первосвяти́тель, за́повідь іспо́лнь вели́каго Са́вви Освяще́ннаго, прия́ благогові́йно чудотво́рную іко́ну Твою́, Млекопита́тельниці, от рук преподо́бних оте́ць Ла́ври єго́ і ра́достно возопи́ к носи́мому на рука́х Твої́х Си́ну Бо́жию: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше і́ноці Святи́я Гори́ Афо́нськия, я́ко честна́я іко́на Твоя́, Богоро́дице, от Ієрусали́ма к ним гряде́ть, с ра́достію ізидо́ша в срі́теніє єя́, і узрі́вше ю, рука́ма святи́теля Са́вви носи́мую, благогові́йно поклони́шася і с весе́лієм си́це Тебі́ вопія́ху:","Ра́дуйся, явля́ющая нам ди́вноє заступле́ніє;","ра́дуйся, сладча́йшеє душ на́ших утіше́ніє.","Ра́дуйся, Го́ру Афо́нськую благода́тним покро́вом осіни́вшая;","ра́дуйся, іко́ни Твоя́ чудотво́рния в ней умно́жившая.","Ра́дуйся, от Ієрусали́ма прише́ствієм Твої́м но́воє зна́меніє ми́лости Твоєя́ нам яви́вшая;","ра́дуйся, іко́ною Твоє́ю насе́льников Святи́я Гори́ благода́тно озари́вшая.","Ра́дуйся, стра́нствія на́шего ти́хоє прибі́жище;","ра́дуйся, спасе́нія на́шего немо́лчная Хода́тайце.","Ра́дуйся, і́ноков прему́драя Учи́тельнице;","ра́дуйся, Свята́го Афо́на Богодарова́нная Влади́чице.","Ра́дуйся, затво́рников сла́дкая Собесі́днице;","ра́дуйся, отше́льников наде́жная Покрови́тельнице.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю води́мії волсви́ достиго́ша хра́мини, в не́йже узрі́ша Отроча́ с Марі́єю, Ма́терію Єго́, і па́дше поклони́шася Єму́. Сего́ ра́ди і ми, грі́шнії, предстоя́ще честні́й іко́ні Твоє́й, Богома́ти, я́ко Само́й Ті су́щей с на́ми і держа́щей на об'я́тіїх Твої́х Богомладе́нця, со умиле́нієм поклоня́ємся Єму́, непреста́нно вопію́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще, Влади́чице, святу́ю іко́ну Твою́ с Богомладе́нцем Ісу́сом, Єго́же, я́ко блаже́нная Ма́ти, от сосцю́ Твоє́ю пита́єши, велича́єм ди́вноє смотре́ніє Єго́ о нас, грі́шних, і умиле́нно вопіє́м Ті такова́я:","Ра́дуйся, Пода́тельнице духо́вния ра́дости;","ра́дуйся, А́гнице, ро́ждшая А́гнця Бо́жия, взе́млющаго гріхи́ ми́ра.","Ра́дуйся, лі́ствице Іа́ковля, земна́я с небе́сними соєдини́вшая;","ра́дуйся, в слід Тебе́ ді́ви Царю́ приводя́щая.","Ра́дуйся, ско́рбних ма́терей утіше́ніє;","ра́дуйся, чад їх благода́тноє охране́ніє.","Ра́дуйся, вдов непремі́нная Засту́пнице;","ра́дуйся, си́рих ско́рая Уті́шительнице.","Ра́дуйся, а́лчущих ще́драя Пита́тельнице;","ра́дуйся, боля́щих неча́ємая Ціли́тельнице.","Ра́дуйся, заблу́ждших Путеводи́тельнице;","ра́дуйся, ю́них цілому́дрію Наста́внице.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєм ми́лости, явле́нния Тобо́ю Святі́й Горі́ Афо́нстій, Богома́ти, і о Покро́ві Твоє́м всечестні́м при́сно ра́дуємся, ви́дим бо, я́ко і ни́ні от іко́ни Твоєя́ ісціле́ній мно́жество бива́єть всім ві́рою прося́щим і умиле́нно вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ луча́ми преди́вних чуде́с Твої́х, Богоро́дице Ді́во, от іко́ни Твоєя́ святи́я, на не́йже ді́вственную лі́поту Твою́ созерца́юще, і рука́ма Твої́ма держи́маго красні́йшаго па́че сино́в челові́чеських Богомладе́нця ви́дяще, к славосло́вію Твоєму́ подвиза́ємся і та́ко глаго́лем:","Ра́дуйся, цві́те ді́вства неув'яда́ємий;","ра́дуйся, ма́терей сла́во і похвало́.","Ра́дуйся, Мирополо́жнице благоуха́нія Христо́ва;","ра́дуйся, алава́стре, на всяк неду́г врачева́нія подаю́щий.","Ра́дуйся, Предста́тельнице у Престо́ла Пресвяти́я і Єдиносу́щния Тро́йці;","ра́дуйся, ста́мно злата́я святи́х святі́йшаго Сло́ва.","Ра́дуйся, преукраше́нний черто́г Царя́ ца́рствующих;","ра́дуйся, Горо́ Свята́я, низхожде́нієм Бо́жиїм просла́вленная.","Ра́дуйся, Це́ркве Христо́ви сія́ющая лі́пота;","ра́дуйся, всего́ ми́ра удобре́ніє.","Ра́дуйся, Небе́сная Цари́це, па́че со́лнця світлі́йшая;","ра́дуйся, Влади́чице, от всіх чино́в А́нгельських покланя́ємая.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 7","ps":["Хотя́щим нам, Богороди́тельнице, благогові́йно лобиза́ти чудотво́рний Твой о́браз, не возбрани́, Всеблага́я, гріхо́в ра́ди на́ших, но, а́ще і недосто́йних, с любо́вію прийми́ і вся проше́нія блага́я на́ша іспо́лни; ві́ми бо, Цари́це, я́ко милосе́рдіє Твоє́ неісче́тно. Сего́ ра́ди с упова́нієм неотсту́пним к Тебі́ прибіга́єм і, сла́в'яще чудеса́ Твоя́, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую ми́лость яви́ла єси́, Богоро́дице, єгда́ неісчерпа́ємий істо́чник ісціле́ній і благода́тную по́мощ всім с ві́рою притека́ющим ко святі́й іко́ні Твоє́й дарова́ла єси́. Сего́ ра́ди, благодаря́ще Тя і пречу́дному о́бразу Твоєму́ со умиле́нієм припа́дающе, хвале́бно зове́м Ті:","Ра́дуйся, от го́рних висо́т всіх нас Ма́тернею любо́вію Твоє́ю назира́ющая;","ра́дуйся, юдо́ль земну́ю многоско́рбную милосе́рдієм Твої́м посіща́ющая.","Ра́дуйся, усе́рдная спасе́нія на́шего Споспі́шнице;","ра́дуйся, ди́вний сосу́д благода́тнаго врачева́нія.","Ра́дуйся, прославля́ющих Тя прославля́ющая;","ра́дуйся, і непочита́ющих іко́ни Твоєя́ на покая́ніє призива́ющая.","Ра́дуйся, во дні бра́ні правосла́вним во́їном крі́пость подаю́щая;","ра́дуйся, во дні ми́ра сердца́ ві́рних веселя́щая.","Ра́дуйся, наги́х і безкро́вних при́сно покрива́ющая;","ра́дуйся, сиро́т і вдови́ць нікогда́же оставля́ющая.","Ра́дуйся, хожде́ніє хроми́м подаю́щая;","ра́дуйся, о́чі сліпи́м отверза́ющая.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 8","ps":["Стра́нствіє на́ше земно́є многоско́рбноє і многом'яте́жноє услажда́єши, Влади́чице, іко́ною Твоє́ю свято́ю, к не́йже притека́юще с ві́рою і любо́вію, упова́єм, я́ко і́мами Тя на небесі́ Ма́тер і Покрови́тельницю Всеблагу́ю, при́сно споспі́шествующую нам в жи́зні сей і по сме́рті нас не оставля́ющую. О сем ра́дующеся і із глубини́ се́рдця благодаря́ще Тя, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі ро́ди христия́нстії при́сно блажа́ть Тя, Богоро́дицю су́щую, і на лик Твой Пречи́стий благогові́йно взира́юще, с ві́рою покланя́ються Тебі́, я́ко Честні́йшей Херуви́м і Сла́внейшей без сравне́нія Серафи́м. Ті́мже і ми, грі́шнії, с любо́вію вопіє́м Ті:","Ра́дуйся, Цари́це, я́ко пресла́вная глаго́лашася о Тебі́;","ра́дуйся, Влади́чице, я́ко небе́сная і земна́я пі́ти Тебі́ не умолка́ють.","Ра́дуйся, свіще́ неугаси́мая, весь мир сія́нієм Твої́м озаря́ющая;","ра́дуйся, благоуха́нний кри́не ді́вства і чистоти́.","Ра́дуйся, любве́ і ми́лости істо́чниче живоно́сний;","ра́дуйся, моли́твеннице благоприя́тная за ни грі́шния ко Христу́ Бо́гу.","Ра́дуйся, грі́шних ко Творцю́ приводя́щая;","ра́дуйся, пра́ведний гнів Єго́ на ми́лость прелага́ющая.","Ра́дуйся, Ни́во неора́нная, Клас спаси́тельний ми́ру ізрасти́вшая;","ра́дуйся, Трапе́зо пресвята́я, живоно́сний Хліб нам дарова́вшая.","Ра́дуйся, лі́ствице, от тьми гріхо́вния ко спасе́нію возводя́щая;","ра́дуйся, звіздо́ пресві́тлая, путь к небесе́м показу́ющая.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 9","ps":["Вся́кая похвала́ не довлі́єть сла́ві Твоє́й, Богоро́дице Ді́во: Ти бо Си́на от Ду́ха Свята́го зачала́ єси́ і невмісти́маго Бо́га во чре́ві вмісти́ла єси́; Тобо́ю спасе́ніє ми́ра возвіща́ється, па́дший же род челові́ч Пречестни́м Рождество́м Твої́м от ві́чния сме́рти свобожда́ється. Сего́ ра́ди із глубини́ душі́ возсила́єм Ті благода́рственная хвале́нія і, я́ко ізба́вленнії от злих, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї многовіща́нния не мо́гуть пости́гнути ве́лію та́йну Твоєго́ присноді́вства, Богоро́дице, ка́ко в рождестві́ і по рождестві́ Ді́ва пребила́ єси́. Ми же, ві́рою правосла́вно велича́юще Тя я́ко Присноді́ву і Ма́тер Предві́чнаго Живота́, прино́сим Ті із глубини́ серде́ць іспові́даніє на́ше і любо́вію вопіє́м Ті:","Ра́дуйся, і́ноков і і́нокинь правосла́вних благо́є наставле́ніє;","ра́дуйся, ревну́ющих о чистоті́ і цілому́дрії тве́рдоє огражде́ніє.","Ра́дуйся, ді́вственних чино́в свята́я Предводи́тельнице;","ра́дуйся, і бра́ка честна́го защи́то і покро́ве.","Ра́дуйся, в ложесна́х Твої́х Бо́га неті́сно вмісти́вшая;","ра́дуйся, Єди́на непоро́чная в жена́х.","Ра́дуйся, нетлі́нная і неіскусобра́чная А́гнця і Па́стиря Ма́ти;","ра́дуйся, Ма́терним Твої́м к Нему́ дерзнове́нієм спасе́ніє ми́ру устроя́ющая.","Ра́дуйся, я́ко о Тебі́ ра́дується а́нгельський собо́р;","ра́дуйся, я́ко о Тебі́ торжеству́єть челові́чеський род.","Ра́дуйся, всі́ми доброді́тельми преукраше́нная;","ра́дуйся, от всіх христия́нских родо́в почита́ємая і ублажа́ємая.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, Предві́чноє Сло́во ізбра́ Тя, Пречи́стая, і із честни́х крове́й Твої́х істка́ Себі́ плоть, яви́ся на землі́ і спасе́ніє ми́ру соді́ла. Ті́мже пісносло́вим Тя я́ко Всепі́тую Ма́тер Ізба́вителя, благода́рственно вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну необори́му і покро́в неруши́м імі́ють Тя, Богоро́дице Ді́во, во оби́теліх і́ночеських подвиза́ющіїся і Помо́щницю Держа́вну всі, на Тя по Бо́зі все упова́ніє своє́ возлага́ющії, Тебі́ бо даде́ся от Го́спода благода́ть моли́твеннаго заступле́нія, і Ти єси́ ві́рних в ді́встві і чистоті́ утвержде́ніє. Ті́мже і ми, грі́шнії, благооти́шіє душе́вноє в Тебі́ обріта́юще, усе́рдно взива́єм:","Ра́дуйся, до́брі подвиза́ющимся Хода́тайце блаже́ннаго упокоє́нія;","ра́дуйся, і́ноком, на плоть во́їнствующим, Пода́тельнице ві́чнаго ра́дованія.","Ра́дуйся, безмо́лвствующих благода́тноє осіне́ніє;","ра́дуйся, ста́рцев благогові́йних отра́до і утіше́ніє.","Ра́дуйся, ста́риць боголюби́вих крі́посте і утвержде́ніє;","ра́дуйся, ю́ношей і дів в ді́вственном житії́ заступле́ніє.","Ра́дуйся, ма́терей ражда́ющих і млеко́м пита́ющих от бід огражда́ющая;","ра́дуйся, всяк во́зраст ві́рних Ма́терняго благопопече́нія Твоєго́ сподобля́ющая.","Ра́дуйся, благочести́вих домо́в покро́ве і благослове́ніє;","ра́дуйся, оби́димих і гони́мих гото́воє заступле́ніє.","Ра́дуйся, оби́дящих гро́зноє обличе́ніє;","ра́дуйся, вражду́ющих любвеоби́льноє примире́ніє.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сим Ті, Христе́ Царю́, во верте́пі ро́ждшемуся і во я́сліх возле́гшему спасе́нія на́шего ра́ди. Ті́мже в пі́сніх велича́єм і Пречи́стую Ма́тер Твою́, Присноді́ву Марі́ю, пред честно́ю іко́ною Єя́ возвіща́юще ми́лості і чудеса́, ї́миже обогати́ся вся вселе́нная. Ти же, Всеблага́я, Сама́ научи́ нас ви́ну взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с Твої́х, Богоро́дице Ді́во, мрак гріхо́вний отгоня́єши, всіх нас на стезю́ спасе́нія наставля́ющи. Ті́мже мо́лим Тя, Всеблага́я, приведи́ нас к ти́хому приста́нищу Твоєму́, да со умиле́нієм прино́сим Ті хвале́бная пі́нія сицева́я:","Ра́дуйся, Пренепоро́чная Влади́чице, Со́лнце Пра́вди ві́рним возсія́вшая;","ра́дуйся, пла́чущим і скорб'я́щим небе́сноє утіше́ніє низпосила́ющая.","Ра́дуйся, ни́щих і убо́гих бога́тство неоскудіва́ємоє;","ра́дуйся, подви́жников благоче́стія во бра́ні духо́вній укріпле́ніє тве́рдоє.","Ра́дуйся, предста́тельство к Бо́гу на́ше крі́пкоє;","ра́дуйся, в час кончи́ни огражде́ніє на́ше необори́моє.","Ра́дуйся, в ра́йських селе́ніїх хода́тайством Твої́м нас водворя́ющая;","ра́дуйся, благоче́стно живу́щим Ма́тернєє милосе́рдіє явля́ющая.","Ра́дуйся, от восто́ка до за́пада непреста́нно сла́вимая;","ра́дуйся, от А́нгел і челові́к в пі́сніх ра́достно превозноси́мая.","Ра́дуйся, рук на́ших діла́ ісправля́ющая;","ра́дуйся, ско́рби лю́тия в ра́дость претворя́ющая.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость іспроси́, Преблагослове́нная Ма́ти, от Си́на Твоєго́, Христа́ Бо́га на́шего, і, воздева́ющи к Нему́ Богоприє́мнії ру́ці Твої́, умоли́ Єго́ вся ни спасти́ і ізба́вити от ги́белі ві́чния: мно́го бо мо́жеть моли́тва Твоя́ Ма́терняя ко благосе́рдію Влади́ки; ті́мже ра́дующеся, поє́м Ро́ждшемуся із Тебе́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пресла́вная чудеса́ Твоя́, Богоро́дице Ді́во, от іко́ни Твоєя́ святи́я при́сно явля́ємая, велича́єм Тя, возвели́чившую род наш. Ти же, Всеблага́я, освяти́ і спаси́ вопію́щия Ті сицева́я:","Ра́дуйся, Ма́ти, безму́жно Предві́чнаго Си́на ро́ждшая пло́тію;","ра́дуйся, я́ко Тобо́ю печа́лі на́ша утоля́ються.","Ра́дуйся, живоно́сний ми́лостей істо́чник всім к Тебі́ прибега́ющим;","ра́дуйся, лучеза́рний світи́льниче омраче́нних душ на́ших.","Ра́дуйся, проро́чеськая сві́тлая похвало́;","ра́дуйся, апо́стольськая нетлі́нная сла́во.","Ра́дуйся, му́чеников утіше́ніє;","ра́дуйся, святи́телей укріпле́ніє.","Ра́дуйся, неотсту́пная Храни́тельнице і́ночеських оби́телей;","ра́дуйся, пра́ведних непреста́нноє ра́дованіє.","Ра́дуйся, ми́ра Влади́чице;","ра́дуйся, я́ко Тобо́ю спасе́ніє содіва́ється.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, Млекопита́тельниці Спа́са на́шего! Усли́ши серде́чная воздиха́нія на́ша, бу́ди те́плая Засту́пниця і Моли́твенниця за нас пред Си́ном Твої́м і Бо́гом, о є́же ізба́витися нам от гріх на́ших, да не пребу́дем вні черто́га Єго́, но сподо́бимся со всі́ми святи́ми пі́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л с небесе́ приї́де к Тебі́, Богоро́дице, благовісти́ти непостижи́моє рожде́ніє от Тебе́ Бо́га Сло́ва, і рече́: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю. Ті́мже і ми, смире́ннії, дерза́єм вопи́ти к Тебі́ си́це:","Ра́дуйся, А́нгелов ра́досте;","ра́дуйся, челові́ков спасе́ніє.","Ра́дуйся, па́дшаго ми́ра обновле́ніє;","ра́дуйся, средості́нія вражди́ разруше́ніє.","Ра́дуйся, проро́чеських глаго́л ісполне́ніє;","ра́дуйся, зако́на дре́вняго преміне́ніє.","Ра́дуйся, А́гнця і Па́стиря во чре́ві Твоє́м упа́сшая;","ра́дуйся, Творця́ небесе́ і землі́ пло́тію ро́ждшая.","Ра́дуйся, Пита́теля вселе́нния млекопита́вшая;","ра́дуйся, млеко́м богопозна́нія ві́рних Пита́тельнице.","Ра́дуйся, пови́вшая Повива́ющаго не́бо о́блаки;","ра́дуйся, дла́ньма нося́щая на Херуви́міх Носи́маго.","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, похва́льная пі́нія прино́сим Ті раби́ Твої́ о явле́нії чудотво́рния іко́ни Твоєя́. Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, соблюди́ і спаси́ от вся́ких бід раби́ Твоя́, с ві́рою і любо́вію вопію́щия Ті:","Ра́дуйся, Богоро́дице Ді́во, ми́лостію Твоє́ю при́сно нас пита́ющая."]},{"h":"Молитва","ps":["О, Пресвята́я Влади́чице Богоро́дице, Пречи́стая і Ми́лостивая Млекопита́тельниці! С любо́вію і благогові́нієм припа́дающе ко свято́му і чудотво́рному о́бразу Твоєму́, на не́мже ви́дяще всіх Творця́ і Го́спода, я́ко Младе́нця, пречи́стим млеко́м Твої́м пита́єма, благохвале́нія і поклоне́ніє прино́сим Ті грі́шнії і недосто́йнії раби́ Твої́ і сле́зно мо́лим Тя: не оста́ви нас без Твоєя́ по́мощі і заступле́нія! Се бо гріхми́ і страстьми́ разсла́бленни єсьми́ і гла́дом духо́вним погиба́юще, а́лчем і жа́ждем пи́щі небе́сния. Оскуді́ бо в нас ві́ра, упова́ніє благо́є, любо́в і благоче́стіє. Несми́сленни і младоу́мни єсьми́, зане́ при́сно умо́м і дія́нми младе́нствуєм, і во́лі Бо́жієй не твори́м, ніже́ разумі́єм, что єсть благо́є іли́ зло́є. Ти же, о Цари́це Небе́сная, Пита́тельниця жи́зні на́шея, покро́вом ми́лости Твоєя́ покрива́ющая все́ленную всю, напита́й нас от істо́чника бла́гости Твоєя́ млеко́м богопозна́нія, да возраста́єм в стра́сі Бо́жії і смиренному́дрії. Ти єси́ ми́ро, ізлія́нноє лю́б'ящим Тя рабо́м Твої́м, росо́ю моли́тв Твої́х Богома́терніх ороси́ нас, да принесе́м Бо́гу плоди́ покая́нія і житіє́ нескве́рноє. Укріпи́ нас малоду́шних, омраче́нних гріхми́ просвіти́, воста́ніє страсте́й на́ших утоли́, ко спасе́нію ві́чному окорми́, не́мощі єстества́ на́шего ісціли́ і не оста́ви до конця́ поги́бнути раби́ Твоя́, Ти бо єси́ єди́на Засту́пниця на́ша і Упова́ніє, і всі наді́ющіїся на Тя не постидя́ться, я́ко да Твої́ми те́плими моли́твами в день Стра́шнаго Суда́ Христо́ва ізба́вимся бу́дущаго осужде́нія і несконча́ємия му́ки, сподо́бимся же ізбра́нних ра́дости і весе́лія ві́чнаго, во є́же со всі́ми святи́ми воспіва́ти Си́на Твоєго́, Христа́ Бо́га на́шего, Єму́же подоба́єть вся́кая сла́ва і благодаре́ніє, честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Без сі́мене от Боже́ственнаго Ду́ха, / во́лею же О́тчею зачала́ єси́ Си́на Бо́жия, / от Отця́ без ма́тере пре́жде вік су́ща, / нас же ра́ди із Тебе́ без отця́ би́вша, / пло́тію родила́ єси́ / і Младе́нця млеко́м пита́ла єси́, / ті́мже не преста́й моли́ти // ізба́витися от бід душа́м на́шим."]},{"h":"Кондак, глас 5","ps":["Душ на́ших чу́вствія очи́стивше, / у́зрим на іко́ні та́їнство пресла́вноє, / Творця́ Вселе́нной і Го́спода ви́шніх сил, / во об'я́тіїх держи́ма і от сосцю́ Твоє́ю я́ко Младе́нця пита́єма, / і, со стра́хом і ра́достію покланя́ющеся Тебі́ / і ро́ждшемуся от Тебе́ Спа́су на́шему, воззове́м: // ра́дуйся, Влади́чице, жи́зні на́шея Пита́тельнице."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Млекопита́тельниці Спа́са на́шего, / і чтим о́браз Твой святи́й, / от него́же благода́ть ісціле́нія // нам при́сно подає́ши."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Табинська»","e":"Akathist to the Theotokos before her icon “Tabynsk”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді ро́да христия́нськаго і страни́ на́шея ізвестной Ізба́вительнице, хвале́бния пі́сні принесе́м ві́рнії Ді́ві влади́чице Богоро́дице. Ти же я́ко іму́щая милосе́рдіє неізрече́нноє, от вся́ких іне ско́рбних обстоя́ній свободи́, да с любо́вію зове́м Ті:","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели див'я́ться Твоєму́ неізрече́нному милосе́рдію к ро́ду челові́чеському, Ді́во Богоро́дице, я́ко благоволи́ла яви́ти святу́ю іко́ну Свою́ близ гра́да Каза́ни, єгда́ нечести́вії ага́ряне воздвиго́ша брань на ми́рния лю́ди, разоря́я гра́ди і ве́сі їх. Ти же, Блага́я, хотя́ уті́шити рабо́в Твої́х прише́ствієм Свої́м, скорб їх на ра́дость преложи́ла єси́, сего́ ра́ди вопіє́м Ті такова́я:","Ра́дуйся, Благослове́нная в жена́х, ра́дуйся, обрі́тшая Благода́ть у Бо́га.","Ра́дуйся, десни́цею Созда́теля Благослове́нная;","ра́дуйся, Ду́хом Святи́м освяще́нная.","Ра́дуйся, Ма́ти Христа́ Бо́га на́шего;","ра́дуйся, в Рождестві́ і по Рождестві́ Ді́во.","Ра́дуйся А́нгельських чино́в удивле́ніє;","ра́дуйся, святи́х немо́лчноє прославле́ніє.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 2","ps":["Прови́дя, Ма́ти і Ді́во, біди́ і см'яте́нія о́крест гра́да Каза́ни, яви́ла єси́ святу́ю іко́ну Свою́, найпа́че же ми́лость Свою́, Влади́чице, людям, да не оскуді́єть ві́ра, да не уга́снеть наде́жда, но да прославля́ється І́м'я свято́є Отця́ і Си́на і Свята́го Ду́ха вопію́щими: Аллилу́я."]},{"h":"Ікос 2","ps":["По вре́мені о́браз Твой честни́й Каза́нський во мно́зі градах і весях страни́ на́шея на досках ізображе́нний, прояви́ си́лу благода́тную істека́ющими чудотвореніями, та́ко і о́крест ві́си Табинськия близ Вознесенськия оби́телі святи́я яви́ся но́вий о́браз Твой. Ні́когда дия́кон чернець, гряду́щий с се́ла во святу́ю оби́тель, усли́ша Твой глас: да потщи́ться правоверующая бра́тія богоспасаємия оби́телі прия́ти М'я в Храм Го́спода Моєго́. Убоя́ся прельще́нія, не внях неземному гла́су сему́, па́ки же возвраща́хуся єму́ путе́м тім, сли́ша глас Твой: Да прийди́ і виждь. Уразумі́х, я́ко глаго́ли сі́ї сви́ше суть, при́йде на мі́сто, отку́да сли́шен бисть глас сей і узрі́х святу́ю іко́ну Ма́ти Бо́жия, на ка́мені ве́лієм близ гори́ Табинськия, у істо́чника водна́го, возра́довахся ду́хом. Ми же див'я́ся сему́ вопіє́м Ті си́це:","Ра́дуйся, явле́нієм святи́я іко́ни Твоєя́ ми́лость Бо́жию нам возвісти́вшая;","ра́дуйся, чи́стим се́рдцем глас Твой святи́й яви́вшая.","Ра́дуйся, Ма́ти щедро́т і милосе́рдія;","ра́дуйся, ми́лости сокро́вище многоці́нноє.","Ра́дуйся, с небе́сних висо́т на раби́ Твоя́ призира́ющая;","ра́дуйся, покро́вом Твої́м нас осіня́ющая.","Ра́дуйся, я́ко ми́лость Твоя́ посіща́єть християнскиє ві́си і гра́ди;","ра́дуйся, я́ко милосе́рдіє Твоє́ серде́ць на́ших отра́да.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 3","ps":["Си́ла благода́ті Твоєя́ осіни́ се́рдце дия́кона благочести́ваго, узревшу єму́ святу́ю іко́ну Твою́, Влади́чице, і об'ят бих стра́хом вели́чія Твоєго́, возра́довахся зіло́, со тща́нієм возтече во оби́тель і возвісти́ бра́тії о дивном обрі́тенії своє́м, ра́достно вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи, Пресвята́я ді́во, іко́на Твоєя́ си́лу благода́тную, яви́ся інокам ра́достію ве́лію, єгда́ позна́ша ми́лости Твоєя́ чрез іко́ну Твою́ Табинськую лю́дем явля́ємия, со стра́хом несо́ша святи́ню сію́ во і поведо́ша о сем воєво́ді Уфимському і Архієре́ю гра́да Каза́ни. Ми же благодарнії вопіє́м Пресвяті́й Ді́ві такова́я:","Ра́дуйся, по́мощ Свою́ всім притекающим к Тебі́ подаю́щая;","ра́дуйся, слез на́ших не отверга́ющая.","Ра́дуйся, к си́ну Твоєму́ моле́ніє о ві́рних ви́ну принося́щая;","ра́дуйся, проше́нія на́ша во бла́го ісполня́ющая.","Ра́дуйся, мона́шествующих покро́ве;","ра́дуйся, ді́вствующих огражде́ніє.","Ра́дуйся, к Бо́гу умо́в і серде́ць направле́ніє;","ра́дуйся, душ на́ших спасе́ніє.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 4","ps":["Бу́ря крамоли́, воздвигнутия от м'ятежник навижденних Айдаром і Кусюмою, разори́ оби́тель Вознесенськую, бра́тію же ізбиши, разсі́ятися пону́ди. Ти же, Всеблага́я, хотя́ по вре́мені яви́тися во сла́ві ве́лієй, сокри́ іко́ну Свою́ чудотво́рную Табинськую. Ми же, див'я́ся таково́му промишле́нію Твоєму́, Влади́чице, вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Богома́ти стена́нія рабо́в Твої́х ві́си Табинськия і ви́дяше скорб їх, зане́ ві́ра Христо́ва поруга́єма бива́ше от неві́рних, в позна́ніє і́стини Христо́вой і ізобличеніє неві́рних благоволи́ла па́ки второ́є яви́ти на ка́мені тім же О́браз Твой честни́й сві́том Боже́ственним озаре́нний. Ми же, див'я́щеся таково́му Твоєму́ попече́нію о нас, вопіє́м Ті такова́я:","Ра́дуйся, явле́ніє іко́ни Твоя́ Табинськия світ і́стинния ві́ри земле́ Уфимськой дарова́вшая;","ра́дуйся, суєверіям і зловеріям омраче́нних просвіти́вшая.","Ра́дуйся, грі́шних ісправле́ніє;","ра́дуйся, ка́ющихся с Бо́гом примире́ніє.","Ра́дуйся, ми́лость согрешившим явля́ющая;","ра́дуйся, ра́ни гріхо́вния істребля́ющая.","Ра́дуйся, скорбниє се́рдця наде́ждою возрождающая;","ра́дуйся, любо́вію їх согріва́ющая.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ святу́ю іко́ну Твою́ уви́діша нечести́вії ага́ряне світя́щую на ка́мені, но не уразумі́ша Твоєго́, Влади́чице, прише́ствія, косни́ бо се́рдцем би́ша, не́навистію ко христия́нам распалишася, надругашися над святи́нею. За тако́є хуле́ніє святи́ні Твоєя́ сліпото́ю нака́зани би́ша, блуждаху по лесу́ неведуща пі́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша хули́телі святи́ні, я́ко зіло́ нака́зани би́ша от Бо́га, не хотя́ху раска́ятися, зане́ ожесточени се́рдцем би́ша, то́кмо єди́н от них, луче́м благода́ті Бо́жієй просвіще́нний, раска́яся і а́біє прозрі́в, возврати́ся со єдиноплеме́нники свої́ми ко святі́й іко́ні і сле́зно моли́шася пред не́ю. По моли́тві єго́ Ма́ти Бо́жия всіх ісціли́. Сего́ ра́ди вопіє́м Пречи́стій:","Ра́дуйся, торжество́ ві́ри в страні́ на́шея явля́ющая;","ра́дуйся, свято́й іко́ною Твоє́ю окаменения се́рдця см'ягчающая.","Ра́дуйся, злові́рія я́вноє обличе́ніє;","ра́дуйся, і́стинния ві́ри утвержде́ніє.","Ра́дуйся, ро́да христия́нськаго возвише́ніє;","ра́дуйся, святи́ні при́сноє огражде́ніє.","Ра́дуйся, я́ко Тобо́ю беззако́ніє наказу́ється;","ра́дуйся, я́ко Тобо́ю хула́ на Бо́га істребля́ється.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і утіше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дници Твоєя́ благода́ті яви́шася прозревшії магометане, возвісти́ша христия́ном ві́си Табинськия о Твоє́м, Богома́ти, явле́нії, но не прия́ша креще́нія, то́кмо пе́рвий прозревший, і́же прия́во ві́ру правосла́вную, возра́довася зіло́ і рече́ всім притекающим ко істо́чнику ціле́бному: се, ни позна́х, я́ко ве́лій єсть Бог землі́ Украї́нській, со умиле́нієм вопія́ Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ Боже́ственний, Влади́чице, єгда́ свята́я іко́на Твоя́ с че́стію ве́лією перенесена бисть от мі́ста явле́нія Своєго́ во весь Табинськую, ізлива́я ві́рним да́ри ціле́бния і всім подава́я по́мощ і утіше́ніє с ві́рою к Тебі́ і во вся́кой ско́рби притекающим і вопію́щим такова́я:","Ра́дуйся, отча́явшихся прибі́жище;","ра́дуйся скорб'я́щих сли́шаніє.","Ра́дуйся, печа́льних утіше́ніє;","ра́дуйся, христия́ном отра́да і огражде́ніє.","Ра́дуйся, в біда́х і печа́ліх те́плоє заступле́ніє;","ра́дуйся, я́ко немощни́м да́руєши укріпле́ніє.","Ра́дуйся, скорб на́шу на ра́дость претворя́ющая;","ра́дуйся, наві́ти вра́жия от нас отгоня́ющая.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 7","ps":["Хотя́ще ві́рнії ві́си Табинськия ви́ну па́м'ятовати о чуде́снім явле́нії іко́ни Твоєя́, Влади́чице, сотвори́ша в честь ди́вния Твоєя́ іко́ни Табинськия пра́зднованіє в п'ято́к дев'я́тий Па́сці, в день второго явле́нія єя́, благодаря́ще Засту́пницю усе́рдную, Бо́гу же воспіва́я: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до яви́ла єси́ Богоро́дице, єгда́ за беззако́нія люде́й пра́ведний гнів Бо́жий пости́же град Стерлитамак, порази́х їх болі́знію холерною, ві́рнії с благослове́нія Архієре́я Іоанни́кия, взе́мши святу́ю іко́ну Твою́, Богома́ти, Табинськую, принесо́ша ю во свой град і сле́зно пред не́ю моляшася. Єгда́ соверше́но бисть моле́бноє пі́ніє — болі́знь сме́ртная оста́ви град. Видяши же лю́діє ми́лость Твою́, Богоро́дице, возопи́ша Тебі́ такова́я:","Ра́дуйся, я́ко за лю́ди согрешившия при́сно пред Сино́м Твої́м і Бо́гом хода́тайствующая;","ра́дуйся, пра́ведний гнів Бо́жий, на них дви́жимий, на ми́лость преклоня́ющая.","Ра́дуйся, прекращенієм холе́ри благода́тную си́лу іко́ні Твоє́й нам возвісти́вшая;","ра́дуйся, ми́лость Бо́жию і согрешившим яви́вшая.","Ра́дуйся, Наде́ждо ненаде́жних;","ра́дуйся, опора немощни́х.","Ра́дуйся, заблу́ждших на путь покая́нія наставля́ющая;","ра́дуйся, ві́ру в жизнь бу́дущаго ві́ка в них пробуждающая.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до зрим о Тебі́, Богома́ти, єгда́ іко́на Твоя́ Табинськая принесе́на бисть во град Оренбург во вре́м'я мо́ра сме́ртнаго і то́кмо яви́ся во гра́ді сем свята́я іко́на Твоя́ — а́біє мор преста́, сего́ ра́ди ві́рнії гра́да сего́ на коєго́ждо лі́то ко дню Рождества́ Пресвяти́я Богоро́диці с ра́достію ве́лію сретиша святу́ю іко́ну Твою́ Табинськую со умиле́нієм вопія́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь аз недосто́йний гріхми́ іспо́лнихся, мирсько́му разсеянію вдахся і о душе́ своє́й вознерадев, оба́че на святу́ю іко́ну Твою́, Влади́чице, взира́я і просвіще́ніє от нея́ безчи́сленним лю́дем зді приходящим ви́дя, па́ки на путь спасе́нія устремля́ються, і в ра́дості се́рдця воспіва́ють Ті си́це:","Ра́дуйся, ше́ствовати путе́м Госпо́днім нас науча́ющая;","ра́дуйся, на путі́ ко Го́споду нас укріпля́ющая.","Ра́дуйся, жестокосердія іскорене́ніє;","ра́дуйся, милосе́рдія в сердця́х насажде́ніє.","Ра́дуйся, к по́двигу цілому́дрія нас призива́ющая;","ра́дуйся, непоро́чних вінча́ющая.","Ра́дуйся, от земна́го бога́тства душі́ ві́рних отвращающая;","ра́дуйся, духо́вними дарова́ньми моля́щихся обогащающая.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 9","ps":["Всі лю́діє землі́ Уфимськия, єгда́ праведній гнів Бо́жий наказа́ша їх бездо́ждієм, со слеза́ми моли́ша Засту́пницю христия́нськую проси́ти у Си́на Своєго́ і Бо́га, да ороси́ть зе́млю їх дожде́м, і єгда́ ві́рнії ві́си Арха́нгельськия, взе́мши святу́ю іко́ну Табинськую, несо́ша ю на село́ своє́, бисть дождь ве́лій, на ра́дость скорб'я́щим і во утіше́ніє пла́чущим, да воспою́ть Го́споду благода́рним се́рдцем: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й глаго́ли і любомудров сми́сли не довлі́ють ко ізглаголанію чуде́с Твої́х, Влади́чице Не́ба, я́ко во утіше́ніє жителям Стерлитамака, низпосла́в сви́ше дождь ве́лій на зе́млю, сим ізба́вила град їх от гла́да і запале́нія о́гненнаго, я́ко да істреби́ться от лиця́ скорб'я́щих вся́ка печа́ль і вся́ка болі́знь, сего́ ра́ди вопіє́м Ті:","Ра́дуйся, обурева́ємих ти́хоє приста́нище;","ра́дуйся, істо́чниче ми́лостей Госпо́дніх.","Ра́дуйся, уни́лих ободря́ющая;","ра́дуйся, моле́ніє скорб'я́щих ко Го́споду вознося́щая.","Ра́дуйся, хода́тайством Твої́м от зно́я і жа́жди нас спаса́ющая;","ра́дуйся, моли́твами от запале́нія огненного ізбавля́ющая.","Ра́дуйся, я́ко а́лчущих пита́єши; ра́дуйся, я́ко во мра́зіх су́щих согріва́єши.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи, Пресвята́я Богоро́дице, страждущего трясовицею Васи́лія во́їна от гра́да Оренбурга, ісціле́ніє подаде́ єму́ чрез іко́ну Свою́ Табинськую. Сей во́їн во сні двукрати во весь Табинськую ідя́ше і та́мо Ма́тер Бо́жию об ісціле́нії умоляше, уразумі́во в со́ніях во́лю Влади́чиці, по́йде немощни́й дві́сти тридесять поприщ, тружда́яся і мно́жицею на зе́млю падо́ша, прише́дше же єму́ во весь Табинськую, єгда́ погрузи́ся во істо́чник святи́й, іді́же іко́на Твоя́ яви́ся, а́біє ісціле́н бисть і ра́дуяся, благодаря́ще Ма́тер Бо́жию, возопиши Го́споду: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ неруши́мая ві́ри яви́лася єси́, Богоро́дице, боголюби́вому о́троку, зане́ сей імевший ча́сти ні́кия от ка́мені, на нем же яви́ся іко́на Твоя́, Влади́чице, мно́гим боля́щим по́мощ подаше єси́, єгда́ бо сі́ї, оми́вши ча́стиці ка́мені водо́ю, піяхом ю і омивахом є́ю ра́ни своя́, а́біє ісціле́ніє приймаша. Ми же благода́ть Твою́ ви́дівше, зане́ і ка́мені си́лу чудотвори́ти дарова́ла єси́, вопіє́м Ті си́це:","Ра́дуйся, святи́є ключи́ целебною водо́ю просла́вившая;","ра́дуйся, да́же ка́меню, на нем же яви́ся свята́я іко́на Твоя́ Табинськая, благода́тную си́лу дарова́вшая.","Ра́дуйся, всім с ві́рою притекающим к ціле́бній іко́ні Твоє́й ісціле́ніє подаю́щая;","ра́дуйся, благодаре́ніє їх ко Го́споду вознося́щая.","Ра́дуйся, я́ко к по́мощі Твоєя́ і малові́рнії притека́ють;","ра́дуйся, я́ко по повелі́нію Твоєму́ і разсла́бленнії со одра́ болі́зні возстаю́ть.","Ра́дуйся, бісо́в ізгна́ніє;","ра́дуйся, помраче́нних умо́в просвітле́ніє.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє возсилаху тебі́, Ма́тері Бо́жієй, всі лю́діє, стоя́щії во хра́мі Твоє́м, видиша покая́ніє согрешившего і милосе́рдіє Твоє́ к нему́ ні́кий во́їн Гавриї́л, за нарушеніє обі́та, данного Тебі́, в разслабле́нії су́щий — ісціле́н бисть, єгда́ святого та́їнства єлеосвященія сподо́бльшася к чудотво́рному о́бразу Твоєму́ припаде́. Ми же, грі́шнії, мно́гажди го́спода гріхми́ свої́ми прогнівля́ющії, мо́лим Тя, і нам проще́ніє гріхо́в іспроси́ со упова́нієм пою́щим: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ зрі́нію дарова́ла єси́, Влади́чице, старице ні́коєй, осем літ во гра́ді Оренбурге сліпото́ю страдавшей; єгда́ бо в сретенії Твоєя́ і́де, сро́дницею своє́ю оста́влена бисть, стісне́нія ра́ди наро́да, внеза́пу прозрі́ і ви́дяще іко́ну Твою́ святу́ю возра́довася зіло́, ми же со тре́петом вопіє́м Ті си́це:","Ра́дуйся благода́тная, врачева́нія оби́льно істоча́ющая;","ра́дуйся, ісціле́нієм неду́гов притека́ющих к Тебі́ веселя́щая.","Ра́дуйся, сліпи́х прозрі́ніє;","ра́дуйся, глухи́х сли́шаніє, німи́х глаго́ланіє.","Ра́дуйся, хроми́х хожде́ніє;","ра́дуйся, вдов і сиро́т заступле́ніє.","Ра́дуйся, душ на́ших освяще́ніє;","ра́дуйся, земноро́дних упова́ніє.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть Твою́ яви́ нам, Пресвята́я Ді́во, молящимся Тебі́ пред честні́й іко́ною Твоє́ю Табинською, ізле́й щедро́ти Твоя́ на гра́ди і ве́сі не то́кмо кра́я Приуральськаго, но во всем ми́рі честни́й о́браз Твой почита́ющим і пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́ от іко́ни Твоєя́ Табинськия явления, мо́лим Тя, Влади́чице, Ли́ка Твоєго́ от страни́ на́шей не отврати́ і всім приводящим к чудотво́рному о́бразу Твоєму́ і ми́лости от Теб'я́ ожидающим во блага́я вся проше́нія іспо́лни, да всі воспоє́м Ті си́це:","Ра́дуйся, іко́ною Твоє́ю Благослове́ніє Бо́жиє кра́ю на́шему принося́щая;","ра́дуйся, істо́чник Твой я́ко пропові́дник спасе́нія ві́си Табинськия оставившая.","Ра́дуйся, смире́нних се́рдцем Богові́дінієм просвіща́ющая;","ра́дуйся, я́ко сла́ву Бо́жию воспіва́ти нас науча́ющая.","Ра́дуйся, к Тебі́ же падшиє в покая́нії притека́ють;","ра́дуйся, я́ко призивающиє і́м'я Твоє́ свято́є от паде́нія гріхо́внаго возстаю́ть.","Ра́дуйся, в час сме́ртний чту́щих Тя не оставля́ющая;","ра́дуйся, і по сме́рті во оби́телі небе́сния душі́ їх сопровождающая.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Христа́ Бо́га на́шего, прийми́ моли́тви раб Твої́х і мир іспроси́ всім, с ві́рою і любо́вію притекающим к іко́ні Твоє́й Табинськой, і живо́т ві́чний да́руй їм со умиле́нієм пою́щим: Аллилу́я, Аллилу́я, Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели див'я́ться Твоєму́ неізрече́нному милосе́рдію к ро́ду челові́чеському, Ді́во Богоро́дице, я́ко благоволи́ла яви́ти святу́ю іко́ну Свою́ близ гра́да Каза́ни, єгда́ нечести́вії ага́ряне воздвиго́ша брань на ми́рния лю́ди, разоря́я гра́ди і ве́сі їх. Ти же, Блага́я, хотя́ уті́шити рабо́в Твої́х прише́ствієм Свої́м, скорб їх на ра́дость преложи́ла єси́, сего́ ра́ди вопіє́м Ті такова́я:","Ра́дуйся, Благослове́нная в жена́х;","ра́дуйся, обрі́тшая Благода́ть у Бо́га.","Ра́дуйся, десни́цею Созда́теля Благослове́нная;","ра́дуйся, Ду́хом Святи́м освяще́нная.","Ра́дуйся, Ма́ти Христа́ Бо́га на́шего;","ра́дуйся, в Рождестві́ і по Рождестві́ Ді́во.","Ра́дуйся А́нгельських чино́в удивле́ніє;","ра́дуйся, святи́х немо́лчноє прославле́ніє.","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді ро́да христия́нськаго і страни́ на́шея ізвестной Ізба́вительнице, хвале́бния пі́сні принесе́м ві́рнії Ді́ві влади́чице Богоро́дице. Ти же я́ко іму́щая милосе́рдіє неізрече́нноє, от вся́ких іне ско́рбних обстоя́ній свободи́, да с любо́вію зове́м Ті:","Ра́дуйся, Похвало́ Табинськая і всего́ ми́ра Наде́ждо і Утіше́ніє."]},{"h":"Молитва","ps":["О Пресвята́я Влади́чице, Ді́во Богоро́дице! Прийми́ мольби́ от нас, прилі́жно призива́ющих і моля́щихся Тебі́, покажи́ ско́роє Твоє́ заступле́ніє, покажи́, я́ко мо́жеши, я́ко Ма́ти Бо́га, призива́єм Тя от се́рдця, со слеза́ми припа́дающе пред пречи́стим Твої́м о́бразом. О Бо́жия Ма́ти! Спаси́ нас і не даждь в расхище́ніє супоста́том, ніже́ да на́йдеть на ни вся зла́я, я́же гріхи́ на́ша угото́ваша нам, ніже́ беззако́нія на́ша да превзи́дуть на глави́ на́ша. Виждь на́ша нестерпи́мия печа́лі, ско́рби, ну́жди, болі́зні, стра́сті; вооружи́ся на ни лука́вно враг, язи́ком, я́коже мече́м, хотя́ нас погуби́ти, но Твоє́ю, Богороди́тельнице, крі́постію предвари́. Уста́ челові́ков, я́ко львов лю́тих, гро́ба тягча́йше отверзо́шася, го́рко поглоти́ша ни; но Ти, Богороди́тельнице яви́ся наде́жда ненаде́ющимся і низложи́ крі́пость їх, да у́зрять вразі́ і постидя́ться, да разумі́ють і ви́дять Твою́, є́же по нам сопроти́в борю́щую си́лу, і в про́пасть преіспо́днюю низложи́ їх. Да загради́ться всяк язи́к, лука́вим поуча́яйся, да молча́ть уста́ льсти́вия і уста́, непра́ведно глаго́лющия на пра́веднаго беззако́ніє, горди́нею і за́вистію вражде́бною вку́пі. Призива́ющим Тя, Богоро́дице, от душі́ нело́жно во вся́кой ско́рби, і в болі́зніх разли́чних, і в біда́х лю́тих спі́шно усли́ши, Влади́чице, сих ізбавля́ющи при́сно моли́твами Свої́ми; душ спасе́ніє, ві́ри сохране́ніє, от гріхо́вних на́виков ізбавле́ніє, ми́рную христия́нськую кончи́ну і Ца́рствія Небе́снаго наслі́діє да́руй нам. Да і́м'я Твоє́, Богоро́дице, на землі́ славослочвиться, І́же бо, із Тебе́ возсія́в, грі́шником держа́вную наде́жду і сті́ну неруши́мую Тя дарова́ во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Наста́ днесь пресві́тлий пра́здник, / Пречи́стая Ді́во, Влади́чице, / честни́я Твоєя́ Таби́нськия іко́ни, / я́же па́че луч со́лнечних возсія́, / істоча́ющи ціле́бния да́ри / с ві́рою к Тебі́ притека́ющим. / Тя бо Христо́с Помо́щницю лю́дем Свої́м дарова́ / покрива́ти і спаса́ти от вся́кия біди́ раби́ Своя́, // Єди́ну Благослове́нную."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді ро́да христия́нськаго / і страни́ на́шея ізві́стній Ізба́вительнице, / хвале́бния пі́сні принесе́м, ві́рнії, Ді́ві, Влади́чице Богоро́дице, / Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, / от вся́ких нас ско́рбних обстоя́ній свободи́, да с любо́вію зове́м Ті: // ра́дуйся, всего́ ми́ра Наде́ждо і Утіше́ніє, Похвало́ Таби́нськая."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже болі́зні на́ша врачу́єши і ду́ші на́ша к Бо́гу возво́диши."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Озерянська»","e":"Akathist to the Theotokos before her icon “Ozeryany”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, невече́рняго Сві́та Роди́тельнице, Боже́ственноє зна́меніє спасе́нія — Христа́ Богомладе́нця на ру́ку Своє́ю держа́щи, моли́твам Це́ркве земни́я вне́млющей, струї́ животво́рния от явле́нния іко́ни Своєя́ Озеря́нськия всім ві́рним істоча́ющей, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице. Но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́ і щедро́тами Си́на Твоєго́ ду́ші на́ша озари́, да зове́м Ті:","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, спасе́ніє на́ше предвозвіща́я, благослове́нную в жена́х пронарече́ Тя, Богоро́дице. Ми же, благове́стнику Бо́га Ви́шняго вне́млюще, ве́лію та́їнству див'я́щеся, ра́дуємся; Тебі́ — зна́меніє Ли́ка Своєго́ Озеря́нськаго нам дарова́вшую — Ма́тер Го́спода на́шего іспові́дуєм, і я́ко Ма́тері милосе́рдія і щедро́т, со благогові́нієм вопіє́м Ті:","Ра́дуйся, свяще́нноє сокро́вище сла́ви Бо́жієй, свіщенося́ще во Свята́я Святи́х сві́тло введе́нная;","ра́дуйся, благоволе́нія Бо́жия предображе́ніє і челові́ков спасе́нія пропові́даніє.","Ра́дуйся, проро́чеських прорече́ній сбитіє́ многоці́нноє, Христа́ всім предвозвести́вшая;","ра́дуйся, о Тебі́ бо Небе́сная вся удиви́шася, зря́ще Ду́ха Свята́го в Тя все́льшася.","Ра́дуйся, Глави́зно на́шего спасе́нія, Трийпоста́сноє єстество́ в Єди́ном Божестві́ ми́ру яви́вшая;","ра́дуйся, Отроча́ Мла́до, О́тчеє Сія́ніє, мир просвіти́вшеє, нам роди́вшая.","Ра́дуйся, Ма́ти Пречи́стая, пре́жде рождества́ і по рождестві́ Ді́ва преби́вшая;","ра́дуйся, я́ко о Рождестві́ Си́на Твоєго́ всі земноро́днії, спаса́ющеся, возвесели́шася.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 2","ps":["Ви́дя благочести́вий муж ві́си Озеря́нськия, єгда́ ізи́де на ді́ланіє своє́, святу́ю іко́ну Твою́, Влади́чице, внеза́пу косо́ю єго́ разсече́нную, со слеза́ми умиле́нія к Ли́ку Твоєму́ пове́ржеся, і со благогові́нієм разсіче́нния ча́сти в дом свой принесе́, сле́зно прося́ умилостивле́нія о грісі́ своє́м. Єгда́ же воу́трії сих не обрі́те, стра́хом і ско́рбію об'я́т бисть, поми́сли бо гні́ву Бо́жию на до́мі своє́м би́ти, со умиле́нієм возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ти хотя́ та́йни сея́ си́лу, є́юже сокри́ся із до́му єго́ свята́я іко́на Твоя́, Влади́чице, муж сей боголюби́вий на мі́сто разсіче́нія єя́ поспіши́. І єгда́ же па́ки сраще́нну сію́ обрі́тше, зна́меніє ве́ліє в сем уразумі́, о нем же ієре́ю Фео́дору пові́да, і лю́дем ві́си Озеря́нськия о чудеси́ ве́ліє возвісти́. Ті́ї же о Твоє́м, Богома́ти, милосе́рдії сли́шавше, гла́сом ра́дованія благода́рні возопи́ша:« Отку́ду нам сіє́, да Ма́ти Го́спода на́шего к нам при́йде!» Си́це умиля́ющеся, воспіва́ху Ті такова́я:","Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, І́мже мир от гріха́ і сме́рті спасе́ся;","ра́дуйся, благослове́н бо Плод чре́ва Твоєго́, І́мже глава́ змі́єва сокруши́ся.","Ра́дуйся, Це́ркве Христо́ви, седьмію́ Вселе́нськими Собо́ри утвержде́нния, при́сноє украше́ніє;","ра́дуйся, ві́ри Правосла́вния, Ду́хом Святи́м огражда́ємия, непоколеби́моє утвержде́ніє.","Ра́дуйся, Препросла́вленная, во дні наше́ствія іноплеме́нник всемо́щно нас охраня́ющая;","ра́дуйся, мольби́ ві́рних Свої́х, пред Пречи́стим Твої́м о́бразом приноси́мия, ми́лостиво приє́млющая.","Ра́дуйся, сраще́нієм святи́я іко́ни Твоєя́ му́жа пра́ведна зіло́ возвесели́вшая;","ра́дуйся, разсече́нноє дия́волом єстество́ на́ше Рождество́м Си́на Твоєго́ па́ки с Бо́гом соєдини́вшая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 3","ps":["Си́ла благода́ті неісповіди́мая не то́кмо от святи́я іко́ни Твоєя́, Пречи́стая, ві́рним істоча́шеся, но і во істо́чниці, на мі́сті чу́днаго явле́нія єя́, хроми́м хожде́ніє, глухи́м сли́шаніє, сліпи́м прозрі́ніє оби́льно подава́шеся. Та́ко бо Твоєго́ Ма́терняго милосе́рдія бе́здну неізслі́димую лю́діє ви́дівше, от неду́гов душе́вних і тіле́сних ісціля́хуся, сердця́ же своя́ в любві́ Бо́жієй утвержда́ху, с весе́лієм пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я сіє́ неопису́ємоє сокро́вище ві́ри — Твоєго́, о Богома́ти, Ли́ка Пречи́стаго благослове́ніє, і в нем Твой Покро́в і землі́ на́шея благода́тноє украше́ніє, ієре́й Бо́жий Фео́дор, умиля́яся, все імі́ніє своє́ разда́ і в преді́ліх ві́си Озеря́нськия, святу́ю оби́тель — хра́мину Ли́ку Твоєму́ со пустиннолю́бцем Севастія́ном воздви́же; себе́ же, в же́ртву живу́ю — і́ночествовати в ней, Си́ну Твоєму́ і Бо́гу на́шему приведе́, іді́же со іни́ми пустиннолю́бці о Тебі́, Благода́тная, ра́дуяся, синолю́бно воспі́ такова́я:","Ра́дуйся, Му́дрость, Сло́во і Си́лу — Си́на О́тча, із Тебе́ воплоти́вшагося, ми́ру яви́вшая;","ра́дуйся, Христа́ — Па́сху нетлі́нную ме́ртвим, живи́м і гряду́щим угото́вившая.","Ра́дуйся, Влади́чице ми́лостивая, Свой Боже́ственний Покро́в на нас простира́ющая;","ра́дуйся, Голуби́це чадолюби́вая, утіше́ніє благо́є в сердця́ на́ша низпосила́ющая.","Ра́дуйся, Покро́ве ши́рший о́блака, явле́нієм іко́ни Твоєя́ ми́лостивно нас посіти́вшая;","ра́дуйся, любвеоби́льная Ма́ти, зе́млю Ха́рковськую благода́тно освяти́вшая.","Ра́дуйся, Бо́жия Сло́ва преди́вноє Селе́ніє, град наш і лю́ди от наше́ствія вра́жия охраня́ющая;","ра́дуйся, незри́мая путеводи́тельнице, к небе́сному Оте́честву нас руководя́щая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 4","ps":["Бу́рю жите́йських скорбе́й і напа́стей в лю́діх утоли́ти хотя́щи, святу́ю іко́ну Твою́ на утіше́ніє нам дарова́ла єси́, Влади́чице, Ю́же а́ки Са́мую Тя с на́ми су́щую зря́ще, недоумі́юще, взива́єм: ку́ю Ті похвалу́ принесе́м, Засту́пнице усе́рдная, Я́же істо́чник благода́тних ісціле́ній пред Пречи́стим о́бразом Твої́м с ві́рою моля́щимся і Твоєя́ по́мощі прося́щим всеще́дро істоча́єши, і си́це непреста́нно нас ми́луєши, ра́зві неісчерпа́ємия щедро́ти Твоя́ велича́юще, благода́рственно вопіє́м Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше бли́жнії і да́льнії лю́діє о пречу́дном явле́нії святи́я іко́ни Твоєя́ і о чудесі́х от нея́ бива́ємих, со умиле́нієм в святу́ю оби́тель Озеря́нськую притека́ху, і во вся́ких ско́рбіх жите́йських, і в дні наше́ствія іноплеме́нник, в наде́жді спасе́нія своєго́, о Тебі́, Всепі́тая Ма́ти, уверя́шася, і си́це ликовству́юще, Го́спода любо́вію прославля́ху. Ті́мже і ми, наде́жду ра́дости сея́ приє́мше, о Го́споді ра́дуємся, Тебі́ же гла́сом хвале́нія прино́сим такова́я:","Ра́дуйся, А́гнице, ро́ждшая А́гнця, взе́мшаго гріхи́ ми́ра, — небесе́ і землі́ Цари́це і Влади́чице;","ра́дуйся, всіх ві́рних от зол огражде́ніє і свяще́нноє прибі́жище.","Ра́дуйся, Блага́я Уті́шительнице, неча́янную ра́дость в святі́й іко́ні Твоє́й нам прине́сшая;","ра́дуйся, душ немощни́х Ціли́тельнице, бла́гость любве́ Бо́жия нам откри́вшая.","Ра́дуйся, упова́ніє на милосе́рдіє Бо́жиє в сердця́ на́ша благода́тно вселя́ющая;","ра́дуйся, теплото́ю любве́ Боже́ственния сердця́ на́ша оживотворя́ющая.","Ра́дуйся, одушевле́нний Хра́мі, Вели́каго Царя́ Боже́ственноє жили́ще;","ра́дуйся, Селе́ніє Небе́сноє, Херуви́м пребо́льше і Серафи́м преви́ше.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ іко́на Твоя́, о Богома́ти, уподо́бися, єгда́ святи́я оби́телі — Озеря́нськую, Куря́жськую і Ха́рковськую обтека́ше і цельбоно́сньми струї́, неоску́дно от нея́ істоча́ющимися, ізоби́льно ві́рних напая́ше і, благода́тію Свята́го ду́ха тіх оживотворя́ющи, тіле́сні і душе́вні, по ві́рі їх, ісціля́ше. Ми же душе́внима на́шима очи́ма к Тебі́, Первоо́бразу Єя́, возво́димся, неду́гов на́ших ісціле́нія, гріхо́в проще́нія і Небе́сним Уті́шителем душ на́ших посіще́нія уми́льно про́сим, с ві́рою вопію́ще о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше іко́ну Твою́, Влади́чице, косо́ю разсече́нную і чудоді́йственно сраще́нную су́щу, і то́ки чуде́с от нея́ ізлива́ємия, всі лю́діє, со усе́рдієм к ней притека́юще, Ма́терній Покро́в Твой і защище́ніє, наде́жду і умилостивле́ніє в ней разуміва́ху. Си́це і ми, стріла́ми врага́ разсіка́ємі і волна́ми страсте́й потопля́ємі, душе́вні ізнемога́юще, в Тебі́, о Всеблага́я, наде́жду на́шего спасе́нія іму́ще, дерза́юще мо́лимся: усли́ши нас, грі́шними усти́ глаго́лющих Ті сицева́я: Ра́дуйся, Преблага́я Покрови́тельнице гра́да на́шего, Твої́ми бо моли́твами ро́ди христия́нстії спаса́ються; ра́дуйся, всіх грехо́вне блужда́ющих на путь жи́зні ві́чния до́брі наставля́ющая.","Ра́дуйся, безу́мства, ле́ни і страсте́й си́лою любве́ Твоєя́ нас ми́лостивно спаса́ющая;","ра́дуйся, бі́дния ду́ші на́ша, огне́м Ду́ха Свята́го, на по́двиг любве́ согріва́ющая і укріпля́ющая.","Ра́дуйся, всіх под Твой покро́в і защище́ніє Ма́тернєє приє́млющая;","ра́дуйся, в по́двигі ві́ри ізнемога́ющих моли́твам їх вне́млющая.","Ра́дуйся, боля́щия і безнаде́жния от одра́ болі́зні возставля́ющая;","ра́дуйся, ві́рная Спу́тнице, путеше́ствующих і по мо́рю пла́вающих от вся́ких бід ізбавля́ющая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 6","ps":["Пропові́дник немо́лчен благода́тния по́мощі Богома́тере яви́ся челові́к ні́кий, су́ху ру́ку іми́й, і́же со слеза́ми умиле́нія к іко́ні Єя́ святі́й припа́дая, удо́б ісціле́ніє прия́т, і о чудеси́, на нем би́вшем, с ра́достію і благодаре́нієм всій це́ркві пові́да. Ми же, іму́ще сію́ істо́чник благода́тних ісціле́ній, найпа́че же пред Престо́лом Бо́жиїм Засту́пниці усе́рдния за всіх нас Ма́тернєє заступле́ніє, со дерзнове́нієм вопіє́м лю́б'ящему нас Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ нам, па́че луч со́лнечних, свята́я іко́на Твоя́, Влади́чице, в преді́ліх Озеря́нських, єгда́ губи́тельная я́зва на страну́ на́шу на́йде, і мно́гі о́стрієм сме́рті ізсіче́. Лю́діє же, гнів Бо́жий ви́дяще, со слеза́ми умиле́нія ко святі́й іко́ні Твоє́й, о Богома́ти, поверга́хуся, і не то́кмо правосла́внії, но і інові́рнії, к істо́чнику Твоєго́ милосе́рдія притека́вшії с ві́рою, ісціля́хуся. Си́це бо ми́лость Бо́жию Твої́ми Ма́терніми моли́твами на себі́ ви́дяще, со благодаре́нієм воспіва́ху Ті такова́я:","Ра́дуйся, в дні мо́ра я́звеннаго непрело́жная на́ша Наде́ждо і Спаси́тельнице;","ра́дуйся, всіх, в неудобоїсці́льних неду́зіх стра́ждущих, премилосе́рдная Ціли́тельнице.","Ра́дуйся, ум наш, небреже́нієм омраче́нний, благода́тними струя́ми, от іко́ни Твоєя́ ізлива́ємими, озаря́ющая;","ра́дуйся, близ сме́рти су́щия і душе́вні ізнемога́ющия ми́лостивно к жи́зні возвраща́ющая.","Ра́дуйся, сві́тлоє благода́ті позна́ніє, о Тебі́ бо вся си́ли небе́сния хва́ляться;","ра́дуйся, наде́ждо благ ві́чних, Тобо́ю бо земноро́днії к жи́зні ві́чній приуготовля́ються.","Ра́дуйся, Ма́ти Предві́чнаго Бо́га, ціле́бную ра́дость ві́рним істоча́ющая;","ра́дуйся, Честно́ю Кро́вію Си́на Твоєго́ гріхи́ ми́ра омива́ющая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 7","ps":["Хотя́щи яви́ти лю́дем стра́ждущим Твоєя́ Ма́тернія любве́ неісчерпа́ємую щедро́т бе́здну, а́ки студенці́ в пусти́ні зно́йней, чудотво́рния іко́ни Твоя́ і но́вая зна́менія от них, о Богома́ти, дарова́ла єси́, да всі в болі́зніх душе́вних і тіле́сних неісці́льно ізнемога́ющи, і ко Твоєму́ милосе́рдію с ві́рою притека́ющії, спасе́ніє обріта́ють. Та́ко у іко́ни Твоєя́ Озеря́нськия немощні́ї і одержи́мії, ісціле́нія душ і тіле́с свої́х приє́млюще, с весе́лієм і благодаре́нієм воспева́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую піснь хвале́нія принесе́ Ті па́жить Ха́рковськая, Ма́ти Врача́ душ і тіле́с на́ших, єгда́ ні́кая сліпа́я отрокови́ця с ма́терію своє́ю сле́зния моли́тви у іко́ни Твоєя́ Озеря́нськия творя́щи, внеза́пну ве́ліїм гла́сом ра́дованія возопи́: «О, ма́ти моя́! Світ Бо́жий ви́жу, тьму непрохо́дную оче́с мої́х просвіща́ющий!» Лю́діє же, ви́дівше Твоєго́, о Богома́ти, благода́тнаго врачева́нія си́лу, Твоєму́ милосе́рдію себі́ вверя́ху, с ві́рою і любо́вію ко святі́й іко́ні Твоє́й припа́дающе, такови́ми взива́ху похвали́:","Ра́дуйся, Істо́чниче милосе́рдія неісчерпа́ємий, неісці́льних болі́зней врачева́ніє содержа́щий;","ра́дуйся, всіх оста́вленних врача́ми Твоє́ю благода́тною си́лою ісціля́ющая.","Ра́дуйся, дів благочести́вих невести́тельнице і усе́рдная о нас моли́твеннице;","ра́дуйся, во іскуше́ніїх і собла́знах жите́йських блужда́ющих ко спасе́нію Путеводи́тельнице.","Ра́дуйся, Звіздо́ неугаси́мая, зрі́ти Бо́га Ви́шняго нас просвіща́ющая;","ра́дуйся, растлі́нія душе́внаго і со́вісти лука́вства нас ізбавля́ющая.","Ра́дуйся, о Тебі́ бо ма́тері і дще́рі, і неві́сти Христо́ви наде́жду іму́ще, спаса́ються;","ра́дуйся, боже́ственную ра́дость і ві́чноє спасе́ніє упова́ющим на Тя приуготовля́ющая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 8","ps":["Стра́шноє і ужа́сноє виді́ніє лю́дем Бо́жиїм бисть, єгда́ у святи́я іко́ни Твоєя́, Влади́чице, чу́до ве́ліє і неізрече́нноє соверши́ся: дщер бо ні́кая, бі́сом томи́мая су́щи, хулу́ стра́шную на Сію́ ізрека́ше, оба́че моли́тв ра́ди Святи́я Це́ркве, найпа́че же Твоєго́ предста́тельства си́лою, от сего́ лука́вства спасе́на бисть, і на славосло́віє Твоє́, Пречи́стая, подви́жеся. Ми же ра́дуємся і веселі́мся, я́ко не посмію́ться о нас вразі́ на́ші, ніже́ погуби́ть нас Госпо́дь гріх ра́ди на́ших, моли́твами Твої́ми. Сего́ ра́ди, благодаря́ще, о Тебі́ вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся во ви́шніх пребива́ющи і ни́жніх, к Ли́ку Твоєму́ свято́му припа́дающих, ніка́коже оставля́вши, Богоро́дице. Си́це бо челові́к, ду́ха зла́го іми́й, с ві́рою моля́ся пред Пречи́стим о́бразом Твої́м Озеря́нським, Влади́чице, ісціле́н бисть, і в ра́дості душе́вній о благодія́нії на нем би́вшем, благодаре́ніє Тебі́ принесе́. С ним же і на нас, о Всеблага́я, во вре́м'я благопотре́бно посіти́ і от ловле́нія дия́воля ду́ші на́ша сохрани́, да не постиді́мся, ніже́ посрамі́мся, принося́ Ті сицеви́я похвали́:","Ра́дуйся, я́ко і́менем Твої́м, па́че вся́каго і́мене, пліне́нія дия́воля і всея́ си́ли вра́жия челові́ци свобожда́ються;","ра́дуйся, я́ко призива́ющії і́м'я твоє́ от клевети́ челові́чеськія і внеза́пния сме́рті Тобо́ю ізбавля́ються.","Ра́дуйся, бе́дствующим на вся́ком мі́сті всеусе́рдная Предста́тельнице;","ра́дуйся, за оби́димих, озло́бленних і уничиже́нних при́сная Хода́тайце.","Ра́дуйся, Ти бо ка́ющихся грі́шников із че́люстей духо́в зло́би ізима́єши;","ра́дуйся, Ти бо всіх на Тя упова́ющих в любо́в Бо́жию вво́диши.","Ра́дуйся, красото́ю ді́вства Твоєго́ воспіва́ти вели́чіє Бо́жиє нас науча́ющая;","ра́дуйся, Рождество́м Си́на Твоєго́ гро́зноє сме́рти жа́ло притупля́ющая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 9","ps":["Всі су́щії в біда́х, болі́зніх і печа́ліх, ра́достно восхва́лим Святу́ю Засту́пницю на́шу, Богоро́дицю, обре́тшую благода́ть у Бо́га, во є́же неду́жния ісціля́ти, немощни́я укріпля́ти, пліне́нния свобожда́ти і стра́ждущия от духо́в нечи́стих і про́чих бід ізбавля́ти. Ті́мже, я́ко несомні́нній Предста́тельнице на́шей уми́льно глаго́лем: помози́ і научи́ нас, о Милосе́рдствующая Ма́ти, во́лю Бо́жию всегда́ твори́ти, і пребива́ти в любві́ Єго́, і я́ко кади́ло благово́нноє, непреста́нно приноси́ти Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії недоумі́ють, что глаго́лати о Тебі́, Ма́ти Бо́жия, ви́дяще та́йну необ'є́млемую і вели́чіє неопису́ємоє свята́го Ли́ка Твоєго́, Ді́во Чи́стая, да́ром чудотворе́ній сія́ющаго і всіх, припа́дающих к нему́ с ві́рою, цільбоно́сними дара́ми снабдева́ющаго. Ми же, неісче́тная благодія́нія сія́ ві́дуще, а́ще і от скве́рних усте́н на́ших, оба́че умиле́нною душе́ю і се́рдцем сокруше́нним, дерза́єм воспіва́ти Тебі́ сія́ похвали́:","Ра́дуйся, Отця́ Небе́снаго благоволе́нія предображе́ніє, ка́ющихся грі́шников милосе́рдієм Бо́жиїм снабдіва́ющая;","ра́дуйся, Єди́на Ма́ти милосе́рдія, вдов і сиро́т ми́лующая і пита́ющая.","Ра́дуйся, на горі́ Афо́нстій, Поча́євстій і в іни́х оби́теліх іко́нами Твої́ми пресла́вно чудоде́йствующая;","ра́дуйся, но́вую купі́ль Силоа́мськую в пусти́ні Озеря́нстей ві́рним на утіше́ніє істочи́вшая.","Ра́дуйся, і́ноков благоподвиза́ющихся к Оте́честву Небе́сному ві́рная Предводи́тельнице;","ра́дуйся, супру́жеств христия́нських благослове́ніє і чад їх Преблага́я Покрови́тельнице.","Ра́дуйся, Це́ркве Небе́сния при́сноє ра́дованіє, земни́я же от всіх ко́зней вра́жиїх непреодолі́нноє ізбавле́ніє;","ра́дуйся, во ві́чнім Ца́рствії Си́на Твоєго́, ра́дости неізрече́нния ві́рним уготовле́ніє.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 10","ps":["Спаси́тельноє прибі́жище і Твоєго́ Предста́тельства увіре́ніє, і милосе́рдія Твоєго́ явле́ніє — іко́на Озеря́нськая нам, Влади́чице, показа́ся, пред Не́ю же ду́ші на́ша в моли́тві ізлива́єм і ві́рою Тебі́ вопіє́м: воззри́, Милосе́рдная, на лю́ди Твоя́, вся ско́рбі на́ша і печа́лі утоли́, утіше́ніє благо́є в сердця́ на́ша низпосли́, і спасе́ніє ві́чноє душа́м на́шим, Пречи́стая, іспроси́, да спаса́ємі Тобо́ю, Си́ну Твоєму́ і Бо́гу на́шему благода́рно зове́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тве́рду і от бід огражде́ніє, проти́ву ко́зней вра́жиїх спаси́тельноє прибі́жище, неду́гов ісціле́ніє і і́ни да́ри мно́гі в святі́й іко́ні Твоє́й, Влади́чице, оби́льно дарова́ла єси́ нам. Сію́ благові́рний христолю́бець, і́же ушеси́ свої́ми зіло́ страда́ше, в трикра́тном явле́нії ви́дів, со умиле́нієм к Той припа́дая, благода́тнаго ісціле́нія сподо́бися. Та́ко ви́дяще любве́ Твоєя́, Богома́ти, неісчерпа́ємоє мо́ре, дерза́юще, мо́лимся: усли́ши нас убо́гих, грі́шними усти́ глаго́лющих Ті сицева́я:","Ра́дуйся, Предві́чнаго Царя́ Роди́тельнице, Це́ркве Правосла́вния забра́ло і огражде́ніє;","ра́дуйся, наро́да на́шего от бід Храни́тельнице, і от всіх враго́в ізбавле́ніє.","Ра́дуйся, на́ша всеусе́рдная Благоді́тельнице, па́ству Ха́рковськую матери́нськи опека́ющая;","ра́дуйся, Цві́те Небе́снаго благоуха́нія, благода́тним ми́ром сердця́ на́ша растворя́ющая.","Ра́дуйся, незри́мая Предста́тельнице, Ти бо воі́стину крі́пость на́ша і спасе́ніє;","ра́дуйся, благоутро́бная і ми́лостивая к челові́ком, болі́зней на́ших наде́жноє ісціле́ніє.","Ра́дуйся, блага́я хлебода́тельнице, дождя́ми ра́нними і по́здніми зе́млю на́шу напоя́ющая;","ра́дуйся, от враг ви́димих і неви́димих, возстаю́щих на ни, нас ізбавля́ющая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим Ті, Всеми́лостивая Влади́чице! Не ві́ми бо, что сотвори́м, єгда́ внеза́пу на́йде на нас стра́шний час сме́рти? На Тя все упова́ніє на́ше возлага́єм, і к Твоє́й святі́й іко́ні, ю́же на утіше́ніє нам дарова́ла єси́, припа́дающе, про́сим: бу́ди ми́лостива к нам грі́шним і не пре́зри моле́ній на́ших, но всели́ в сердця́ на́ша печа́ль по Бо́зі Спаси́телі на́шем, да пла́менною любо́вію зове́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную свіщу́, во мра́ці житія́ су́щим неугаси́мую, зрим святу́ю іко́ну Твою́, Всенепоро́чная, — Твоєго́ милосе́рдія істо́чник, благода́ть всім істоча́ющий, у него́ же мно́зі грі́шници, ка́ющеся, спасе́ніє улучи́ша, і Твої́м хода́тайством Ца́рствіє Небе́сноє обріто́ша. Помози́ і нам, Всеми́лостивая, да Твої́ми Ма́терніми моли́твами с му́дрими ді́вами Ца́рствію Христо́ву приобщі́мся, іді́же веселя́щеся вопіє́м Ті такова́я:","Ра́дуйся, прия́тноє моли́тви кади́ло, за спасе́ніє ми́ра у Престо́ла Святи́я Тро́йці при́сно благоуха́ющая;","ра́дуйся, орга́не моли́тви неумолка́ющия, милосе́рдія Бо́жия ми́ру прося́щая.","Ра́дуйся, равноапо́столов і пропові́дников єва́нгельськия і́стини благода́тноє вдохнове́ніє;","ра́дуйся, ві́рних ієра́рхов Це́ркве Христо́ви пра́вило ві́ри і от скорбе́й ізбавле́ніє.","Ра́дуйся, хра́мов Бо́жиїх усе́рдних строї́телей і ві́рних в них служи́телей любо́вію Христо́вою обогаще́ніє;","ра́дуйся, трудолюби́вих земледі́льцев хлі́бом жи́зні ві́чния насище́ніє.","Ра́дуйся, Боже́ственною красото́ю Си́на Твоєго́ і Бо́га на́шего непреста́нно наслажда́ющаяся;","ра́дуйся, Єго́ же, я́ко Судію́ і Бо́га, о спасе́нії ми́ра неотсту́пно умоля́ющая.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 12","ps":["Благода́ті Твоєя́ земно́є зна́меніє да́ти восхоті́вши, істо́чник чуде́с неісче́тних па́жити Ха́рковстей в іко́ні Твоє́й Озеря́нськой отве́рзла єси́, Влади́чице. В ней же Боже́ственная благода́ть, є́юже Всеви́шній облагода́тствова Тя, зна́менія і чудеса́ ви́ну содіва́єть, душе́вних і тіле́сних неду́гов ісціле́ніє всім с ві́рою притека́ющим подає́ть. Ті́мже і нам благода́ті сея́ по́мощ у Си́на Твоєго́, Пречи́стая, іспроси́, да не поги́бнем лю́ті без покая́нія, но Тобо́ю спаса́ємії, немо́лчно поє́м Єди́ному Світоза́рному Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще любве́ Твоєя́ бе́здну неізрече́нную, ю́же ізлива́єши ро́ду христия́нському, благода́рно припа́дающе, мо́лим Тя, Богоро́дице: я́ко в животі́ сем, та́ко і в стра́шний час сме́рти не оста́ви нас, но ускори́ на по́мощ і, я́ко воі́стину Ма́тер Бо́жия і над всі́ми влади́чествующая, от лю́тих мита́рств і руки́ бісо́вськия ду́ші на́ша ісхити́, і Си́ну Твоєму́ і Бо́гу на́шему спасе́ни приведи́, да я́коже на землі́, та́ко і на небесі́, со всі́ми святи́ми воспіва́єм Ті такови́я похвали́:","Ра́дуйся, щедро́т бе́здно, от нача́ла віко́во во глави́зну на́шего спасе́нія предизбра́нная;","ра́дуйся, істо́чниче любве́ неізрече́нния, Ма́терію ми́лостивою Страстоте́рпцем Голго́фським ми́ру ука́занная.","Ра́дуйся, у Креста́ Си́ну Своєму́ сострада́вшая, і с Ним мир возлюби́вшая;","ра́дуйся, Це́рков Си́на Твоєго́ от всіх зол ізбавля́ющая, род христия́нський возвели́чившая.","Ра́дуйся, цві́те ді́вства неув'яда́ємого, віне́ць всіх доброді́телей в Себі́ спле́тшая;","ра́дуйся, ра́дуго Боже́ственнаго Зна́менія, небе́сния і земни́я у Престо́ла Бо́жия Собо́ю совоку́пльшая.","Ра́дуйся, всесвяти́й бо Лик Твой, благода́тію і жи́знію ди́шущий, я́ко рай Боже́ственний, на Тя взира́ющим;","ра́дуйся, преви́ше Небе́с Превознесе́нная, Отра́до і Утіше́ніє непреста́нно Тя велича́ющим.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 13","ps":["О Преблагослове́нная Ма́ти Христа́ Бо́га на́шего, Це́ркве Небе́сния преди́вноє украше́ніє, земни́я же щит і утвержде́ніє, всем во вся́ких ско́рбіх Ма́тернєє заступле́ніє, і среди́ собла́знов ми́ра сего́ благода́тноє душ на́ших озаре́ніє! Прийми́, Всеми́лостивая, сіє́ убо́гоє моле́ніє на́ше, пред Пречи́стим о́бразом Твої́м Тебі́ приноси́моє, і умоли́ Всеблага́го Бо́га яви́ти ми́лость Свою́ на ни і на наро́ди на́ша, во є́же в си́лі і благода́ті Ду́ха Свята́го вся́коє зло препобіжда́я, ніколи́же в любві́ Бо́жієй не наси́титися, і та́ко чи́стим се́рдцем зді і в бу́дущем ві́ці воспіва́ти святи́х Святі́йшему Сло́ву: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, спасе́ніє на́ше предвозвіща́я, благослове́нную в жена́х пронарече́ Тя, Богоро́дице. Ми же, благове́стнику Бо́га Ви́шняго вне́млюще, ве́лію та́їнству див'я́щеся, ра́дуємся; Тебі́ — зна́меніє Ли́ка Своєго́ Озеря́нськаго нам дарова́вшую — Ма́тер Го́спода на́шего іспові́дуєм, і я́ко Ма́тері милосе́рдія і щедро́т, со благогові́нієм вопіє́м Ті:","Ра́дуйся, свяще́нноє сокро́вище сла́ви Бо́жієй, свіщенося́ще во Свята́я Святи́х сві́тло введе́нная;","ра́дуйся, благоволе́нія Бо́жия предображе́ніє і челові́ков спасе́нія пропові́даніє.","Ра́дуйся, проро́чеських прорече́ній сбитіє́ многоці́нноє, Христа́ всім предвозвести́вшая;","ра́дуйся, о Тебі́ бо Небе́сная вся удиви́шася, зря́ще Ду́ха Свята́го в Тя все́льшася.","Ра́дуйся, Глави́зно на́шего спасе́нія, Трийпоста́сноє єстество́ в Єди́ном Божестві́ ми́ру яви́вшая;","ра́дуйся, Отроча́ Мла́до, О́тчеє Сія́ніє, мир просвіти́вшеє, нам роди́вшая.","Ра́дуйся, Ма́ти Пречи́стая, пре́жде рождества́ і по рождестві́ Ді́ва преби́вшая;","ра́дуйся, я́ко о Рождестві́ Си́на Твоєго́ всі земноро́днії, спаса́ющеся, возвесели́шася.","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, невече́рняго Сві́та Роди́тельнице, Боже́ственноє зна́меніє спасе́нія — Христа́ Богомладе́нця на ру́ку Своє́ю держа́щи, моли́твам Це́ркве земни́я вне́млющей, струї́ животво́рния от явле́нния іко́ни Своєя́ Озеря́нськия всім ві́рним істоча́ющей, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице. Но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́ і щедро́тами Си́на Твоєго́ ду́ші на́ша озари́, да зове́м Ті:","Ра́дуйся, благослове́нная в жена́х Богоро́дице, сві́том любве́ Христо́вой нас озаря́ющая."]},{"h":"Молитва","ps":["О Преблагослове́нная Влади́чице на́ша Богоро́дице! К Тебі́, обре́тшей благода́ть пред Бо́гом, во є́же роди́ти ми́ру Спа́са душ на́ших, с Ним же у Креста́ Єго́ моли́твою за мир сраспина́вшаяся, і Ма́терію Сві́та Їм пронарече́нная, припа́дающе, мо́лимся. При́зри, Всеми́лостивая, на нас, Предві́чним Сові́том Пресвяти́я Тро́йці, к благода́тному наслі́дію жи́зні ві́чния созда́нних, жа́лом же гріхо́вним уя́звленних і сме́рті тіле́сній і душе́вній пове́рженних су́щих, і я́коже святу́ю іко́ну Твою́ Озеря́нськую пречу́дне срасти́вши, всім ві́рним істо́чник чуде́с от нея́ істочи́ла єси́, си́це же і нас, на Твою́, Богома́ти, іко́ну, благогові́йно взира́ющих, душе́вні і тіле́сні ісціли́, і немощно́є єстество́ на́ше, січе́нієм гріхо́вним разсека́ємоє, па́ки с Бо́гом соєдини́, і ча́дами Єго́ Боже́ственния любве́, си́лою і ді́йствієм Свята́го Ду́ха, нас соді́лай. Сердця́ же на́ша, Всеми́лостивая, благода́тію Христо́вою раствори́, і во́лю на́шу к ісполне́нію за́повідей Бо́жиїх спе́шну сотвори́, но́ги же на́ші на путь ми́рен — І́стину Христо́ву напра́ви. І си́це, о Всеблага́я, все єстество́ на́ше любо́вію к Бо́гу воспламени́. Влади́чице Пресвята́я, я́коже в тя́жком наше́ствії іноплеме́нник в преді́ли на́ша свято́ю іко́ною Твоє́ю Озеря́нською Правосла́вния лю́ди укрепля́ла єси́, та́ко і ни́ні зна́менієм Ли́ка сего́ Пресвята́го па́ству Ха́рковськую і всіх ві́рних чад страни́ на́шея в єдиноми́слії ві́ри утверди́, і от тлітво́рних раско́лов і єресе́й злочести́вих і іни́х бід сохрани́, Оте́честву же на́шему нези́блемаго ми́ра от Бо́га іспроси́, і от всіх враг, ми́слящих нам зла́я, нас ізба́ви. Ві́рних же Твої́х, пред свято́ю іко́ною Твоє́ю припа́дающих і в ско́рбіх Тебі́ моля́щихся, проше́нія іспо́лни, і вся, я́же ко спасе́нію потре́бная, всім нам да́руй. Убо́гія же сле́зи і воздиха́нія на́ша благоприя́тни пред Бо́гом сотвори́ і проще́ніє гріхо́в на́ших іспроси́. І та́ко, Преблагослове́нная Ма́ти, воздви́гни нас на благода́рственноє Ті славосло́віє, і в по́двизі покая́нія нас укріпля́ющи, неосужде́нних прича́стников Пречи́стаго Ті́ла і Честни́я Кро́ве Го́спода на́шего Ісу́са Христа́ по кончи́ні житія́ на́шего би́ти нас ми́лостивно сподо́би. В час же ісхо́да на́шего моли́тву Ма́тернюю о нас пред Бо́гом сотвори́, і бі́дния ду́ші на́ша чрез мита́рства лю́тия, нача́ла і вла́сті тьми, невозбра́нно в Ца́рствіє Небе́сноє, іді́же мир і ра́дость безконе́чная, приведи́, — во є́же в Це́ркві Небе́сній, Тобо́ю, Честні́йшею Херуви́м і Сла́внейшею без сравне́нія Серафи́м, укра́шенной, непреста́нно славосло́вити і воспіва́ти сме́рті Побіди́теля — А́гнця Бо́жия, взе́мшаго гріхи́ ми́ра. Єму́ же, о Благода́тная, Тебе́ ра́ди, оса́нна і благодаре́ніє, сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і со Пресвяти́м, Благи́м і Животворя́щим Ду́хом — Уті́шителем Святи́м, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["От суєти́ жите́йськія возни́кше і ума́ своєго́ по́мисли во єди́но собра́вше, ко Твоє́й, Богоро́дице, іко́ні о́чі душ і тіле́с на́ших воздвиза́єм, і Тебі́ взива́єм си́це: не оста́ви, Пречи́стая, нас немощни́х во грісі́х на́ших растлі́тися, не попусти́ зло́му де́мону ду́ші на́ша от Си́на Твоєго́ в де́бри страсте́й отгна́ти, но помози́ нам Того́ за́повіді при́сно па́м'ятовати, да ніже́ блу́дним возбіше́нієм себі́ предає́м, ніже́ друг дру́га зло́бою угриза́єм, но я́коже днесь, святи́ні Твоє́й предстоя́ще, о ісправле́нії житія́ на́шего ре́вностію распаля́ємся, та́ко і от хра́ма Твоєго́ в до́ма своя́ отше́дше, сіє́ до́броє намі́реніє сохрани́ти потщі́мся. По сих же і тіле́сния на́ша ну́жди утоли́, і го́рести Твоє́ю моли́твою ісціли́, Всепі́тая. Ві́ми, я́ко подоба́ше нам па́че вся сія́ благоду́шне претерпіва́ти і то́чію о терпі́нії в ско́рбіх Го́спода проси́ти: но поне́же ізнемога́ють в печа́ліх ду́ші на́ша і по́мисли уни́нія на́шу коле́блють ві́ру, сего́ ра́ди в сокруше́нії серде́ць к Тебі́ си́це взива́єм: я́коже безчи́сленния боля́щия страда́льці ісціли́ла єси́ і скорб'я́щия уті́шила єси́, та́ко і нас пред чудотво́рною Твоє́ю іко́ною припа́дающих і в ско́рбі Тебі́ моля́щихся усли́ши, і всіх проше́нія во благо́є іспо́лни, боля́щим здра́віє, скорб'я́щим утіше́ніє подаю́щи, во вражді́ су́щим мир от Бо́га низпосила́ющи, сомня́щимся же ві́ри утвержде́ніє. Усли́ши грі́шния раби́ Твоя́, Пречи́стая, воздви́гни нас на благода́рственноє Ті славосло́віє, да умно́житься ві́ра люде́й Твої́х, да просла́виться в них Твоє́ заступле́ніє, да та́ко Ца́рствіє Си́на Твоєго́ посреди́ нас утверди́ться. Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і Пресвяти́м і Благи́м і Животворя́щим Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Твоєго́ предста́тельства увіре́ніє / і милосе́рдія Твоєго́ явле́ніє / іко́на Озеря́нськая нам, Влади́чице, показа́ся; / пред не́юже ду́ші на́ша в моли́тві ізлива́єм / і ві́рою Тебі́ вопіє́м: / воззри́, Милосе́рдная, на лю́ди Твоя́, / вся ско́рбі на́ша і печа́лі утоли́, / утіше́ніє благо́є в сердця́ на́ша низпосли́ // і спасе́ніє ві́чноє душа́м на́шим, Пречи́стая, іспроси́."]},{"h":"Кондак, глас 5","ps":["Не отри́ни, о Милосе́рдая Ма́ти, / слез і воздиха́ній на́ших, / но проше́нія на́ша ми́лостивно приї́мши, / пред іко́ною Твоє́ю моля́щихся люде́й ві́ру укріпи́, / умиле́нієм сердця́ їх іспо́лни і крест земна́го житія́ носи́ти їм помози́; // єли́ка бо хо́щеши, мо́жеши."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Розчулення» Серафимо-Дівеєвська (інший акафіст)","e":"Akathist to the Theotokos before her icon “Tenderness” of Seraphim-Diveyevo (another akathist)","secs":[{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в Засту́пнице вселе́нния, похва́льний глас Твої́х рабо́в приє́мши, Всеблаже́нная, ізба́ви нас от вся́ких бід, да пред іко́ною Твоє́ю і ми арха́нгельський приветь поє́м усе́рдною душе́ю:","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Ікос 1","ps":["Арха́нгел Бо́жий Гавриї́л, началово́ждь Небе́сних Сил, предста́ Тебі́, Отрокови́це, Сові́т Преві́чний открива́я і є́же «Ра́дуйся» віща́я: «Ти Ма́ти бу́деши Влади́ці». Тому́ послі́дующе ві́рно, дерза́єм всі нелицемі́рно воспі́ти ра́достний сей глас Тебі́, моля́щейся о нас:","Ра́дуйся, ро́ждшая Жизнь всім утро́бо;","ра́дуйся, грі́шнаго ми́ра спасе́ніє.","Ра́дуйся, Син Твой воскре́се от гро́ба;","ра́дуйся, Є́виних слез ізбавле́ніє.","Ра́дуйся, дре́вняго змі́я попра́вшая;","ра́дуйся, у́зи гріха́ растерзавшая.","Ра́дуйся, ра́дость жена́м несказа́нная;","ра́дуйся, Бо́жия ми́лости двер.","Ра́дуйся, А́нгелов піснь непреста́нная;","ра́дуйся, Бо́гу ізбра́нная Дщер.","Ра́дуйся, тва́рі всея́ ожида́ніє;","ра́дуйся, грі́шником всім упова́ніє.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 2","ps":["Ви́дяще о́браз Твой сей «Умиле́ніє», то́ки ціле́бния всім істоча́ющий, те́плі к нему́ притека́єм смире́ннії, в ну́ждах і ско́рбіх спасе́нія ча́юще. Ти же Христа́ умоли́, я́ко Ма́ти, вся́ко проше́ніє нам дарова́ти, я́ко да при́сно Тому́ воспої́м піснь благода́рну пред о́бразом сим: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний стяжа́ Серафи́м, тя́жким неду́гом лежа́ одержи́м; Тя бо моля́ше болі́знь ісціли́ти. Ти же, Блага́я, прише́дши во сні, кро́тці предста́ла єму́ в тишині́, о́троку жизнь обіща́вши продлити. Ті́мже, от сме́рти Тобо́ю спасе́нний, сла́дці воспі́ Серафи́м умиле́нний:","Ра́дуйся, ви́сшая не́ба небе́с;","ра́дуйся, Ма́ти Госпо́дня свята́я.","Ра́дуйся, ро́ждшая Бе́здну чуде́с;","ра́дуйся, ста́мно щедро́т всезлата́я.","Ра́дуйся, Ти бо нам ми́лость явля́єши;","ра́дуйся, вся́ку болі́знь ісціля́єши.","Ра́дуйся, душ і тіле́с врачевство́;","ра́дуйся, па́дших благо́є возста́ніє.","Ра́дуйся, го́рніх умо́в торжество́;","ра́дуйся, грі́шников к Не́бу воззва́ніє.","Ра́дуйся, Бо́га за нас умоля́єши;","ра́дуйся, вра́жию сіть сокруша́єши.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго ди́вно храни́м, в си́лу от си́ли в душе́ преспіва́ше в ю́ності чи́стій святи́й Серафи́м. В храм Пресвяти́я усе́рдно хожда́ше і, умиле́нно моли́тву творя́, се́рдцем хвалу́ во псалмі́х воспису́я, Бо́га Всеще́драго благодаря́, при́сно поя́ше Єму́ Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я Тя Спу́тницю ві́рную в жи́зні, оста́ви ізбра́нник Твой ю́ний отчи́зну, в оби́тель Саро́вськую путь направля́я. Слага́я бо в се́рдці Твоя́ словеса́, оте́чество мня́ше своє́ Небеса́, пусти́нних живо́т на землі́ ублажа́я. І, сли́шав: «От на́шего ро́да єсть сей», Тебі́ воспіва́ше, наде́жде своє́й:","Ра́дуйся, ві́ри звіздо́ путево́дная;","ра́дуйся, Ко́рмчая жи́зні моє́й.","Ра́дуйся, Спутнице, к Бо́гу доходная;","ра́дуйся, кро́ве от бу́рі страсте́й.","Ра́дуйся, к Бо́гу бо нас управля́єши;","ра́дуйся, ду́шу спасти́ вразумля́єши.","Ра́дуйся, пра́вди стезе́ незаблудная;","ра́дуйся, мо́сте, го́ре возводя́й.","Ра́дуйся, ни́щим Помо́щнице чу́дная;","ра́дуйся, ві́нче, се́рдця веселяй.","Ра́дуйся, в Ца́рствіє нас призива́єши;","ра́дуйся, две́рі рая́ отверза́єши.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 4","ps":["Бу́ри жите́йськія ско́ро спаса́єть Бо́жия Ма́ти вдови́цю блаже́нную, жре́бій вручи́ти єй Свой обіща́єть, зе́млю возделати благослове́нную. Ті́мже, Пречи́стия во́лі послу́шна, в путь неізвестний отхо́дить вдови́ця, претерпіва́ющи вся благоду́шно, до́ндеже в жре́бій святи́й водвори́ться, Ді́ви глаго́ла в терпі́нії ждущи, Бо́гу же Си́ну прилі́жно пою́щи: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша вдови́ця глаго́л долгожда́нний, в тонцем дреманії єй провещанний: «Зді єсть в Дивеєві мі́сто Моє́, зді єсть Мой жре́бій четве́ртий ізбра́нний, зді ти положи́ши ко́сті твоя́, ді́вам приста́нище пре́жде созда́вши». Ті́мже вдови́ця, от ло́жа воста́вши, Ма́тері Сві́та за ра́дость святу́ю сві́тло поє́ть похвалу́ такову́ю:","Ра́дуйся, Сві́та оби́тель блаже́нная;","ра́дуйся, Бо́гом ізбра́нний уді́л.","Ра́дуйся, ски́ніє Бо́га свяще́нная;","ра́дуйся, до́брих сокро́вище діл.","Ра́дуйся, ми́лости мо́ре безбрежноє;","ра́дуйся, душ тишино́ безм'яте́жная.","Ра́дуйся, вдов к чистоті́ окормле́ніє;","ра́дуйся, ді́вства сосу́де драги́й.","Ра́дуйся, в ста́рости сил укріпле́ніє;","ра́дуйся, в ю́ності же́зле благи́й.","Ра́дуйся, Ді́во Марі́є нетлі́нная;","ра́дуйся, Господом благослове́нная.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 5","ps":["Бо́жия Ма́тере гла́су внима́ющи, храм Єя́ і́мені вдова́ созида́єть; ма́лоє ста́до сиро́т собира́ющи, во благоче́стії тіх возраща́єть. Та́ко в Дивеєві Бо́жиє сі́м'я в до́брую зе́млю вложи́ся во вре́м'я, плод же в терпі́нії свой принесе́, я́ко да ми от плода́ днесь вкуша́юще, Ма́тер Благу́ю Творця́ небесе́ благодари́м, о Ней піснь воспіва́юще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши первоначальниця ма́ти, я́ко оби́тель нача́ть возраста́ти, Ді́ви Марі́ї слове́с в ісполне́ніє, ма́лоє ста́до своє́ поручаєть ста́рцем Саро́вським і му́дро ввіря́єть па́стви духо́вноє все окормле́ніє. І, преспіва́ющи в жи́зні своє́й, благодаря́щи істо́чник чуде́с, Ді́ву Марі́ю, за по́мощ с Небе́с, пі́сні слага́єть похва́льния Єй:","Ра́дуйся, ти́хая на́ша отра́до;","ра́дуйся, і́м'я Тебі́ Умиле́ніє.","Ра́дуйся, Ма́ти слове́снаго стада́;","ра́дуйся, мі́ста сего́ прославле́ніє.","Ра́дуйся, нам бо покро́в простира́єши;","ра́дуйся, нас ко Христу́ собира́єши.","Ра́дуйся, ді́вам Ти сві́тлий черто́г;","ра́дуйся, си́рих от бід огражда́єши.","Ра́дуйся, Тя бо послу́шаєть Бог;","ра́дуйся, пла́чущих всіх утіше́ніє.","Ра́дуйся, не́мощі на́ша терп'ящая;","ра́дуйся, нас во благи́х богатя́щая.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 6","ps":["Бисть пропові́дниця ми́лостей всіх в своє́м житії́ Алекса́ндра честна́я. Бо́жиє І́м'я всегда́ во усті́х, в се́рдці і ми́слі моли́тва свята́я. Сле́зния то́ки Тебі́ приноша́ше, Тя, Живоно́сний Істо́чниче, чту́щи, труд же дневни́й неуста́нно творя́ше, ду́хом горя́щи і Бо́гу пою́щи: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсіява́ющи світ благода́ті в дивном Дивеєве, Бо́жия Ма́ти Свой омофо́р простира́єть над ним, ко́зні врага́ і наві́ти людські́я, не́мощі ду́ха і стра́сті плотські́я, ну́жди, оби́чния лю́дем земни́м, — вся утоля́єть Цари́ця блага́я, ско́ро Свої́м сирота́м помога́єть. Ті́мже, пою́ще Тоя́ чудеса́, ра́достно рцем Єй сія́ словеса́:","Ра́дуйся, сві́те спасе́нія бла́гостний;","ра́дуйся, чи́стих серде́ць красото́.","Ра́дуйся, со́вісти ми́рі, всім сла́достний;","ра́дуйся, ду́ха любве́ широто́.","Ра́дуйся, цвітни́че благоуха́ющий;","ра́дуйся, же́зле, враги́ устраша́ющий.","Ра́дуйся, в не́мощі по́мощ всеси́льная;","ра́дуйся, в ско́рбі уті́хо с Небе́с.","Ра́дуйся, в ску́дости пи́ще оби́льная;","ра́дуйся, ви́шшая вся́ких слове́с.","Ра́дуйся, Бо́жий бо гнів утоля́єши;","ра́дуйся, ми́лость на нас призива́єши.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 7","ps":["Хотя́щи оста́вити мир сей растлі́нний, блаже́нная вку́пі сиро́т собира́єть і Ма́тере Бо́га уді́л, єй вруче́нний, Пахо́мія ста́рця блюсти́ умоля́єть; Пречи́стия о́браз на пе́рси приє́млеть і в ру́ці Влади́чиці дух предає́ть. Іспо́лненний ско́рби Пахо́мій єй вне́млеть і піснь єй надгро́бную си́це поє́ть: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий Дивеєву А́нгел храни́тель, жре́бія Ді́ви і дів устрої́тель, по́слан Пречи́стою бисть Серафи́м. Ку́пно с прехва́льним Петро́м, с Іоа́нном, в ке́ллії Ді́ва предста́ несказа́нно, сві́тлая, с му́чениць лико́м святи́м, благоуха́ющи ми́ром небе́сним. «Дів ти Мої́х не оста́ви», — віща́єть, по́мощ єму́ по вся дні обіща́єть, он же прино́сить Єй дар свой слове́сний:","Ра́дуйся, сла́во проро́ков прекра́сная;","ра́дуйся, кри́не удо́лій рая́.","Ра́дуйся, му́чениць піснь велегла́сная;","ра́дуйся, стершая сле́зи моя́.","Ра́дуйся, грі́шних моли́тв не забившая;","ра́дуйся, си́рих Твої́х посіти́вшая.","Ра́дуйся, на́ша пред Сино́м Спору́чнице;","ра́дуйся, с Бо́гом прине́сшая мир.","Ра́дуйся, душ Женихових Обру́чниці;","ра́дуйся, Две́рниці зва́нним на пир.","Ра́дуйся, та́йни от ві́ка явле́ніє;","ра́дуйся, Ді́во, Тебе́ моє́ пі́ніє.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 8","ps":["Стра́нних виді́ній прича́стник блаже́нний, бла́гостний ста́рець оте́ць Серафи́м к се́рдцю приє́млеть заві́т незабве́нний Ді́ви Марі́ї і, Є́ю води́м, ді́вам оби́тель особую стро́їть; мі́ру собо́рному хра́му дає́ть, мі́сто свято́є канавкой обво́дить, па́ству Пречи́стия ві́рно пасе́ть, пра́вило жи́зні і чин полага́єть, Бо́гу нелі́ностно пі́ти внуша́єть: Аллилу́я."]},{"h":"Ікос 8","ps":["Всеці́лим умо́м ся Христу́ сраспиная, блаже́нства рая́ на землі́ предвкушая, поя́ше святи́й, я́ко благ тіх вино́вній, Марі́ї, роди́вшей нам Спа́сшаго нас, арха́нгельський Той, є́же «Ра́дуйся», глас прилі́жно всегда́ с простото́ю синовней. Тому́ подража́я, Марі́їн уді́л дони́ні обхо́дить свой дре́вній преді́л, хвалу́ Богоро́дице Ді́ві поя́, да ра́дости бу́деть прича́стник Тоя́:","Ра́дуйся, о Богоро́дице Ді́во;","ра́дуйся, ро́ждшая Спа́са Христа́.","Ра́дуйся, Бо́га вмісти́вшая в чре́во;","ра́дуйся, плод Твой нам Путь живота́.","Ра́дуйся, ра́достей ві́чних вино́вная;","ра́дуйся, сла́во і ра́дость церко́вная.","Ра́дуйся, ді́вственниць чи́стих вінча́ніє;","ра́дуйся, і́ноков ще́драя Ма́ти.","Ра́дуйся, ма́терей всіх велича́ніє;","ра́дуйся, до́ме, іспо́лнь благода́ті.","Ра́дуйся, стрі́ли во дні угаша́ющи;","ра́дуйся, стра́хи в нощі́ прогоня́ющи.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 9","ps":["Вся́ких Сил а́нгельських, Ді́во, превисшую, хва́лять немо́лчно Тя на́ша се́рдця, сві́тлостей со́лнечних і́стинно чи́стшую, Тя велича́єть вся твар без конця́. Ти же Хода́тайця за нас бу́ди к Си́ну і Бо́гу в день стра́шний Суда́; грі́шних моле́ній тогда́ не забу́ди, пі́ти сподо́би нас Бо́гу всегда́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й многогласних не мо́жеть язи́к воспі́ти досто́йно Твой сла́достний лик, о Ді́во і Ма́ти Влади́ки Небе́с. Даро́в Твої́х чу́дних і сил умноже́ніє се́рдця ісполня́єть роси́ умиле́нія, дає́ть очесе́м всіх істо́чники слез. Твой о́браз святи́й со свіще́ю горя́щею всегда́ веселя́ше взор ста́рця моля́щаго, єгда́ на колі́на склонився пред ним, усе́рдно хваля́ше Тя пі́нієм сим:","Ра́дуйся, всіх безнаде́жних наде́ждо;","ра́дуйся, се́рдцю росо́ умиле́нія.","Ра́дуйся, пра́вди лише́нних оде́ждо;","ра́дуйся, всім нам істо́чник спасе́нія.","Ра́дуйся, де́монський лик низлагаєши;","ра́дуйся, гро́зно бісо́м запреща́єши.","Ра́дуйся, ду́хом уни́лих возста́ніє;","ра́дуйся, па́лице спящим во злі.","Ра́дуйся, стро́потних душ наказа́ніє;","ра́дуйся, вся бо возмо́жна Тебі́.","Ра́дуйся, в го́рких рабо́тах всім сла́дость;","ра́дуйся, Ма́ти, скорб'я́щим всім ра́дость.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 10","ps":["Спаси́тельно по́стними сі́яв слеза́ми, жнеть в ра́дості ста́рець от Ді́ви віща́ніє: «Ти ско́ро, люби́миче, бу́деши с на́ми». І ду́хом покоєн, в живо́м упова́нії, отход свой от ми́ра предуготовля́єть. Уста́в свой моли́твенний і наставле́нія храни́ти сиро́т свої́х он поуча́єть: «От днесь вам Блага́я єди́на хране́ніє; ви мно́гія пі́стуни і́мате, ча́да, оте́ць же не бу́деть ра́зві мене́, на гро́бі моє́м іщі́те отра́ди, і в ну́ждах і в ско́рбіх іді́те ко мні; і ві́рую, дасть вам Госпо́дь утіше́ніє, да при́сно восхо́дить от вас Єму́ пі́ніє: Аллилу́я»."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Пречи́стая Ді́во, от вра́жиїх ко́зней, от ну́жди і гні́ва, Тебі́ бо вручи́ нас святи́й Серафи́м. І в час іспита́нія дух наш см'ятенний к Тебі́ ми возноси́м в моли́тві смире́нній: о, бу́ди Помо́щниця си́рим Твої́м, да ве́село хва́лим Тя, Присноблаже́нную, всеми́рную сла́ву, хвалу́ неізмі́нную:","Ра́дуйся, ві́рних Твої́х утвержде́ніє;","ра́дуйся, крі́пкая си́рих стіно́.","Ра́дуйся, Це́ркве святи́я хвале́ніє;","ра́дуйся, го́рнім умо́м глубино́.","Ра́дуйся, цві́те наш неув'яда́ємий;","ра́дуйся, гра́де Царя́ прославля́ємий.","Ра́дуйся, лі́ствице, к Бо́гу возве́дшая;","ра́дуйся, о́блаче ле́гкий Христо́в.","Ра́дуйся, ро́су руно́ проізведшеє;","ра́дуйся, всім Ти гото́вий покро́в.","Ра́дуйся, на́ша наде́ждо ізві́стная;","ра́дуйся, дів похвало́ неневі́стная.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє днесь побіжда́ється мно́жеством благодія́ній Твої́х; ми́лость Твоя́ на весь мир простира́ється, сла́во небе́сних і ра́дость земни́х. Гла́са бо Ма́тере богоприя́тнаго Син Твой послу́шаєть, Ді́во, всегда́. Ра́дость всім ра́достем Ти, Благода́тная, — зва́ти ми не умолчи́м нікогда́. Та́ко бо зва́ше Тебі́ преподо́бний, Бо́гу поя́, наш предста́тель загробний: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́та откри́ся черто́г вожделі́нний ста́рцю, в моли́тві к Тебі́ восхище́нну, Ді́во, пред о́бразом сим «Умиле́ніє». В ру́ці пречи́стії ду́шу святу́ю Ти восприя́ла єси́ во іну́ю жизнь безконе́чную в ра́йських селе́ніях. Пла́каху ча́да, отця́ їх лише́нная, но́вим же зна́нієм умиле́нная ми́лости к ста́рцю Твоє́й, растворяюще сле́зи надгро́бния пі́снею кра́сною, Тя велича́ху хвало́ю согласною, Ма́тер єди́ну Тебі́ разсмотря́юще:","Ра́дуйся, те́мния вла́сті стена́ніє;","ра́дуйся, пра́ведних душ торжество́.","Ра́дуйся, вратников а́да рида́ніє;","ра́дуйся, Тя бо поє́ть єстество́.","Ра́дуйся, кня́зя мита́рств низложи́вшая;","ра́дуйся, де́монов го́рдость смири́вшая.","Ра́дуйся, і́м'я, святи́м вожделі́нноє;","ра́дуйся, в сме́ртний Помо́щнице час.","Ра́дуйся, ра́дость нам неізрече́нная;","ра́дуйся, в час той усли́ши наш глас.","Ра́дуйся, на́ших серде́ць умиле́ніє;","ра́дуйся, Бо́га умилостивле́ніє.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 12","ps":["Благода́тний зало́г в огражде́ніє, ча́дом дивеєвським ста́рець оста́ви о́браз Пречи́стия сей «Умиле́ніє». Сам же пресві́тло лику́я во сла́ві, Ма́тер Небе́сную мо́лить усе́рдно си́рих єго́ соблюсти́ милосе́рдно, да не воздре́млють уни́нія сном, но да єле́єм свіщу́ напоя́юще, вни́дуть в черто́г со свої́м Женихо́м, ві́чную А́нгелов піснь воспеваюше: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м днесь Твою́, Богоро́дице, сла́ву і ми́лость ко грі́шним, на бі́си держа́ву; всі пра́зднуєм сві́тло Твоя́ чудеса́. Безмі́рно Тя всю освяти́в, Непоро́чная, Бог лю́дем поста́ви Тя в крі́пость всемо́щную: Тебі́ бо внима́ють Того́ ушеса́. Тобо́ю спаса́ємі всі єжеча́сно, прино́сим Ті піснь такову́ю согла́сно:","Ра́дуйся, жи́зні сокро́вище ві́чния;","ра́дуйся, пра́вди ковче́же святи́й.","Ра́дуйся, лю́дем хвало́ безконе́чная;","ра́дуйся, сві́щниче ві́ри злати́й.","Ра́дуйся, Бо́жиє благоволе́ніє;","ра́дуйся, всіх челові́ков спасе́ніє.","Ра́дуйся, му́ченик всіх дерзнове́ніє;","ра́дуйся, піснь преподо́бних Твої́х.","Ра́дуйся, пра́ведних жен украше́ніє;","ра́дуйся, кра́ю жела́ній благи́х.","Ра́дуйся, це́ркве хору́гв пречестна́я;","ра́дуйся, грі́шним нам Ма́ти блага́я.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 13","ps":["О Ма́ти Всепі́тая, всем во спасе́ніє даждь, Всеблага́я, серде́ць умиле́ніє, да Бо́жиїм стра́хом всегда́ огражда́єми, ізбі́гнем губи́тельних сіте́й борця́, і та́ко Твої́ми мольба́ми спаса́ємі, во ві́ки восхва́лим блага́го Творця́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Бо́жий Гавриї́л, началово́ждь Небе́сних Сил, предста́ Тебі́, Отрокови́це, Сові́т Преві́чний открива́я і є́же «Ра́дуйся» віща́я: «Ти Ма́ти бу́деши Влади́ці». Тому́ послі́дующе ві́рно, дерза́єм всі нелицемі́рно воспі́ти ра́достний сей глас Тебі́, моля́щейся о нас:","Ра́дуйся, ро́ждшая Жизнь всім утро́бо;","ра́дуйся, грі́шнаго ми́ра спасе́ніє.","Ра́дуйся, Син Твой воскре́се от гро́ба;","ра́дуйся, Є́виних слез ізбавле́ніє.","Ра́дуйся, дре́вняго змі́я попра́вшая;","ра́дуйся, у́зи гріха́ растерзавшая.","Ра́дуйся, ра́дость жена́м несказа́нная;","ра́дуйся, Бо́жия ми́лости двер.","Ра́дуйся, А́нгелов піснь непреста́нная;","ра́дуйся, Бо́гу ізбра́нная Дщер.","Ра́дуйся, тва́рі всея́ ожида́ніє;","ра́дуйся, грі́шником всім упова́ніє.","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в Засту́пнице вселе́нния, похва́льний глас Твої́х рабо́в приє́мши, Всеблаже́нная, ізба́ви нас от вся́ких бід, да пред іко́ною Твоє́ю і ми арха́нгельський приветь поє́м усе́рдною душе́ю:","Ра́дуйся, всім ра́достем Ти єси́ ра́дость, Всеблаже́нная."]},{"h":"Молитва","ps":["О Пресвята́я Влади́чице, Богоро́дице Ді́во! Прийми́ недосто́йния моли́тви на́ша, сохрани́ нас от наві́тов злих челові́к і от напра́сния сме́рті, пода́ждь нам пре́жде конця́ покая́ніє, на моле́нія на́ша умилосе́рдися і ра́дость вмі́сто печа́лі да́руй. І ізба́ви нас, о Госпоже́ Влади́чице Богоро́дице, от вся́кия біди́, напа́сти, ско́рби, болі́зні і вся́каго зла, і сподо́би нас, грі́шних рабо́в Твої́х, одесну́ю ста́ти во второ́м прише́ствії Си́на Твоєго́, Христа́ Бо́га на́шего, і наслі́дники нас би́ти сподо́би Ца́рствія Небе́снаго і жи́зні ві́чния со всі́ми святи́ми в бесконечния ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К Богоро́диці с умиле́нієм припаде́м, / всі, гріхми́ обремене́ннії, / чудотво́рную Єя́ іко́ну Умиле́нія облобиза́юще / і вопію́ще со слеза́ми: / Влади́чице, прийми́ моле́ніє недосто́йних раб Твої́х / і пода́ждь нам, прося́щим, // ве́лію Твою́ ми́лость."]},{"h":"Кондак, глас 3","ps":["Ю́же подража́я непло́дную смоко́вницю, / аз, окая́нний, умиле́нія плода́ отню́д не приношу́ і посіче́нія страшу́ся, / но, взира́я к чудотво́рній іко́ні Твоє́й Умиле́нія, Влади́чице, / стеню́ от се́рдця і вопію́: / умили́ся, Благосе́рдая, / і мні, окамене́нному се́рдцем, // благоволи́ пода́ти душе́вноє і серде́чноє умиле́ніє."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконами «Взискання погибших» і «Всіх скорботних Радість»","e":"Akathist to the Theotokos before her icons “Seeker of the Lost” and “Joy of All Who Sorrow”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді побіди́тельная, я́ко ізба́вльшеся от ві́чния сме́рти благода́тію от Тебе́ ро́ждшагося Христа́ Бо́га на́шего і Твої́м Ма́тернім пред Ним хода́тайством, благода́рственная воспису́єм Ті, раби́ Твої́, но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід і ско́рбних обстоя́ній свободи́, зову́щих:","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть с Небесе́ рещи́ Богоро́дице: ра́дуйся, Благослове́нная в жена́х, предрече́нная Ма́ти Христа́, Си́на Бо́жия. Ті́мже і ми, гріхми́ обремене́ннії, наде́жду спасе́нія в Тебі́ улучи́вше, уми́льно взива́єм Ті:","Ра́дуйся, Бо́жиє ко грі́шним благоволе́ніє;","ра́дуйся, ка́ющихся пред Го́сподем Бо́гом крі́пкоє заступле́ніє.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, гріхо́вную от'ємлющая скве́рну;","ра́дуйся, ба́не, омива́ющая со́вість.","Ра́дуйся, ро́ждшая Ізба́вителя, беззако́нія на́ша ми́лостиво очища́ющаго;","ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє.","Ра́дуйся, мо́сте, воі́стину преводя́й нас от сме́рти к животу́;","ра́дуйся, мир от пото́па гріхо́внаго спа́сшая.","Ра́дуйся, лі́ствице небе́сная, Є́юже Госпо́дь к нам сни́де;","ра́дуйся, вина́ всіх обоже́нія.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 2","ps":["Ви́дяще то́ки чуде́с, ізлива́ємия от святи́я Твоєя́ іко́ни, Блага́я Богороди́тельнице, і разумі́юще, я́ко Ти єси́ моля́щихся Блага́я Помо́щниця, оби́димих Засту́пниця, ненаді́ющихся наде́жда, печа́льних утіше́ніє, поги́бших Взиска́ніє, а́лчущих Корми́тельниця, наги́х одія́ніє, ді́вственних целому́дріє, стра́нних Наста́вниця, тружда́ющихся по́мощ, сліпи́х прозрі́ніє, глухи́х благосли́шаніє, больни́х ісціле́ніє, благода́рственні вопіє́м о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Та́йну Твоєго́, Богоро́дице, заступле́нія люде́й, в ско́рбі погиба́ющих, уразумі́ти хотя́ще, к Тебі́ прибіга́єм, о Ма́ти і Ді́во. Ти же, я́ко Блага́я, научи́ ни разумі́ти в защище́нії Блага́го Си́на Твоєго́ милосе́рдоє промишле́ніє о спасе́нії душ на́ших і очище́ніє мно́гих согріше́ній, да взива́єм Ті ра́достно:","Ра́дуйся, обурева́ємих ти́хоє приста́нище;","ра́дуйся, сумнящихся ізві́стноє утвержде́ніє.","Ра́дуйся, Єди́на Ма́ти милосе́рдія;","ра́дуйся, ско́рая Помо́щнице су́щим в біда́х і напа́стіх.","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая;","ра́дуйся, печа́лію на́ша не́мощі душе́вния врачу́ющая.","Ра́дуйся, су́єтния ра́дости презира́ти нас науча́ющая;","ра́дуйся, к ви́шнему ми́ру ум наш возводя́щая.","Ра́дуйся, от любве́ земни́я к Небе́сній Бо́жієй любві́ нас привлекающая;","ра́дуйся, в са́мих страда́ніїх на́ших утіше́ніє і благода́тную жизнь нам подаю́щая.","Ра́дуйся, обітова́ніє благ ві́чних;","ра́дуйся, Хода́тайце ві́чния ра́дости.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 3","ps":["Си́лою сви́ше укріпи́ м'я, Блага́я Влади́чице, неду́гующа ті́лом і душе́ю, і посіще́нія Твоєго́ сподо́би і промишле́нія, мрак уни́нія і ско́рби, облежа́щий м'я, отгоня́ющи, да, спаса́ємий Тобо́ю, при́сно воспою́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи бога́тство милосе́рдія неізрече́нноє, всім скорб'я́щим ру́ку по́мощі простира́єши, неду́ги врачу́ющи, стра́сті ісціля́ющи. Не пре́зри і мене́, Блага́я Влади́чице, на одрі́ не́мощі моєя́ низлежаща і вопію́ща Ті:","Ра́дуйся, ми́лости сокро́вище многоці́нноє;","ра́дуйся, отча́янних єди́на наде́ждо.","Ра́дуйся, ті́ла моєго́ врачева́ніє;","ра́дуйся, душі́ моєя́ спасе́ніє.","Ра́дуйся, тве́рдая крі́посте немощни́х;","ра́дуйся, ізнемога́ющих Засту́пнице і укріпле́ніє.","Ра́дуйся, гнів Бо́жий Твої́м моле́нієм ско́ро утоля́ющая;","ра́дуйся, стра́сті на́ша си́лою моли́тв Твої́х укроща́ющая.","Ра́дуйся, сліпи́х зрі́ніє, глухи́х сли́шаніє;","ра́дуйся, хроми́х хожде́ніє, німи́х глаго́ланіє.","Ра́дуйся, боля́щих благонаде́жноє посіще́ніє;","ра́дуйся, я́ко Тобо́ю, по мі́рі ві́ри, подаю́ться благода́тная ісціле́нія всім немощствующим.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 4","ps":["Бу́ря мно́гих бід і напа́стей обдержи́ть м'я, і волне́нія уже́ не терплю́. Ти же, я́ко Ми́лостивая Ма́ти Спа́са моєго́ і Бо́га, воздви́гни ру́ці к Си́ну Твоєму́, моля́щи Єго́, да при́зрить на лю́тую скорб се́рдця моєго́ і воздви́гнеть м'я із пучи́ни отча́янія, вопію́щаго Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шащи, Пресвята́я Ді́во і Ма́ти, Симео́на пра́веднаго прорече́ніє: «Тебі́ же Само́й ду́шу про́йдеть ору́жіє», - слага́ла єси́ в се́рдці Твоє́м вся глаго́ли сія́, разуміва́ющи, я́ко ра́дость ма́терняго се́рдця о ча́діх мно́гих печа́лей в ми́рі сем прича́стна. Ті́мже, я́ко іскушенней по вся́чеським і спострада́ти ма́терней ско́рби могу́щей, взива́єм Ті:","Ра́дуйся, ра́дость ми́ру, Христа́ Спаси́теля, ро́ждшая;","ра́дуйся, мир от скорбе́й ізбавля́ющая.","Ра́дуйся, поноше́ніє Си́на Твоєго́ терпевшая;","ра́дуйся, страда́нієм Єго́ спострада́вшая.","Ра́дуйся, ско́рбних ма́терей утіше́ніє;","ра́дуйся, чад їх благода́тноє охране́ніє.","Ра́дуйся, в біда́х ско́роє нам заступле́ніє;","ра́дуйся, заблу́ждших ісправле́ніє.","Ра́дуйся, младе́нцев пита́ніє;","ра́дуйся, ю́них наставле́ніє.","Ра́дуйся, Ма́ти сиро́тствующих;","ра́дуйся, вдов заступле́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 5","ps":["Богото́чную Кров Си́на Твоєго́ на Кресті́ за спасе́ніє на́ше ізлива́ємую зря́щи, я́ко Раба́ Госпо́дня, повину́ющися во́лі Отця́, І́же на Небесі́х, нам о́браз злострада́нія і терпі́нія яви́ла єси́, да і ми, в пе́щі іскуше́ній і бід су́щії, вопіє́м смире́нно Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя Тя Син Твой і Бог, при Кресті́ стоя́щую с возлю́бленним ученико́м і се́рдцем Єму́ сраспинающуюся, глаго́ла: «Же́но, се син Твой», і ученику́: «Се, Ма́ти твоя́», всиновля́я Тебі́ вся верующия в Него́. Ми же, я́ко о́бщници ско́рби і страда́ній Си́на Твоєго́, імі́юще в Тебі́ Благу́ю Ма́тер, на Тя все упова́ніє в ско́рбі возлага́юще, вопіє́м Ті:","Ра́дуйся, Ма́ти ро́да христия́нськаго;","ра́дуйся, усинови́вшая нас при Кресті́ Си́на Твоєго́.","Ра́дуйся, Бо́га с челові́ки соєдини́вшая;","ра́дуйся, ві́рних Го́сподеві сочета́вшая.","Ра́дуйся, А́гнице, ро́ждшая А́гнця, взе́мшаго гріхи́ ми́ра;","ра́дуйся, ча́ше, че́рплющая нам ра́дость от Істо́чника безсме́ртія.","Ра́дуйся, Спору́чнице спасе́нія грі́шних;","ра́дуйся, Взиска́ніє поги́бших.","Ра́дуйся, неча́янная грі́шних Ра́досте;","ра́дуйся, па́дших возста́ніє.","Ра́дуйся, Ціли́тельнице всіх не́мощей;","ра́дуйся, утоле́ніє вся́кия печа́лі.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 6","ps":["Пропові́дують ми́лості Твоя́, Богома́ти, всі конці́ вселе́нния, і́бо честни́м покро́вом Твої́м покрива́єши весь род христия́нський, о не́мже при́сно мо́лишися Христу́ Спаси́телю на́шему і ізбавля́єши от всіх бід благонра́вния і богобоящіяся лю́ди Твоя́, ві́рно вопію́щия Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ благода́ть світоза́рная от пречу́дния іко́ни Твоєя́, Богома́ти, пред не́юже со слеза́ми припа́дающе, мо́лим Ті ся: отжени́ о́блак наше́дших на ни іскуше́ній, да вопіє́м Ті ра́достно:","Ра́дуйся, принося́щая к Си́ну Твоєму́ і Бо́гу моле́нія ві́рних;","ра́дуйся, і Сама́ у Престо́ла Си́на Твоєго́ при́сно моля́щаяся о нас.","Ра́дуйся, Предста́тельнице к Бо́гу, мир от бід спаса́ющая;","ра́дуйся, Засту́пнице ро́да христия́нськаго, от Бо́га нам дарова́нная.","Ра́дуйся, дре́во благосінноли́ственноє, і́мже покрива́ються мно́зі;","ра́дуйся, дре́во світлоплодови́тоє, і́мже пита́ються ві́рнії.","Ра́дуйся, покро́ве ми́ру, ши́рший о́блака;","ра́дуйся, земле́ обітова́нія, із нея́же тече́ть мед і млеко́.","Ра́дуйся, ни́во, растя́щая оби́ліє щедро́т;","ра́дуйся, Пода́тельнице вся́кия бла́гости.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 7","ps":["Хотя́щи яви́ти то́ки чуде́с от святи́я іко́ни Твоєя́ «Взиска́ніє поги́бших», повелі́ла єси́, Влади́чице, в поги́белі і печа́лі су́щим моле́бная пі́нія пред то́ю соверша́ти і получившим ісціле́ніє пропові́дати ми́лости, ра́ди тоя́ іко́ни явле́нния, да не сокри́т бу́деть істо́чник благода́тних врачева́ній всім тре́бующим. Ті́мже і ми не таї́м Твої́х благодія́ній, но, благода́рственні прославля́юще Бо́га, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая купі́ль Силоа́мськая па́че о́ния дре́внія яви́ся, Пречи́стая Влади́чице, храм Твой, в не́мже поклоня́ємся чудотво́рній іко́ні Твоє́й, і́бо не єди́ною в лі́то і то́кмо пе́рвіє входящим здра́віє ті́лом подає́ши, но вся́кий неду́г і вся́кую я́зву душе́вную і тіле́сную врачу́єши с ві́рою і любо́вію к Тебі́ прибіга́ющих. Сего́ ра́ди вопіє́м Ті:","Ра́дуйся, купеле, в ню́же вся ско́рбі на́ша погружа́ються;","ра́дуйся, ча́ше, є́юже ра́дость і спасе́ніє восприє́млем.","Ра́дуйся, ка́меню, напоя́ющий жаждующия жи́зні;","ра́дуйся, дре́во, услажда́ющеє сла́ния води́ жите́йськаго мо́ря.","Ра́дуйся, животво́рния води́ неістощи́мий Істо́чниче;","ра́дуйся, ба́не, омива́ющая гріхо́вную скве́рну.","Ра́дуйся, скорбе́й на́ших услажде́ніє;","ра́дуйся, печа́лей на́ших утоле́ніє.","Ра́дуйся, де́монов попра́ніє;","ра́дуйся, враго́в посрамле́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 8","ps":["Стра́нники і прише́льці всі єсьми́ на землі́ сей, по глаго́лу апо́столову, біди́ от враго́в, біди́ от сро́дник, біди́ от лжебра́тії терп'я́ще в лише́ніїх мно́гих і ско́рбіх. Ти же, Влади́чице, я́ко Блага́я Путеводи́тельниця, наста́ви нас к ти́хому приста́нищу і моли́ Си́на Твоєго́ проще́нію прегріше́ній нам пре́жде конця́ дарова́тися, да при́сно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все житіє́ на́ше на землі́ болі́зненно і печа́лі іспо́лнено от клевети́, досажде́нія, укоре́нія і іни́х многови́дних бід і напа́стей, немощству́єть бо ті́ло, ізнемога́єть і дух наш. К Тебі́ у́бо прибіга́єм, Богома́ти, пред пречи́стою іко́ною Твоє́ю припа́дающе, іспо́лни ра́дости і весе́лія ско́рбная се́рдця на́ша, да вопіє́м Ті:","Ра́дуйся, Путеводи́тельнице, к Небе́сному оте́честву нас руководящая;","ра́дуйся, Цари́це Не́ба і землі́, врата́ ра́йськая нам отверза́ющая.","Ра́дуйся, Ми́лостивая, нас ми́лующая;","ра́дуйся, Домострої́тельнице, житіє́ на́ше до́брі устроя́ющая.","Ра́дуйся, руно́ ороше́нноє, є́же Гедео́н предви́ді;","ра́дуйся, блаже́нноє чре́во, невмісти́маго всі́ми Бо́га вмісти́вшеє.","Ра́дуйся, Неопали́мая Купино́;","ра́дуйся, Неруши́мая Стіно́.","Ра́дуйся, Живоно́сний Істо́чниче;","ра́дуйся, Цві́те Неув'яда́ємий.","Ра́дуйся, ум'ягче́ніє серде́ць злих;","ра́дуйся, умиле́ніє благи́х.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 9","ps":["Вся́кая жите́йськая в ми́рі сем сла́дость печа́лі бива́єть прича́стна: сла́ва не стої́ть, бога́тство мимотечеть, лі́пота і здра́віє ув'яда́ють, дру́зі і іскренії сме́ртію от'ємлються. Услади́ у́бо на́ша ско́рби, благи́х Вино́вная, Твою́ нетлі́нную даю́щи ра́дость нам, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії недоумі́ють, ки́їми словеси́ скорб'я́щия і погибающия утіша́ти, но Сама́, Влади́чице, возглаго́ли сердця́м на́шим утіше́ніє, благода́ті Твоєя́ луча́ми о́блак ско́рби на́шея і мрак уни́нія разгоня́ющи, да взива́єм Ті:","Ра́дуйся, обра́довавшая наді́янієм на Тя всіх христия́н;","ра́дуйся, Ра́досте і умире́ніє ми́ру.","Ра́дуйся, Пода́тельнице Боже́ственния бла́гости;","ра́дуйся, Наде́ждо благ ві́чних.","Ра́дуйся, кораблю́ хотя́щих спасти́ся;","ра́дуйся, приста́нище жите́йських пла́ваній.","Ра́дуйся, ві́рная Храни́тельнице упова́ющих на Тя по Бо́зі;","ра́дуйся, оде́ждо наги́х дерзнове́нія.","Ра́дуйся, Храни́тельнице всіх і утвержде́ніє;","ра́дуйся, всіх ві́рних огражде́ніє і свяще́нноє прибі́жище.","Ра́дуйся, по́моще ві́рно моля́щихся Тебі́;","ра́дуйся, сві́тлоє благода́ті позна́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 10","ps":["Спасти́ хотя́й род челові́чеський от ві́чния муки́ і непрестаю́щия ско́рби, Человіколю́бець Госпо́дь в присноді́вственную утро́бу Твою́ всели́ся і Тебі́, Ма́тер Свою́, дарова́ погиба́ющим в по́мощ, покро́в і защище́ніє, да бу́деши печа́льним утіше́ніє, погибшим взиска́ніє, скорб'я́щим ра́дованіє, отча́янним наде́жда, ві́чния муки́ Свої́м хода́тайством ізбавля́ющая і к Небе́сному весе́лію приводя́щая всіх, ві́рно вопію́щих Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і всім к Твоєму́ покро́ву прибегающим. Ті́мже мо́лим Тя: заступи́, покри́й і соблюди́ всіх погиба́ющих і безпомо́щних от іскуше́ній, озлобле́ній і бід, Тебі́ с любо́вію взива́ющих:","Ра́дуйся, сто́лпе ді́вства;","ра́дуйся, чистоти́ і цілому́дрія сосу́де ізбра́нний.","Ра́дуйся, воїнствующим на плоть цілому́дрієм ізря́дноє вінча́ніє;","ра́дуйся, во і́ночестві благоскорб'ящим Пода́тельнице ві́чнаго ра́дованія.","Ра́дуйся, пла́мень страсте́й ізміня́ющая;","ра́дуйся, мрак іскуше́ній прогоня́ющая.","Ра́дуйся, Наста́внице цілому́дрія;","ра́дуйся, чистоти́ огражде́ніє.","Ра́дуйся, челові́ков ісправле́ніє;","ра́дуйся, Є́юже от паде́нія на́шего возстахом.","Ра́дуйся, тве́рдоє ві́ри утвержде́ніє;","ра́дуйся, прия́тноє моли́тви кади́ло.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим Ті, раби́ Твої́, Богоро́дице, я́ко всеси́льній Засту́пнице ро́да на́шего. Утоли́ болі́зні к Тебі́ прибіга́ющих, укроти́ гнів Бо́жий, пра́ведно на ни дви́жимий гріх ра́ди на́ших, ізба́ви нас от вся́кия лю́тия ско́рби і поги́белі, вопію́щих о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная свіща́, угле́м благода́ті Бо́жия возжже́нная, яви́ся нам пречестна́я іко́на Твоя́, Влади́чице, на освяще́ніє на́ше і утіше́ніє. Ми же, любо́вію чту́ще ю і с ві́рою припа́дающе к ней, вопіє́м Ті:","Ра́дуйся, си́льним Твої́м заступле́нієм от всіх бід нас ізбавля́ющая;","ра́дуйся, от тру́са і пото́па нас защища́ющая.","Ра́дуйся, от гла́да душе́внаго і тіле́снаго нас снабдіва́ющая;","ра́дуйся, огнь росо́ю моли́тв Твої́х угаша́ющая.","Ра́дуйся, от сме́ртнаго губи́тельства нас спаса́ющая;","ра́дуйся, в бра́ніх крі́пкая Помо́щнице.","Ра́дуйся, от наше́ствія іноплеме́нних нас огражда́ющая;","ра́дуйся, от междоусо́бния бра́ні охраня́ющая.","Ра́дуйся, пла́вающих ле́гкоє по вода́м прехожде́ніє;","ра́дуйся, путеше́ствующих до́брая Води́тельнице.","Ра́дуйся, плі́нних свобожде́ніє;","ра́дуйся, от належа́щаго пра́веднаго преще́нія Бо́жия ско́роє ізбавле́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 12","ps":["Благода́ті зало́г восхоті́вши да́ти ро́ду на́шему, цільбоно́сную іко́ну Твою́ яви́ла єси́ нам, Богома́ти, от нея́же то́ки чуде́с с ві́рою приходящим істоча́ються, неду́зі врачу́ються і ско́рби утоля́ються. Сего́ ра́ди ра́достно о Тебі́ вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ ми́лості і чудеса́, Богороди́тельнице, хва́лим Тя всі, я́ко тве́рдую Предста́тельницю на́шу, і со умиле́нієм поклоня́ємся Тебі́, моля́щейся о нас, і про́сим: воздви́гни ру́ці к Си́ну Твоєму́, да в сей жи́зні і по сме́рті на́шей милосе́рдіє Єго́ неотсту́пно бу́деть от нас, взива́ющих Ті:","Ра́дуйся, непости́дноє на́ше упова́ніє в житії́ і по преставле́нії на́шем;","ра́дуйся, уповающим на Тя ми́рен коне́ць житія́ сего́ подаю́щая.","Ра́дуйся, в день су́дний на́ша Наде́ждо і Защище́ніє;","ра́дуйся, Судії́ Пра́веднаго умоле́ніє.","Ра́дуйся, геєни ві́чния ізбавле́ніє;","ра́дуйся, Наде́ждо ві́чнаго спасе́нія.","Ра́дуйся, ключу́ Ца́рствія Христо́ва;","ра́дуйся, две́ре ра́йськая.","Ра́дуйся, мо́сте, к Небесе́м преводя́й;","ра́дуйся, всіх ка́ющихся грі́шников прибі́жище і Блага́я Засту́пнице.","Ра́дуйся, А́нгелов Ра́досте;","ра́дуйся, всіх пра́ведних Сла́во і Утіше́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 13","ps":["О Всепі́тая Богообра́дованная Ма́ти, ро́ждшая на ра́дость Не́бу і землі́ Царя́ Христа́, Бо́га на́шего! Усли́ши глас скорб'я́щих раб Твої́х і, приє́мши сіє́ ма́лоє моле́ніє на́ше, ізба́ви нас от вся́ких бід, скорбе́й і напа́стей, неду́ги на́ша ісціли́, клевети́ потреби́, вся́ку зло́бу і вражду́ отжени́ от нас і бу́дущия ізми́ муки́ о Тебі́ вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть с Небесе́ рещи́ Богоро́дице: ра́дуйся, Благослове́нная в жена́х, предрече́нная Ма́ти Христа́, Си́на Бо́жия. Ті́мже і ми, гріхми́ обремене́ннії, наде́жду спасе́нія в Тебі́ улучи́вше, уми́льно взива́єм Ті:","Ра́дуйся, Бо́жиє ко грі́шним благоволе́ніє;","ра́дуйся, ка́ющихся пред Го́сподем Бо́гом крі́пкоє заступле́ніє.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє;","ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, гріхо́вную от'ємлющая скве́рну;","ра́дуйся, ба́не, омива́ющая со́вість.","Ра́дуйся, ро́ждшая Ізба́вителя, беззако́нія на́ша ми́лостиво очища́ющаго;","ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє.","Ра́дуйся, мо́сте, воі́стину преводя́й нас от сме́рти к животу́;","ра́дуйся, мир от пото́па гріхо́внаго спа́сшая.","Ра́дуйся, лі́ствице небе́сная, Є́юже Госпо́дь к нам сни́де;","ра́дуйся, вина́ всіх обоже́нія.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді побіди́тельная, я́ко ізба́вльшеся от ві́чния сме́рти благода́тію от Тебе́ ро́ждшагося Христа́ Бо́га на́шего і Твої́м Ма́тернім пред Ним хода́тайством, благода́рственная воспису́єм Ті, раби́ Твої́, но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід і ско́рбних обстоя́ній свободи́, зову́щих:","Ра́дуйся, Благода́тная Богоро́дице Ді́во, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Млекопитательниця» (інший акафіст)","e":"Akathist to the Theotokos before her icon “The Milk-Giver” (another akathist)","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от дще́рей челові́чеських Ма́терію би́ти Христа́ Бо́га на́шего принесе́м от любве́ на́шея пі́сні хвале́бния; Ти же, Си́на Бо́жия неізрече́нно роди́вшая і, я́ко Младе́нця млеко́м пита́вшая, сохрани́ нас, пою́щих Тя, от обише́дших ни зол, скорбе́й і напа́стей, да зове́м Ті немо́лчно:","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци, во верте́п прини́кше і узрі́вше та́мо Ді́ву чи́стую, Си́на млеко́м пита́ющую, возопи́ша Тебі́, Благослове́нній:","Ра́дуйся, ро́ждшая ми́ра Творця́;","ра́дуйся, пита́ющая Пита́теля вселенной.","Ра́дуйся, пелена́ми повивающая Повива́ющаго не́бо о́блаки;","ра́дуйся, дла́ньми нося́щая на херуви́міх Носи́маго.","Ра́дуйся, я́ко Ді́тищ мал Тобо́ю роди́ся;","ра́дуйся, я́ко Младе́нець платущ і ми́рові ра́дость дая́й Тобо́ю в мир при́йде.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи Свята́я Ді́ва при пе́рсіх Свої́х Богомладе́нця лежа́ща, глаго́ла Єму́: ка́ко возмогу́ Тя пита́ти, Творця́ Моєго́, Єму́же вся во́їнства небе́сная вопію́ть: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мная вся твар недоразумеваєть, ка́ко Ді́ва пребива́єши і Младе́нця млеко́м пита́єши. Оба́че, неізрече́нному та́їнству сему́ ві́рующе, благогові́йно взива́єм:","Ра́дуйся, Ді́во небла́зная;","ра́дуйся, Діви́це прекра́сная.","Ра́дуйся, жен украше́ніє;","ра́дуйся, Ма́ти чи́стая.","Ра́дуйся, дів пра́вило;","ра́дуйся Благослове́нная в жена́х.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ Тя, Богоро́дице Ді́во, і подаде́ Ті крі́пость пови́ти і пита́ти, Єго́же всі конці́ землі́ велича́ють і пою́ть Єму́ піснь вели́кую: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я дерзнове́ніє ве́ліє к Рожде́нному от Тебе́, при́зри на ско́рби і біди́, нас обишедшия, умоли́ Питаємаго Тобо́ю за ни грі́шния і недосто́йния, да, ізба́вльшеся от лю́тих напа́стей, возглаго́лем Ті та́ко:","Ра́дуйся, ро́ждшая сладча́йшеє Утіше́ніє на́ше;","ра́дуйся, проізрасти́вшая Благославеннаго благода́тію.","Ра́дуйся, Ма́ти на́ша Всеблага́я;","ра́дуйся, ча́дами Твої́ми нас нарекшая.","Ра́дуйся, благонаде́жноє на́ше прибі́жище;","ра́дуйся ві́рних небу́рноє приста́нище.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 4","ps":["Бу́ря скорбе́й і напа́стей обдержи́ть ни, трепе́щем, да не потонем в мо́рі жите́йстім, но яви́ся нам, я́ко голуби́ця Но́єва, вітв наде́жди подаю́щи нам, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шащи жена́ благоразумная глаго́ли живота́ ві́чнаго, Сино́м Твої́м вещаємия, просла́ви Тя, вопію́щи Єму́: «Благослове́нно чре́во, носи́вшеє Тя, і сосця́, я́же єси́ ссал», ті́мже прийми́ і на́ша немощни́я похвали́ сицева́я:","Ра́дуйся, би́сере драги́й, всечу́дная Ма́ти;","ра́дуйся, ве́лія в жена́х.","Ра́дуйся, ві́тве присноцветущая;","ра́дуйся, животе́, приє́мляй Сокро́вище освяще́нія.","Ра́дуйся, ча́ше злата́я, Христа́, небе́сную Ма́нну нося́щая;","ра́дуйся, Хлі́бом Жи́зні нас возраждающая.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 5","ps":["Богоноснеї ру́ці Твої́, Всепі́тая, простри́ к нам немощни́м, воздви́гни нас уни́лих, спаси́ отча́янних, да в ра́дості душе́вній, ничи́мже смуща́ємій, вопіє́м Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів Тя в Ду́сі богоглаго́ливий Іса́їя, я́ко і́маши, Ді́ва су́щи, во чре́ві прия́ти Рожде́ннаго із Тебе́, возгласи́ Ті:","Ра́дуйся, Предві́чнаго ро́ждшая;","ра́дуйся, я́ко Тобо́ю с на́ми Бог бива́єть.","Ра́дуйся, проро́честв сбитіє́;","ра́дуйся, проро́ков весе́ліє.","Ра́дуйся, всего́ ми́ра ча́яніє;","ра́дуйся, ро́да на́шего утіше́ніє.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 6","ps":["Пропові́дници присноглаголемії Твоєго́ милосе́рдія суть чудеса́ многообра́зная, істочаємая от іко́ни Твоєя́ святи́я, я́же оби́льно нам дарова́ла єси́, да, покланя́ющеся Тебі́ і Богомладенцю Христу́, вопіє́м гла́си хвале́бними: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ во оби́телі Са́вви Освяще́ннаго, я́ко со́лнце світоза́рноє, всечестна́я іко́на Твоя́, Млекопита́тельниця імену́ємая, пред не́юже преподо́бний со і́ноки ви́ну прославля́ху Тя, вопію́ще:","Ра́дуйся, оби́телі на́шея пречу́дноє украше́ніє;","ра́дуйся, от враго́во ви́димих і неви́димих тве́рдоє заступле́ніє і защище́ніє.","Ра́дуйся, моле́ніям на́шим при́сно внемлющая;","ра́дуйся, проше́нія на́ша благоутро́бно приє́млющая.","Ра́дуйся, го́рестная воздиха́нія на́ша утишающая;","ра́дуйся, сле́зи на́ша отирающая.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 7","ps":["Хотя́ преподо́бний Са́вва отити в жизнь ві́чную, проро́чеськи рече́, я́ко по мно́зіх днех при́йдеть во оби́тель сію́ царе́в син, єму́ тезоимени́тий, сей при́йметь святу́ю іко́ну Влади́чиці во благослове́ніє і воспоє́ть ра́дуяся: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий уго́дник Са́вва, святи́тель Се́рбськия землі́, при́йде во оби́тель дре́внюю і прия́т по словесі́ єго́ святу́ю іко́ну і принесе́ ю на Го́ру Афо́нськую во оби́тель Хиландарськую, і всі насе́льници єя́ ра́достно взива́ху ко Влади́чице ми́ра:","Ра́дуйся, при́сно о нас грі́шних промишля́ющая;","ра́дуйся, ніколи́же нас грі́шних забивающая.","Ра́дуйся, ми́лость Твою́ тисящекратно во святи́х чудотво́рних іко́нах Твої́х обновля́ющая;","ра́дуйся, но́вая зна́менія щедро́т Твої́х ни́ні ізлива́ющая.","Ра́дуйся, лю́б'ящих і чту́щих Тя зіло́ возлюби́вшая;","ра́дуйся, моля́щих Ті ся ніколи́же посрамля́ющая.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до і недоразуміва́ємоє єсть неві́рним і суєму́дренним, ка́ко от іко́ни Твоєя́ чудеса́ істека́ють, ми же, многократними ми́лостьми в сем утвержденнії, пі́ти Го́споду Бо́гу, дарова́вшему такову́ю Помо́щницю ро́ду христия́нському, дерза́єм: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир ви́димий і неви́димий блажи́ть Тя, Богоро́дице Ді́во, я́ко усе́рдную Засту́пницю на́шу, при́сно помога́ющую нам, в мо́ре бід і скорбе́й погиба́ющим, да Тебі́, єди́ній на́шей Наде́жде, вопіє́м:","Ра́дуйся, Си́на Твоєго́ за нас грі́шних умоляющая;","ра́дуйся, в біда́х і обстоя́ніїх ско́ро помога́ющая.","Ра́дуйся, моле́ній на́ших ско́роє усли́шаніє;","ра́дуйся, го́рестей житія́ на́шего ві́рноє услажде́ніє.","Ра́дуйся, ві́ру на́шу укріпля́ющая;","ра́дуйся, крест жи́зні на́шея понести́ нам помога́ющая.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 9","ps":["Вся́ко ублажа́я Тя, Всеблага́я, Іоа́нн Дамаски́н рече́, я́ко удо́біє молча́ніє, не́же пі́ти Тя, но любо́вію понуждаємії, восхваля́єм Тя і поє́м Си́ну Твоєму́ піснь вели́кую: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствовати не хо́щем, но с любо́вію і слеза́ми притека́єм к Тебі́, я́ко Ма́тері чадолюбивей, і із глубини́ се́рдця вопіє́м:","Ра́дуйся, Ра́досте на́ша неізрече́нная;","ра́дуйся, Утіше́ніє на́ше несказа́нноє.","Ра́дуйся, домо́в на́ших огражде́ніє;","ра́дуйся, чад на́ших покро́ве.","Ра́дуйся, младе́нцев воспита́ніє;","ра́дуйся, ю́них от путе́й ги́бельних охране́ніє.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 10","ps":["Спасти́ всіх нас і хошещі і можещі, Пресвята́я Ді́во, а́ще прибіга́єм ко всечестно́му покро́ву Твоїму, сего́ ра́ди мо́лим Тя: ізба́ви нас от го́рких бід і скорбе́й, наше́дших на ни, привлеци́ се́рдця на́ша к благостному прибі́жищу і научи́ вопи́ти Бо́гу, із Тебе́ ро́ждшемуся: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну неруши́му Тя нариця́єм і ві́ми, я́ко і́стину глаго́лем, уві́діхом бо, я́ко зіло́ лю́биши род христия́нський, ми́лості і щедро́ти Твоя́ при́сно істоча́єши вопію́щим Тебі́:","Ра́дуйся, от сіте́й вра́жиїх нас охраня́ющая,","ра́дуйся от наві́та злих челові́к нас спаса́ющая.","Ра́дуйся, вражду́ сро́дник на́ших на любо́в пременяющая;","ра́дуйся, мир і тишину́ в дома́х на́ших сохраня́ющая.","Ра́дуйся, намереніям благи́м вспомоществующая;","ра́дуйся, сові́ти благи́я на се́рдці полага́ющая.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє принесо́ша Ті, Пренепоро́чная, проро́ци, предзревше безсі́менноє зача́тіє і рожде́ніє от Тебе́ Си́на Бо́жия, па́стиріє же і волсви́, ви́дівше Тя ро́ждшую і пита́ющую, і всі лю́діє Твої́ хва́лять Тя. Ві́руєм, я́ко до сконча́нія ві́ка не умо́лкнеть піснь хвале́бная от ро́да христия́нськаго Рожде́нному Тобо́ю: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́ло світоза́рноє Ти єси́, Пречи́стая, нам во тьмі гріхо́в і страсте́й погиба́ющим, просвіща́ющеє на́ші темнеї о́чі, се́рдце озаря́ющеє ви́сшим ра́зумом, пою́щеє Тя:","Ра́дуйся, Путь, І́стину і Жизнь ро́ждшая;","ра́дуйся, і́стинному Бо́гу нас вручающая.","Ра́дуйся, сві́том Єва́нгелія на́ша мра́чния душі́ озаря́ющая;","ра́дуйся, му́дрость ві́ка сего́ ні во что́же вміня́ющая.","Ра́дуйся, му́дрость превисочайшую, я́же єсть любо́в, в сердця́х на́ших насажда́ющая;","ра́дуйся, по́моще всім і во всем.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия яви́ся чу́дно в землі́ Украї́нській от подо́бія іко́ни Твоєя́ Млекопитательници пренесенния. Ті́мже і Гора́ Афо́нськая, і страна́ на́ша, ни́ні лю́ті стра́ждущая, оба́че на ми́лость Твою́ несуменно упова́ющая, вопію́ть милосе́рдому Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Тя, я́ко Спа́са на́шего роди́вшую, і пелена́ми пови́вшую, і млеко́м пита́вшую, упова́єм, я́ко ніко́єже Твоє́ проше́ніє безответно от Него́ пребу́деть, поне́же Сам Сладча́йший Ісу́с обіща́ Ті та́ко; іму́ще в сем тве́рдую наде́жду, восхваля́єм Тя, Отра́до і Утіше́ніє на́ше:","Ра́дуйся, лю́тия ско́рби в ра́дость претворя́ющая;","ра́дуйся, ожесточе́ніє серде́ць на́ших любо́вію Твоє́ю ум'ягча́ющая.","Ра́дуйся, люби́ти Бо́га і бли́жняго нас науча́ющая;","ра́дуйся, в ско́рбіх на́ших упова́ніє на Бо́га возлага́ти наставля́ющая.","Ра́дуйся, на́ша хла́дния моли́тви любо́вію Твоє́ю согріва́ющая;","ра́дуйся, моли́тви нас грі́шних і недосто́йних, я́ко ми́лостивая Ма́тер, приє́млющая.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 13","ps":["О Всехва́льная Богоро́дице Ді́во, на́шего Го́спода і Влади́ку млеко́м пита́вшая, не пре́зри сего́ ско́рбнаго моле́нія на́шего, но умоли́ Си́на Твоєго́, да да́руєть нам гріхо́в проще́ніє, болі́зней ісціле́ніє, да сохрани́ть нас от гла́да, мра́за, смертоно́сния я́зви, неча́янния сме́рти і от всіх бід і обстоя́ній, да ізба́вльшеся сих, ра́дующеся зове́м Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци, во верте́п прини́кше і узрі́вше та́мо Ді́ву чи́стую, Си́на млеко́м пита́ющую, возопи́ша Тебі́, Благослове́нній:","Ра́дуйся, ро́ждшая ми́ра Творця́;","ра́дуйся, пита́ющая Пита́теля вселенной.","Ра́дуйся, пелена́ми повивающая Повива́ющаго не́бо о́блаки;","ра́дуйся, дла́ньми нося́щая на херуви́міх Носи́маго.","Ра́дуйся, я́ко Ді́тищ мал Тобо́ю роди́ся;","ра́дуйся, я́ко Младе́нець платущ і ми́рові ра́дость дая́й Тобо́ю в мир при́йде.","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нній от дще́рей челові́чеських Ма́терію би́ти Христа́ Бо́га на́шего принесе́м от любве́ на́шея пі́сні хвале́бния; Ти же, Си́на Бо́жия неізрече́нно роди́вшая і, я́ко Младе́нця млеко́м пита́вшая, сохрани́ нас, пою́щих Тя, от обише́дших ни зол, скорбе́й і напа́стей, да зове́м Ті немо́лчно:","Ра́дуйся, Богоро́дице Ді́во Млекопита́тельниці, ми́лостію Твоє́ю нас при́сно пита́ющая."]},{"h":"Молитва","ps":["О Пресвята́я Госпоже́ Влади́чице на́ша Богоро́дице, Небе́сная на́ша Цари́це, млеко́м Христа́ Бо́га на́шего пита́вшая і нас недосто́йних і многогрі́шних Твоє́ю бога́тою ми́лостію пита́ющая, спаси́ і ізба́ви нас, грі́шних рабо́в Твої́х, от напра́сния клевети́, от вся́кия біди́ і напа́сти і внеза́пния сме́рті. Поми́луй нас в дневни́х часі́х, во у́тренних і вече́рніх і во вся́коє вре́м'я сохрани́ нас, стоя́щих, сідя́щих соблюди́ і на вся́ких путеіх ходя́щих і в ночних часі́х спя́щих покри́й і заступи́. Защити́ нас, Влади́чице Богоро́дице, от всіх на́ших враг ви́димих і неви́димих і от вся́каго зла́го обстоя́нія. На вся́ком мі́сті і на вся́коє вре́м'я бу́ди нам, Ма́ти Преблага́я, необори́мая стіна́ і крі́пкоє заступле́ніє, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Без сі́мене от Боже́ственнаго Ду́ха, / во́лею же О́тчею зачала́ єси́ Си́на Бо́жия, / от Отця́ без ма́тере пре́жде вік су́ща, / нас же ра́ди із Тебе́ без отця́ би́вша, / пло́тію родила́ єси́ / і Младе́нця млеко́м пита́ла єси́, / ті́мже не преста́й моли́ти // ізба́витися от бід душа́м на́шим."]},{"h":"Кондак, глас 5","ps":["Душ на́ших чу́вствія очи́стивше, / у́зрим на іко́ні та́їнство пресла́вноє, / Творця́ Вселе́нной і Го́спода ви́шніх сил, / во об'я́тіїх держи́ма і от сосцю́ Твоє́ю я́ко Младе́нця пита́єма, / і, со стра́хом і ра́достію покланя́ющеся Тебі́ / і ро́ждшемуся от Тебе́ Спа́су на́шему, воззове́м: // ра́дуйся, Влади́чице, жи́зні на́шея Пита́тельнице."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Млекопита́тельниці Спа́са на́шего, / і чтим о́браз Твой святи́й, / от него́же благода́ть ісціле́нія // нам при́сно подає́ши."]}],"notes":[]}];
export default D;
